window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch03"]={"id": "ch03", "title": "第三章 DNA的复制", "sub": "朱玉贤《现代分子生物学》第5版 · 教师课件逐页详解", "sub2": "半保留复制 · 复制酶系 · 复制方式 · 端粒", "modules": [{"i": 0, "name": "模块一：DNA复制概述与半保留复制", "slides": [{"i": 0, "sec": "DNA复制概述与半保留复制", "title": "本章内容框架 (p2)", "notes": "本页列出第三章DNA复制的整体学习框架，包括七个部分：DNA复制概述、复制的起点方向与半不连续复制、复制相关物质及复制叉、复制的主要方式、以大肠杆菌为例的复制过程、真核生物DNA复制特点，以及原核与真核生物复制的比较。该框架从基本概念到具体机制、从原核模型到真核特点层层递进，为后续深入学习奠定结构化的知识脉络。", "page": 2, "level": "了解", "img": "assets/img/ch03/p002.jpg", "anim": null, "fig": null, "points": ["第三章DNA复制整体框架包括七个部分：复制概述、起点方向与半不连续复制、复制相关物质及复制叉、复制主要方式、大肠杆菌复制过程、真核生物复制特点、原核与真核比较。", "学习脉络从基本概念到具体机制，从原核模型到真核特点，层层递进。", "该框架为后续深入学习奠定结构化知识脉络，需把握各部分的逻辑关系。"], "check": null, "cards": [{"front": "第三章DNA复制包括哪七个部分的学习框架？", "back": "①DNA复制概述；②复制的起点、方向与半不连续复制；③复制相关物质及复制叉；④复制的主要方式；⑤以大肠杆菌为例的复制过程；⑥真核生物DNA复制特点；⑦原核与真核生物复制的比较。", "mnemonic": "概起物方，大真比较", "useImg": false}]}, {"i": 1, "sec": "DNA复制概述与半保留复制", "title": "DNA复制概述引入 (p3)", "notes": "本页是第一节“DNA复制概述”的标题页，提示接下来将围绕DNA复制的定义、意义及其在遗传信息传递中的核心地位展开。DNA复制是生命延续的分子基础，保证遗传信息从亲代细胞准确传递给子代细胞，是中心法则中遗传信息流的第一环节，也是细胞分裂前必须完成的关键事件。", "page": 3, "level": "了解", "img": "assets/img/ch03/p003.jpg", "anim": null, "fig": null, "points": ["DNA复制是生命延续的分子基础，保证遗传信息从亲代细胞准确传递给子代细胞。", "DNA复制是中心法则中遗传信息流的第一环节。", "DNA复制是细胞分裂前必须完成的关键事件。"], "check": null, "cards": [{"front": "DNA复制在生命活动中的地位是什么？", "back": "DNA复制是生命延续的分子基础，保证遗传信息从亲代细胞准确传递给子代细胞，是中心法则中遗传信息流的第一环节，也是细胞分裂前必须完成的关键事件。", "mnemonic": "复制是中心法则的起点", "useImg": false}]}, {"i": 2, "sec": "DNA复制概述与半保留复制", "title": "中心法则 (p4)", "notes": "中心法则描述了遗传信息在生物大分子间传递的基本规律：DNA通过复制将遗传信息传给子代DNA，通过转录将信息传给RNA，再通过翻译合成蛋白质；某些病毒还存在RNA逆转录为DNA的现象。DNA复制处于中心法则的起点，只有复制准确进行，转录和翻译才有可靠的模板，从而维持物种遗传的稳定性。", "page": 4, "level": "掌握", "img": "assets/img/ch03/p004.jpg", "anim": null, "fig": null, "points": ["中心法则描述遗传信息在生物大分子间传递的基本规律：DNA通过复制传给子代DNA，通过转录传给RNA，再通过翻译合成蛋白质。", "某些病毒存在RNA逆转录为DNA的现象。", "DNA复制处于中心法则的起点，只有复制准确进行，转录和翻译才有可靠模板，从而维持物种遗传稳定性。"], "check": null, "cards": [{"front": "中心法则描述了怎样的遗传信息传递规律？", "back": "DNA通过复制传给子代DNA，通过转录传给RNA，再通过翻译合成蛋白质；某些病毒还存在RNA逆转录为DNA的现象。DNA复制处于中心法则的起点。", "mnemonic": "DNA→DNA（复制），DNA→RNA（转录），RNA→蛋白质（翻译），RNA→DNA（逆转录）", "useImg": false}]}, {"i": 3, "sec": "DNA复制概述与半保留复制", "title": "DNA复制的定义 (p5)", "notes": "DNA复制是指以亲代DNA分子为模板合成一个新的子代DNA分子的过程。复制发生在细胞分裂前的S期（真核）或细胞周期相应阶段（原核），通过碱基互补配对保证子代DNA与亲代DNA序列一致。复制的结果是使遗传信息在细胞分裂过程中得以忠实传递，是生物体生长、发育和繁殖的分子基础。", "page": 5, "level": "掌握", "img": "assets/img/ch03/p005.jpg", "anim": null, "fig": null, "points": ["DNA复制是指以亲代DNA分子为模板合成一个新的子代DNA分子的过程。", "复制发生在细胞分裂前的S期（真核）或细胞周期相应阶段（原核）。", "通过碱基互补配对保证子代DNA与亲代DNA序列一致。", "复制使遗传信息在细胞分裂过程中得以忠实传递，是生物体生长、发育和繁殖的分子基础。"], "check": null, "cards": [{"front": "DNA复制的定义是什么？", "back": "以亲代DNA分子为模板合成一个新的子代DNA分子的过程。发生在细胞分裂前的S期（真核），通过碱基互补配对保证子代DNA与亲代DNA序列一致。", "mnemonic": "以亲代DNA为模板，合成子代DNA", "useImg": false}]}, {"i": 4, "sec": "DNA复制概述与半保留复制", "title": "三种复制模型假说 (p6)", "notes": "关于DNA复制方式曾提出三种模型：弥散复制、半保留复制和全保留复制。三者都符合Watson-Crick双螺旋模型所预测的“遗传信息精确拷贝”要求，但它们在亲代链与子代链的分配方式上不同。半保留复制认为每个子代DNA一条链来自亲代、一条链为新合成；全保留复制认为亲代双链完整保留，子代双链全新合成；弥散复制则认为新旧片段随机分布。", "page": 6, "level": "理解", "img": "assets/img/ch03/p006.jpg", "anim": null, "fig": null, "points": ["关于DNA复制方式曾提出三种模型：弥散复制、半保留复制和全保留复制。", "三者都符合Watson-Crick双螺旋模型所预测的“遗传信息精确拷贝”要求，但亲代链与子代链的分配方式不同。", "半保留复制：每个子代DNA一条链来自亲代、一条链为新合成。", "全保留复制：亲代双链完整保留，子代双链全新合成。", "弥散复制：新旧片段随机分布。"], "check": null, "cards": [{"front": "关于DNA复制方式曾提出哪三种模型假说？", "back": "①弥散复制：新旧片段随机分布；②半保留复制：每个子代DNA一条链来自亲代、一条链为新合成；③全保留复制：亲代双链完整保留，子代双链全新合成。", "mnemonic": "弥散、半保留、全保留", "useImg": false}]}, {"i": 5, "sec": "DNA复制概述与半保留复制", "title": "Meselson-Stahl实验 (p7)", "notes": "1958年Matthew Meselson和Frank Stahl利用氯化铯密度梯度离心技术，以大肠杆菌为材料，通过15N标记亲代DNA，追踪复制后DNA在离心管中的密度位置，成功区分了三种复制模型。实验结果支持半保留复制：第一代全部为杂合密度DNA，第二代出现杂合密度和轻密度DNA各半，从而否定了全保留和弥散复制模型。", "page": 7, "level": "掌握", "img": "assets/img/ch03/p007.jpg", "anim": null, "fig": null, "points": ["1958年Meselson和Stahl利用氯化铯密度梯度离心技术，以大肠杆菌为材料，通过15N标记亲代DNA。", "追踪复制后DNA在离心管中的密度位置，成功区分了三种复制模型。", "实验结果支持半保留复制：第一代全部为杂合密度DNA，第二代出现杂合密度和轻密度DNA各半。", "该实验否定了全保留和弥散复制模型。"], "check": null, "cards": [{"front": "Meselson-Stahl实验用什么技术、什么材料、什么标记证明了半保留复制？", "back": "1958年Meselson和Stahl利用氯化铯密度梯度离心技术，以大肠杆菌为材料，通过15N标记亲代DNA，追踪复制后DNA的密度位置，成功区分三种复制模型，结果支持半保留复制。", "mnemonic": "15N标记+CsCl密度梯度离心+大肠杆菌", "useImg": false}]}, {"i": 6, "sec": "DNA复制概述与半保留复制", "title": "Meselson-Stahl实验示意图 (p8)", "notes": "本页为示意图，展示Meselson-Stahl密度梯度离心实验的原理与结果。图中通常包括：亲代DNA在15N培养基中标记后为重密度；转入14N培养基复制一代后，所有DNA为一条重链一条轻链的杂合密度；复制两代后，一半为杂合密度、一半为轻密度。该图直观说明了半保留复制过程中亲代链的分配方式，是证明半保留复制的经典证据。", "page": 8, "level": "掌握", "img": "assets/img/ch03/p008.jpg", "anim": null, "fig": "图中通常展示离心管中DNA条带的位置：从上到下依次为轻密度、杂合密度、重密度。亲代只有重密度带；第一代只有杂合密度带；第二代出现杂合密度和轻密度带各半。通过条带位置和比例可判断复制方式。", "points": ["Meselson-Stahl实验利用密度梯度离心区分不同密度的DNA。", "亲代DNA在15N培养基中标记后为重密度。", "转入14N培养基复制一代后，所有DNA为一条重链一条轻链的杂合密度。", "复制两代后，一半为杂合密度、一半为轻密度。", "该图直观说明了半保留复制过程中亲代链的分配方式，是证明半保留复制的经典证据。"], "check": null, "cards": [{"front": "Meselson-Stahl实验中第一代和第二代DNA的密度分布如何？", "back": "第一代全部为杂合密度DNA（一条重链一条轻链）；第二代出现杂合密度和轻密度DNA各半。从而否定了全保留和弥散复制模型。", "mnemonic": "一代全杂合，二代杂合轻各半", "useImg": false}]}, {"i": 7, "sec": "DNA复制概述与半保留复制", "title": "半保留复制示意图 (p9)", "notes": "本页为示意图，展示DNA半保留复制的过程。亲代双链解开后，每条链分别作为模板，按碱基互补配对原则合成新链，形成两个子代DNA分子，每个子代DNA均由一条亲代链和一条新合成链组成。该图强调了复制过程中碱基配对的特异性与模板作用，是理解半保留复制机制的核心图示。", "page": 9, "level": "掌握", "img": "assets/img/ch03/p009.jpg", "anim": null, "fig": "图中展示亲代DNA双链解开，分别以两条亲代链为模板，按A-T、G-C配对合成新链。结果两个子代DNA分子各含一条亲代链（旧链）和一条新合成链（新链），直观体现半保留复制。", "points": ["半保留复制过程中，亲代双链解开后，每条链分别作为模板。", "按碱基互补配对原则合成新链，形成两个子代DNA分子。", "每个子代DNA均由一条亲代链和一条新合成链组成。", "该图强调复制过程中碱基配对的特异性与模板作用，是理解半保留复制机制的核心图示。"], "check": null, "cards": [{"front": "半保留复制的过程是怎样的？", "back": "亲代双链解开后，每条链分别作为模板，按碱基互补配对原则合成新链，形成两个子代DNA分子，每个子代DNA均由一条亲代链和一条新合成链组成。", "mnemonic": "双链解开，各为模板，一旧一新", "useImg": false}]}, {"i": 8, "sec": "DNA复制概述与半保留复制", "title": "半保留复制的定义与基础 (p10)", "notes": "半保留复制是指以亲代DNA双链为模板，以碱基互补方式合成子代DNA，在新形成的子代DNA中，一条链来自亲代DNA，另一条链是新合成的。其分子基础是G-C、A-T的严格配对：一条链上的核苷酸排列即可决定另一条链的核苷酸排列，从而保证遗传信息精确复制。这一方式由Meselson和Stahl实验证实，是DNA复制的基本规律。", "page": 10, "level": "掌握", "img": "assets/img/ch03/p010.jpg", "anim": null, "fig": null, "points": ["半保留复制是指以亲代DNA双链为模板，以碱基互补方式合成子代DNA。", "在新形成的子代DNA中，一条链来自亲代DNA，另一条链是新合成的。", "其分子基础是G-C、A-T的严格配对：一条链上的核苷酸排列即可决定另一条链的核苷酸排列。", "这一方式由Meselson和Stahl实验证实，是DNA复制的基本规律。"], "check": null, "cards": [{"front": "半保留复制的定义及其分子基础是什么？", "back": "定义：以亲代DNA双链为模板，以碱基互补方式合成子代DNA，子代DNA中一条链来自亲代，另一条链是新合成的。分子基础：G-C、A-T的严格配对，一条链的核苷酸排列决定另一条链的排列，保证遗传信息精确复制。", "mnemonic": "一旧一新，碱基互补是基础", "useImg": false}]}, {"i": 9, "sec": "DNA复制概述与半保留复制", "title": "复制相关的基本问题 (p11)", "notes": "本页提出DNA复制研究中的几个核心问题：哪些酶参与复制及其功能；长双螺旋DNA如何在不发生缠结的情况下解旋复制；复制如何起始；如何沿染色体推进；如何终止；以及如何保证细胞分裂前只进行一轮复制。这些问题贯穿复制机制的学习，涉及解旋酶、拓扑异构酶、聚合酶等多种因子的协同作用，以及复制起点、复制叉、终止子和复制许可等调控机制。", "page": 11, "level": "理解", "img": "assets/img/ch03/p011.jpg", "anim": null, "fig": null, "points": ["DNA复制研究中的核心问题包括：哪些酶参与复制及其功能。", "长双螺旋DNA如何在不发生缠结的情况下解旋复制。", "复制如何起始、如何沿染色体推进、如何终止。", "如何保证细胞分裂前只进行一轮复制。", "这些问题涉及解旋酶、拓扑异构酶、聚合酶等多种因子的协同作用，以及复制起点、复制叉、终止子和复制许可等调控机制。"], "check": null, "cards": [{"front": "DNA复制研究中的核心基本问题有哪些？", "back": "①哪些酶参与复制及其功能；②长双螺旋DNA如何在不缠结情况下解旋复制；③复制如何起始；④如何沿染色体推进；⑤如何终止；⑥如何保证细胞分裂前只进行一轮复制。", "mnemonic": "酶、解旋、起始、推进、终止、只复制一轮", "useImg": false}]}, {"i": 10, "sec": "DNA复制概述与半保留复制", "title": "DNA复制总览与一般特征 (p12)", "notes": "本页概括DNA复制的一般特征与参与因子。复制具有半保留性、从复制起点起始、双向进行等特点；复制机器包括聚合酶、解旋酶、引发酶、拓扑异构酶等，分别负责合成、解旋、引物合成和消除拓扑张力。前导链连续合成，后随链不连续合成；起始蛋白参与复制起始调控，端粒酶则解决真核线性染色体末端复制问题。这些内容构成复制机制的整体框架。", "page": 12, "level": "掌握", "img": "assets/img/ch03/p012.jpg", "anim": null, "fig": null, "points": ["DNA复制具有半保留性、从复制起点起始、双向进行等特点。", "复制机器包括聚合酶、解旋酶、引发酶、拓扑异构酶等，分别负责合成、解旋、引物合成和消除拓扑张力。", "前导链连续合成，后随链不连续合成。", "起始蛋白参与复制起始调控，端粒酶则解决真核线性染色体末端复制问题。"], "check": null, "cards": [{"front": "DNA复制的一般特征及参与因子有哪些？", "back": "特征：半保留性、从复制起点起始、双向进行；前导链连续合成，后随链不连续合成。参与因子：聚合酶（合成）、解旋酶（解旋）、引发酶（引物合成）、拓扑异构酶（消除拓扑张力）、起始蛋白（起始调控）、端粒酶（解决真核线性染色体末端复制问题）。", "mnemonic": "半保留、起点起始、双向进行；聚解引拓，起端辅助", "useImg": false}]}, {"i": 11, "sec": "DNA复制概述与半保留复制", "title": "DNA复制的速度、完整性与准确性 (p13)", "notes": "DNA复制具有快速、完整和准确三大特征。原核生物复制速度约100-1000 bp/秒，真核生物约25-50 bp/秒；复制必须覆盖基因组中几乎每一个碱基对，保证完整性；同时复制高度准确，合成过程中通常每10^10个碱基才出现一个错误。这种准确性依赖于碱基互补配对、聚合酶的校对功能以及错配修复系统等多重保障，对维持基因组稳定性至关重要。", "page": 13, "level": "掌握", "img": "assets/img/ch03/p013.jpg", "anim": null, "fig": null, "points": ["DNA复制具有快速、完整和准确三大特征。", "原核生物复制速度约100-1000 bp/秒，真核生物约25-50 bp/秒。", "复制必须覆盖基因组中几乎每一个碱基对，保证完整性。", "复制高度准确，合成过程中通常每10^10个碱基才出现一个错误。", "准确性依赖于碱基互补配对、聚合酶的校对功能以及错配修复系统等多重保障，对维持基因组稳定性至关重要。"], "check": null, "cards": [{"front": "DNA复制的速度、完整性与准确性如何？", "back": "速度：原核约100-1000 bp/秒，真核约25-50 bp/秒；完整性：必须覆盖基因组中几乎每一个碱基对；准确性：通常每10^10个碱基才出现一个错误，依赖碱基互补配对、聚合酶校对功能和错配修复系统。", "mnemonic": "快（原核100-1000，真核25-50）、全（覆盖每个碱基）、准（10^10分之一错误）", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_1", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "DNA半保留复制是指子代DNA分子中：", "o": ["A. 两条链均来自亲代DNA", "B. 一条链来自亲代DNA，另一条链为新合成", "C. 两条链均为新合成", "D. 亲代链和新链随机分布"], "a": "B", "e": "半保留复制中，亲代双链解开，每条链作为模板合成新链，因此每个子代DNA由一条亲代链和一条新合成链组成。", "kp": "ch03_s0_7"}, {"id": "ch03_mcq_2", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "Meselson和Stahl证明DNA半保留复制所采用的关键技术是：", "o": ["A. X射线衍射", "B. 氯化铯密度梯度离心", "C. 琼脂糖凝胶电泳", "D. 电子显微镜观察"], "a": "B", "e": "他们用15N标记DNA，通过氯化铯密度梯度离心区分不同密度的DNA，从而证明复制为半保留方式。", "kp": "ch03_s0_5"}, {"id": "ch03_mcq_3", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "关于DNA复制的一般特征，下列哪项描述正确？", "o": ["A. 原核生物复制速度比真核生物慢", "B. 复制只发生在基因组的部分区域", "C. 复制具有高保真性，错误率极低", "D. 复制不需要引物"], "a": "C", "e": "DNA复制高度准确，通常每10^10个碱基才出现一个错误；原核复制速度约100-1000 bp/秒，真核约25-50 bp/秒，且复制几乎覆盖全基因组，并需要引物。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_4", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "下列哪种酶在DNA复制中负责解开双螺旋？", "o": ["A. DNA聚合酶", "B. 解旋酶", "C. 引发酶", "D. 端粒酶"], "a": "B", "e": "解旋酶负责解开DNA双螺旋，暴露单链模板；聚合酶合成DNA，引发酶合成引物，端粒酶延长真核染色体末端。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_5", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "DNA复制过程中，后随链的合成特点是：", "o": ["A. 连续合成", "B. 不连续合成，形成多个冈崎片段", "C. 不需要模板", "D. 从3'→5'方向合成"], "a": "B", "e": "后随链的合成方向与解旋方向相反，因此以不连续方式合成，形成多个冈崎片段，再连接成完整链。", "kp": "ch03_s0_10"}], "judge": [{"id": "ch03_judge_1", "modI": 0, "q": "DNA复制是中心法则中遗传信息流的第一环节，只有复制准确进行，转录和翻译才有可靠的模板。", "a": "对", "e": "中心法则描述遗传信息在生物大分子间传递的基本规律：DNA通过复制将遗传信息传给子代DNA，通过转录将信息传给RNA，再通过翻译合成蛋白质；DNA复制处于中心法则的起点。", "kp": "ch03_s0_2"}, {"id": "ch03_judge_2", "modI": 0, "q": "Meselson-Stahl实验第一代DNA全部为轻密度DNA，第二代出现杂合密度和轻密度DNA各半。", "a": "错", "e": "第一代全部为杂合密度DNA（一条重链一条轻链），第二代出现杂合密度和轻密度DNA各半。", "kp": "ch03_s0_5"}], "fill": [{"id": "ch03_fill_1", "modI": 0, "q": "DNA复制是指以________为模板合成一个新的子代DNA分子的过程，复制发生在细胞分裂前的________期（真核）。", "a": "亲代DNA分子,S", "kp": "ch03_s0_3"}, {"id": "ch03_fill_2", "modI": 0, "q": "1958年Meselson和Stahl利用________技术，以大肠杆菌为材料，通过________标记亲代DNA，追踪复制后DNA在离心管中的密度位置，实验结果支持________复制。", "a": "氯化铯密度梯度离心,15N,半保留", "kp": "ch03_s0_5"}], "short": [{"id": "ch03_short_1", "modI": 0, "q": "简述DNA半保留复制的定义及其分子基础，并说明Meselson-Stahl实验如何证明半保留复制。", "a": "定义：以亲代DNA双链为模板，以碱基互补方式合成子代DNA，在新形成的子代DNA中，一条链来自亲代DNA，另一条链是新合成的。分子基础：G-C、A-T的严格配对，一条链上的核苷酸排列即可决定另一条链的核苷酸排列，从而保证遗传信息精确复制。Meselson-Stahl实验：1958年利用氯化铯密度梯度离心技术，以大肠杆菌为材料，通过15N标记亲代DNA，追踪复制后DNA在离心管中的密度位置；第一代全部为杂合密度DNA，第二代出现杂合密度和轻密度DNA各半，从而否定了全保留和弥散复制模型，支持半保留复制。", "kp": "ch03_s0_6"}], "calc": [], "term": [{"id": "ch03_term_1", "modI": 0, "term": "Semi-conservative replication", "def": "半保留复制：以亲代DNA双链为模板，按碱基互补配对合成子代DNA；每个子代DNA分子中一条链来自亲代，另一条链为新合成；由Meselson-Stahl实验证实；是DNA复制的基本规律。", "kp": "ch03_s0_5"}]}, {"i": 1, "name": "模块二：复制的起点、方向与半不连续复制", "slides": [{"i": 0, "sec": "DNA复制的起点、方向与半不连续复制", "title": "DNA复制的起点、方向和半不连续复制(p14)", "notes": "本页是第三章“DNA的复制”中模块二的总起页，提示接下来要讨论三个核心问题：复制的起点（origin）、复制的方向（双向还是单向）以及半不连续复制机制。DNA复制并非随机开始，而是从特定起点启动，并沿特定方向进行；由于DNA双链反向平行且DNA聚合酶只能沿5′→3′方向合成，复制叉两条模板链的合成方式必然不同，从而引出前导链与后随链、冈崎片段等概念。这些内容是理解复制准确性和高效性的基础。", "page": 14, "level": "掌握", "img": "assets/img/ch03/p014.jpg", "anim": null, "fig": null, "points": ["DNA复制从特定起点（origin）启动，而非随机开始", "复制方向需判断是双向还是单向", "DNA聚合酶只能沿5′→3′方向合成，双链反向平行导致两条模板链合成方式不同", "引出前导链、后随链、冈崎片段等核心概念"], "check": null, "cards": [{"front": "DNA复制需要讨论的三个核心问题是什么？", "back": "复制的起点、复制的方向、半不连续复制机制。", "mnemonic": "起、向、断（起点—方向—半不连续）", "useImg": false}, {"front": "什么是冈崎片段？原核与真核的冈崎片段长度有何差异？", "back": "冈崎片段是后随链上不连续合成的小片段，由冈崎令治和冈崎恒子等1968年提出。原核生物约2000 nt，真核生物约100~200 nt。后随链先合成许多短片段，再由DNA连接酶等连接成完整链。", "mnemonic": "冈崎小片段，原核长真核短，连接酶来缝合", "useImg": false}]}, {"i": 1, "sec": "复制起点", "title": "复制起点与真核多起点复制(p15)", "notes": "复制起点（origin，ori）是DNA分子上约100~300 bp、具有专一核苷酸顺序的片段，可被特异蛋白识别并启动复制。原核生物通常只有一个复制起始位点，如大肠杆菌oriC全长245 bp，且在细菌中高度保守。真核生物每条染色体含多个复制子、多个复制起点，一个细胞周期中可激活约5万~10万个起点。多起点策略使庞大的真核基因组能在较短时间内完成复制，也便于复制调控与检查点监控。", "page": 15, "level": "掌握", "img": "assets/img/ch03/p015.jpg", "anim": null, "fig": null, "points": ["复制起点是约100~300 bp、具专一核苷酸顺序的DNA片段，可被特异蛋白识别", "原核生物通常只有一个复制起始位点，如大肠杆菌oriC全长245 bp且高度保守", "真核生物每条染色体含多个复制起点，一个细胞周期激活约5万~10万个起点", "多起点策略使真核庞大基因组能在S期较短时间内完成复制"], "check": null, "cards": [{"front": "复制起点（ori）是什么？原核与真核的起点数量有何差异？", "back": "复制起点是约100~300 bp、具专一核苷酸顺序、可被特异蛋白识别并启动复制的片段。原核通常只有一个（如大肠杆菌oriC 245 bp，高度保守）；真核每条染色体有多个复制子、多个起点，一个细胞周期可激活约5万~10万个起点。", "mnemonic": "原核一灶起火，真核万点齐燃", "useImg": false}]}, {"i": 2, "sec": "复制子", "title": "复制子：复制起点到终点的复制单位(p16)", "notes": "复制子（replicon）指从复制起点到复制终点所组成的一个独立复制单位，一个复制子只含一个复制起点。原核生物染色体、噬菌体通常只有一个复制子；真核生物染色体由多个复制子组成，哺乳动物细胞约有50,000~100,000个复制子，每个复制子长约50~200 kb。关键调控特征是：每个复制子在一个细胞周期中只能复制一次，从而保证基因组DNA的精确倍性，避免重复复制导致基因扩增或不稳定。", "page": 16, "level": "掌握", "img": "assets/img/ch03/p016.jpg", "anim": null, "fig": null, "points": ["复制子是从复制起点到复制终点的独立复制单位，一个复制子只含一个复制起点", "原核生物染色体、噬菌体通常只有一个复制子", "真核生物染色体由多个复制子组成，哺乳动物约50,000~100,000个，每个长约50~200 kb", "每个复制子在一个细胞周期中只能复制一次，保证基因组精确倍性"], "check": null, "cards": [{"front": "真核生物为什么采用多起点复制？", "back": "真核基因组庞大，多起点策略使染色体能在较短时间内完成复制，也便于复制调控与检查点监控。", "mnemonic": "基因组大，多点开工才赶得上S期", "useImg": false}]}, {"i": 3, "sec": "真核染色体多复制子复制", "title": "真核线形染色体的多起点双向复制(p17)", "notes": "该页为示意图，表达真核线形染色体由多个复制子构成，每个复制子都有自己的复制起点。复制时表现为多点起始、双向复制，即从每个起点向两侧形成两个复制叉；相邻复制子的复制叉最终相遇并汇合，完成整条染色体的复制。这种组织方式使真核生物巨大的线形染色体能在S期内高效复制，同时每个复制子只复制一次，保证遗传信息稳定传递。", "page": 17, "level": "掌握", "img": "assets/img/ch03/p017.jpg", "anim": null, "fig": "图中展示一条线形染色体上分布多个复制起点，每个起点向左右两侧形成复制叉；相邻复制叉相遇汇合处即为复制终点。看图的重点是识别多点起始、双向复制以及汇合完成整条染色体复制的过程。", "points": ["真核线形染色体由多个复制子构成，每个复制子有自己的复制起点", "复制表现为多点起始、双向复制，每个起点向两侧形成两个复制叉", "相邻复制子的复制叉最终相遇并汇合，完成整条染色体复制", "该方式保证真核巨大线形染色体在S期内高效复制且每个复制子只复制一次"], "check": null, "cards": [{"front": "什么是复制子（replicon）？原核与真核的复制子数量有何不同？", "back": "复制子是从复制起点到复制终点组成的一个独立复制单位，一个复制子只含一个复制起点。原核染色体、噬菌体通常只有一个复制子；真核染色体由多个复制子组成，哺乳动物细胞约有50,000~100,000个复制子，每个长约50~200 kb。", "mnemonic": "一子一原点，真核多子分段复制", "useImg": false}]}, {"i": 4, "sec": "复制叉", "title": "复制叉：Y形DNA结构(p18)", "notes": "复制叉（replication fork）是DNA复制时解链酶等解开双链后形成的复制点，因形状呈叉状而得名，也称Y形DNA结构。复制叉处进行模板链解旋、引物合成、DNA聚合酶延伸及后随链加工等反应。复制叉可沿DNA向一个或两个方向移动；真核生物多复制子通常双向复制，形成两个移动方向相反的复制叉。复制叉的稳定与重启对基因组完整性至关重要，复制叉停滞会触发DNA损伤应答。", "page": 18, "level": "掌握", "img": "assets/img/ch03/p018.jpg", "anim": null, "fig": null, "points": ["复制叉是解链酶等解开双链后形成的复制点，呈Y形结构", "复制叉处进行模板链解旋、引物合成、DNA聚合酶延伸及后随链加工", "复制叉可沿DNA向一个或两个方向移动，真核多复制子通常双向复制", "复制叉的稳定与重启对基因组完整性至关重要，停滞会触发DNA损伤应答"], "check": null, "cards": [{"front": "复制子调控的关键特征是什么？为什么重要？", "back": "每个复制子在一个细胞周期中只能复制一次。这保证基因组DNA的精确倍性，避免重复复制导致基因扩增或不稳定。", "mnemonic": "一周期一次，防多复制", "useImg": false}]}, {"i": 5, "sec": "复制方向与半不连续复制", "title": "5′→3′方向与半不连续复制(p19)", "notes": "该页为示意图，核心是DNA合成沿5′→3′方向进行，并因此表现为半不连续复制。由于DNA双链反向平行，而DNA聚合酶只能将新核苷酸加到3′-OH末端，所以复制叉处一条模板链可连续合成前导链，另一条模板链只能反向、分段合成后随链。图中通常标出前导链和后随链，以及复制叉移动方向。该机制解释了为什么复制叉整体向前，但两条新链的合成方式不同。", "page": 19, "level": "掌握", "img": "assets/img/ch03/p019.jpg", "anim": null, "fig": "图中通常标出复制叉移动方向、前导链和后随链；前导链合成方向与复制叉移动方向一致，后随链则反向分段合成。看图重点是理解双链反向平行与5′→3′合成方向如何共同导致半不连续复制。", "points": ["DNA合成沿5′→3′方向进行，DNA聚合酶只能将新核苷酸加到3′-OH末端", "DNA双链反向平行，导致复制叉处两条模板链合成方式不同", "一条模板链可连续合成前导链，另一条模板链反向分段合成后随链", "该机制即半不连续复制，解释了复制叉整体向前但两条新链合成方式不同"], "check": null, "cards": [{"front": "真核线形染色体的多起点双向复制是如何进行的？", "back": "每个复制子有自己的起点，从每个起点向两侧形成两个复制叉（双向复制）；相邻复制子的复制叉最终相遇并汇合，完成整条染色体复制。", "mnemonic": "多点起火，双向推进，叉叉相遇", "useImg": false}]}, {"i": 6, "sec": "半不连续复制模型", "title": "半不连续复制与冈崎片段(p20)", "notes": "半不连续复制指DNA复制过程中一条链连续合成，另一条链不连续合成。1968年，日本学者冈崎令治和冈崎恒子等提出该模型，并发现后随链上存在不连续的小片段，即冈崎片段。后随链先合成许多短片段，再由DNA连接酶等连接成完整链。该模型解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾，是DNA复制机制中的核心概念，在生物界具有普遍性。", "page": 20, "level": "掌握", "img": "assets/img/ch03/p020.jpg", "anim": null, "fig": null, "points": ["半不连续复制指一条链连续合成，另一条链不连续合成", "1968年冈崎令治和冈崎恒子等提出该模型并发现冈崎片段", "后随链先合成许多短片段（冈崎片段），再由DNA连接酶等连接成完整链", "该模型解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾", "半不连续复制在生物界具有普遍性，是DNA复制机制的核心概念"], "check": null, "cards": [{"front": "什么是复制叉？其结构特点和功能是什么？", "back": "复制叉是DNA复制时解链酶等解开双链后形成的复制点，呈Y形（Y形DNA结构）。此处进行模板链解旋、引物合成、DNA聚合酶延伸及后随链加工等反应。复制叉可沿DNA向一个或两个方向移动；真核多复制子通常双向复制，形成两个移动方向相反的复制叉。", "mnemonic": "Y形叉口，解旋合成加工一条龙", "useImg": false}]}, {"i": 7, "sec": "前导链、后随链与冈崎片段", "title": "前导链、后随链和冈崎片段(p21)", "notes": "以复制叉移动方向为标准：前导链合成方向与复制叉移动方向一致，可连续合成；后随链合成方向与复制叉移动方向相反，随复制叉前进不断形成不连续片段，再连接成完整DNA链。这些不连续片段称为冈崎片段，原核生物可达约2000 nt，真核生物约100~200 nt。冈崎片段在生物界具有普遍性，反映了DNA聚合酶只能5′→3′合成以及双链反向平行所决定的半不连续复制机制。", "page": 21, "level": "掌握", "img": "assets/img/ch03/p021.jpg", "anim": null, "fig": null, "points": ["以复制叉移动方向为标准：前导链合成方向与复制叉移动方向一致，可连续合成", "后随链合成方向与复制叉移动方向相反，不断形成不连续片段再连接", "不连续片段称为冈崎片段，原核生物约2000 nt，真核生物约100~200 nt", "冈崎片段在生物界具有普遍性，反映DNA聚合酶只能5′→3′合成及双链反向平行决定的半不连续复制机制"], "check": null, "cards": [{"front": "为什么DNA复制是半不连续复制？前导链和后随链有何区别？", "back": "DNA双链反向平行，而DNA聚合酶只能沿5′→3′方向合成（加到3′-OH末端）。因此复制叉处一条模板链可连续合成前导链（方向与复制叉移动方向一致）；另一条模板链只能反向、分段合成后随链（方向与复制叉移动方向相反），先形成冈崎片段再连接成完整链。", "mnemonic": "同向连续前导，反向分段后随", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_6", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "关于复制起点（origin，ori）的叙述，正确的是：", "o": ["A. 原核生物染色体通常有多个复制起点，真核生物只有一个", "B. 复制起点是约100~300 bp、可被特异蛋白识别并启动复制的DNA片段", "C. 复制起点就是复制子，一个复制子可含多个复制起点", "D. 真核生物复制起点在每个细胞周期中可被多次激活"], "a": "B", "e": "复制起点是约100~300 bp、具有专一序列并可被特异蛋白识别启动复制的片段。原核通常一个起点，真核有多个；一个复制子只含一个复制起点；真核每个复制子一个细胞周期只复制一次。", "kp": "ch03_s1_1"}, {"id": "ch03_mcq_7", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "真核生物线形染色体复制时，通常表现为：", "o": ["A. 单起点、单向复制", "B. 单起点、双向复制", "C. 多起点、双向复制，复制叉最终汇合", "D. 多起点、单向复制，复制叉不汇合"], "a": "C", "e": "真核染色体由多个复制子构成，每个复制子有自己的起点，表现为多点起始、双向复制，相邻复制叉最终汇合完成整条染色体复制。", "kp": "ch03_s1_3"}, {"id": "ch03_mcq_8", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "冈崎片段是指：", "o": ["A. 前导链上连续合成的DNA片段", "B. 后随链上不连续合成的5′→3′小片段", "C. 复制起点被识别后形成的RNA引物", "D. 复制叉解链后形成的Y形DNA结构"], "a": "B", "e": "冈崎片段是后随链断续合成产生的5′→3′不连续小片段，原核可达约2000 nt，真核约100~200 nt，随后被连接成完整链。", "kp": "ch03_s1_6"}, {"id": "ch03_mcq_9", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "DNA复制表现为半不连续复制，根本原因主要是：", "o": ["A. DNA双链反向平行，且DNA聚合酶只能沿5′→3′方向合成", "B. DNA聚合酶只能沿3′→5′方向合成", "C. 复制起点只能单向启动复制", "D. 真核生物染色体只有一个复制子"], "a": "A", "e": "DNA双链反向平行，而DNA聚合酶只能将核苷酸加到3′-OH端，即沿5′→3′延伸，因此一条链连续合成，另一条链必须分段合成。", "kp": "ch03_s1_0"}, {"id": "ch03_mcq_10", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "关于前导链和后随链，叙述正确的是：", "o": ["A. 前导链合成方向与复制叉移动方向相反，后随链相同", "B. 前导链连续合成，后随链不连续合成并形成冈崎片段", "C. 前导链和后随链都完全连续合成", "D. 后随链不需要引物即可起始合成"], "a": "B", "e": "前导链合成方向与复制叉移动方向一致，可连续合成；后随链方向相反，需不断起始并形成冈崎片段，再连接成完整链。", "kp": "ch03_s1_7"}], "judge": [{"id": "ch03_judge_3", "modI": 1, "q": "原核生物通常只有一个复制起始位点，而真核生物每条染色体含多个复制子、多个复制起点。", "a": "对", "e": "原核生物通常只有一个复制起始位点，如大肠杆菌oriC；真核生物每条染色体含多个复制子、多个复制起点，一个细胞周期中可激活约5万~10万个起点。", "kp": "ch03_s1_1"}, {"id": "ch03_judge_4", "modI": 1, "q": "冈崎片段是前导链上连续合成的小片段，原核生物可达约2000 nt，真核生物约100~200 nt。", "a": "错", "e": "冈崎片段是后随链上不连续合成的小片段，原核生物可达约2000 nt，真核生物约100~200 nt。", "kp": "ch03_s1_7"}], "fill": [{"id": "ch03_fill_3", "modI": 1, "q": "复制起点是DNA分子上约________ bp、具有专一核苷酸顺序的片段，可被特异蛋白识别并启动复制；大肠杆菌oriC全长________ bp，且在细菌中高度保守。", "a": "100~300,245", "kp": "ch03_s1_1"}, {"id": "ch03_fill_4", "modI": 1, "q": "复制子指从复制起点到复制终点所组成的一个独立复制单位，一个复制子只含________个复制起点；哺乳动物细胞约有________个复制子，每个复制子长约________ kb。", "a": "一,50000~100000,50~200", "kp": "ch03_s1_2"}, {"id": "ch03_fill_5", "modI": 1, "q": "由于DNA双链反向平行且DNA聚合酶只能沿________方向合成，复制叉两条模板链的合成方式不同，从而引出________链与________链、冈崎片段等概念。", "a": "5′→3′,前导,后随", "kp": "ch03_s1_0"}], "short": [{"id": "ch03_short_2", "modI": 1, "q": "简述DNA复制中前导链和后随链的合成特点，并解释半不连续复制的原因。", "a": "前导链：合成方向与复制叉移动方向一致，可连续合成。后随链：合成方向与复制叉移动方向相反，随复制叉前进不断形成不连续片段（冈崎片段），再连接成完整DNA链。半不连续复制的原因：DNA双链反向平行，而DNA聚合酶只能将新核苷酸加到3′-OH末端，即只能沿5′→3′方向合成；因此复制叉处一条模板链可连续合成前导链，另一条模板链只能反向、分段合成后随链。该机制解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾。", "kp": "ch03_s1_0"}], "calc": [], "term": [{"id": "ch03_term_2", "modI": 1, "term": "Origin of replication (ori)", "def": "复制起点：DNA分子上约100~300 bp、具有专一核苷酸顺序的片段；可被特异蛋白识别并启动复制；原核生物通常只有一个，如大肠杆菌oriC全长245 bp且高度保守；真核生物每条染色体含多个复制起点。", "kp": "ch03_s1_4"}, {"id": "ch03_term_3", "modI": 1, "term": "Replicon", "def": "复制子：从复制起点到复制终点所组成的一个独立复制单位；一个复制子只含一个复制起点；原核生物染色体、噬菌体通常只有一个复制子；真核生物染色体由多个复制子组成，哺乳动物细胞约有50,000~100,000个复制子，每个长约50~200 kb；每个复制子在一个细胞周期中只能复制一次。", "kp": "ch03_s1_2"}, {"id": "ch03_term_4", "modI": 1, "term": "Replication fork", "def": "复制叉：DNA复制时解链酶等解开双链后形成的复制点；因形状呈叉状而得名，也称Y形DNA结构；复制叉处进行模板链解旋、引物合成、DNA聚合酶延伸及后随链加工等反应；可沿DNA向一个或两个方向移动；真核生物多复制子通常双向复制，形成两个移动方向相反的复制叉。", "kp": "ch03_s1_4"}, {"id": "ch03_term_5", "modI": 1, "term": "Semi-discontinuous replication", "def": "半不连续复制：DNA复制过程中一条链连续合成，另一条链不连续合成；前导链合成方向与复制叉移动方向一致，可连续合成；后随链合成方向与复制叉移动方向相反，随复制叉前进不断形成不连续片段，再连接成完整DNA链；由冈崎令治和冈崎恒子等提出并发现冈崎片段；解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾。", "kp": "ch03_s1_4"}, {"id": "ch03_term_6", "modI": 1, "term": "Okazaki fragments", "def": "冈崎片段：后随链上不连续合成的小片段；原核生物可达约2000 nt，真核生物约100~200 nt；后随链先合成许多短片段，再由DNA连接酶等连接成完整链；在生物界具有普遍性，反映了DNA聚合酶只能5′→3′合成以及双链反向平行所决定的半不连续复制机制。", "kp": "ch03_s1_7"}]}, {"i": 2, "name": "模块三：DNA复制相关物质（起始与辅助蛋白）", "slides": [{"i": 0, "sec": "DNA复制相关物质", "title": "DNA复制相关物质总览 (p22)", "notes": "本页是第三章“DNA的复制”中模块三的开篇，提出DNA复制并非单一酶能完成，而是由多种物质协同参与的复杂过程。复制机器（replication machinery）包括底物dNTPs、模板DNA、解旋酶、单链结合蛋白、引物酶、引物、拓扑异构酶和DNA聚合酶等。理解这些组分的分工与协作，是掌握DNA复制机制的基础。", "page": 22, "level": "掌握", "img": "assets/img/ch03/p022.jpg", "anim": null, "fig": null, "points": ["DNA复制由多种物质协同完成，不是单一酶能完成的过程", "复制机器包括底物dNTPs、模板DNA、解旋酶、单链结合蛋白、引物酶、引物、拓扑异构酶和DNA聚合酶等", "理解各组分分工与协作是掌握DNA复制机制的基础"], "check": null, "cards": [{"front": "DNA复制机器（replication machinery）包括哪些主要组分？", "back": "底物dNTPs、模板DNA、解旋酶、单链结合蛋白、引物酶、引物、拓扑异构酶和DNA聚合酶等。", "mnemonic": "底模解单引，拓扑聚合酶", "useImg": false}]}, {"i": 1, "sec": "DNA复制相关物质", "title": "DNA复制机器组成示意图 (p23)", "notes": "本页为示意图，综合展示DNA复制叉处多种蛋白与DNA的相互作用：解旋酶在复制叉前方解开双链，单链结合蛋白稳定暴露的单链，拓扑异构酶缓解超螺旋张力，引物酶合成RNA引物，DNA聚合酶沿模板延伸新链。该图直观说明复制是一个多组分协同的“分子机器”过程，各因子在时间和空间上精密配合。", "page": 23, "level": "理解", "img": "assets/img/ch03/p023.jpg", "anim": null, "fig": "看图中复制叉处各蛋白的相对位置：解旋酶位于叉前方解链，单链结合蛋白覆盖暴露单链，拓扑异构酶在叉前方缓解张力，引物酶与DNA聚合酶在模板上延伸新链。", "points": ["复制叉处多种蛋白与DNA相互作用，构成多组分协同的分子机器", "解旋酶在复制叉前方解开双链，单链结合蛋白稳定暴露的单链", "拓扑异构酶缓解超螺旋张力，引物酶合成RNA引物，DNA聚合酶沿模板延伸新链", "各因子在时间和空间上精密配合"], "check": null, "cards": [{"front": "为什么说DNA复制是一个多组分协同的“分子机器”过程？", "back": "复制叉处解旋酶、SSBP、拓扑异构酶、引物酶、DNA聚合酶等在时间和空间上精密配合，共同完成复制。", "mnemonic": "", "useImg": false}]}, {"i": 2, "sec": "3.1 dNTPs", "title": "四种脱氧核苷三磷酸 dNTPs (p24)", "notes": "dNTPs即dATP、dTTP、dCTP、dGTP，是DNA合成的直接底物。每个dNTP由脱氧核糖、碱基和三个磷酸基团组成。复制时，DNA聚合酶催化dNTP的α-磷酸与新生链3′-OH形成磷酸二酯键，同时释放焦磷酸。dNTP既提供能量又提供核苷酸单元，其种类和浓度直接影响复制速度与保真度。", "page": 24, "level": "掌握", "img": "assets/img/ch03/p024.jpg", "anim": null, "fig": null, "points": ["dNTPs即dATP、dTTP、dCTP、dGTP，是DNA合成的直接底物", "每个dNTP由脱氧核糖、碱基和三个磷酸基团组成", "DNA聚合酶催化dNTP的α-磷酸与新生链3′-OH形成磷酸二酯键，同时释放焦磷酸", "dNTP既提供能量又提供核苷酸单元，其种类和浓度影响复制速度与保真度"], "check": null, "cards": [{"front": "四种脱氧核苷三磷酸（dNTPs）分别是什么？由哪三部分组成？", "back": "dATP、dTTP、dCTP、dGTP；每个由脱氧核糖、碱基和三个磷酸基团组成。", "mnemonic": "A T C G，糖碱三磷酸", "useImg": false}]}, {"i": 3, "sec": "3.1 dNTPs", "title": "复制过程中dNTP的添加 (p25)", "notes": "本页说明dNTP如何被添加到延伸中的DNA链上。DNA聚合酶以模板链为指导，选择与模板互补的dNTP，将其α-磷酸与引物或新生链游离3′-OH结合，形成3′,5′-磷酸二酯键，并释放PPi。该反应需要Mg2+参与，且遵循碱基互补配对原则，从而保证子链序列与模板准确对应。", "page": 25, "level": "掌握", "img": "assets/img/ch03/p025.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶以模板链为指导，选择与模板互补的dNTP", "dNTP的α-磷酸与引物或新生链游离3′-OH结合，形成3′,5′-磷酸二酯键并释放PPi", "该反应需要Mg2+参与", "遵循碱基互补配对原则，保证子链序列与模板准确对应"], "check": null, "cards": [{"front": "dNTP在DNA合成中起什么作用？", "back": "既是DNA合成的直接底物提供核苷酸单元，又通过释放焦磷酸提供能量；其种类和浓度影响复制速度与保真度。", "mnemonic": "", "useImg": false}]}, {"i": 4, "sec": "3.2 Template", "title": "模板：亲代DNA两条链 (p26)", "notes": "DNA复制以亲代DNA的两条链分别作为模板。由于碱基互补配对，每条亲代链都能指导合成一条互补子链，最终形成两个与亲代序列相同的DNA分子。这种以两条链分别作模板的方式称为半保留复制，保证了遗传信息在细胞分裂过程中准确传递，是DNA复制最核心的原则之一。", "page": 26, "level": "掌握", "img": "assets/img/ch03/p026.jpg", "anim": null, "fig": null, "points": ["DNA复制以亲代DNA的两条链分别作为模板", "每条亲代链指导合成一条互补子链，最终形成两个与亲代序列相同的DNA分子", "这种以两条链分别作模板的方式称为半保留复制", "半保留复制保证遗传信息在细胞分裂过程中准确传递，是DNA复制最核心的原则之一"], "check": null, "cards": [{"front": "DNA聚合酶如何将dNTP添加到延伸中的DNA链上？", "back": "以模板链为指导选择互补dNTP，将其α-磷酸与新生链游离3′-OH结合形成3′,5′-磷酸二酯键，释放PPi，需Mg2+参与，遵循碱基互补配对。", "mnemonic": "α磷酸接3′羟基，放焦磷酸需镁离子", "useImg": false}]}, {"i": 5, "sec": "3.3 DNA helicase", "title": "DNA解旋酶/解链酶 (p27)", "notes": "DNA解旋酶是促进DNA双链分开的酶，它利用ATP水解提供的能量破坏碱基对间的氢键，使双螺旋在复制叉处解开。解旋酶沿DNA链移动，不断暴露单链模板，为后续引物合成和DNA聚合酶延伸创造条件。没有解旋酶，复制叉无法推进，DNA复制不能启动和持续。", "page": 27, "level": "掌握", "img": "assets/img/ch03/p027.jpg", "anim": null, "fig": null, "points": ["DNA解旋酶是促进DNA双链分开的酶", "利用ATP水解提供的能量破坏碱基对间的氢键，使双螺旋在复制叉处解开", "解旋酶沿DNA链移动，不断暴露单链模板，为引物合成和DNA聚合酶延伸创造条件", "没有解旋酶，复制叉无法推进，DNA复制不能启动和持续"], "check": null, "cards": [{"front": "DNA复制以什么为模板？这种方式叫什么？", "back": "以亲代DNA的两条链分别作为模板；称为半保留复制，保证遗传信息准确传递。", "mnemonic": "两条亲代链，各做一模板", "useImg": false}]}, {"i": 6, "sec": "3.4 SSBP", "title": "单链结合蛋白 SSBP (p28)", "notes": "单链结合蛋白在复制过程中与暴露的DNA单链结合，防止两条单链重新退火或形成链内二级结构，并保护单链不被核酸酶降解。SSBP与DNA结合无序列专一性，可覆盖较长单链；它还能增强DNA聚合酶对单链DNA的亲和力，并与其他复制蛋白如解旋酶协同作用，促进复制顺利进行。", "page": 28, "level": "掌握", "img": "assets/img/ch03/p028.jpg", "anim": null, "fig": null, "points": ["单链结合蛋白与暴露的DNA单链结合，防止两条单链重新退火或形成链内二级结构", "保护单链不被核酸酶降解", "与DNA结合无序列专一性，可覆盖较长单链", "增强DNA聚合酶对单链DNA的亲和力，并与其他复制蛋白如解旋酶协同作用"], "check": null, "cards": [{"front": "DNA解旋酶的功能是什么？能量来源是什么？", "back": "利用ATP水解提供的能量破坏碱基对间氢键，使双螺旋在复制叉处解开，暴露单链模板，推动复制叉前进。", "mnemonic": "解旋酶，ATP供能拆氢键", "useImg": false}]}, {"i": 7, "sec": "3.5 Primase", "title": "引物酶 Primase (p29)", "notes": "引物酶以DNA为模板合成一段短RNA，为DNA聚合酶提供起始所需的3′-OH末端。其本质是以DNA为模板的RNA聚合酶，不需要引物即可起始合成。由于细胞内RNA引物易被降解，通常难以观察到完整引物，但它在复制起始中不可或缺，尤其在滞后链上需反复合成多个引物。", "page": 29, "level": "掌握", "img": "assets/img/ch03/p029.jpg", "anim": null, "fig": null, "points": ["引物酶以DNA为模板合成一段短RNA，为DNA聚合酶提供起始所需的3′-OH末端", "其本质是以DNA为模板的RNA聚合酶，不需要引物即可起始合成", "细胞内RNA引物易被降解，通常难以观察到完整引物", "在复制起始中不可或缺，尤其在滞后链上需反复合成多个引物"], "check": null, "cards": [{"front": "单链结合蛋白（SSBP）的作用有哪些？", "back": "与暴露的DNA单链结合，防止重新退火或形成二级结构，保护单链不被核酸酶降解，增强DNA聚合酶对单链DNA的亲和力，并与解旋酶等协同作用。", "mnemonic": "防退火、防降解、助聚合", "useImg": false}]}, {"i": 8, "sec": "3.6 Primer", "title": "引物 Primer (p30)", "notes": "DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH。引物通常是一段短RNA链，能与模板DNA的一条链互补配对，其3′-OH作为DNA聚合酶的起点。复制完成后，RNA引物被切除并由DNA填补，最终由连接酶连接成完整DNA链。引物机制保证了DNA合成的高效与准确起始。", "page": 30, "level": "掌握", "img": "assets/img/ch03/p030.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH", "引物通常是一段短RNA链，能与模板DNA的一条链互补配对", "引物的3′-OH作为DNA聚合酶的起点", "复制完成后RNA引物被切除并由DNA填补，最终由连接酶连接成完整DNA链"], "check": null, "cards": [{"front": "引物酶（Primase）的本质和功能是什么？", "back": "本质是以DNA为模板的RNA聚合酶，不需要引物即可起始合成；合成一段短RNA引物，为DNA聚合酶提供起始所需的3′-OH末端。", "mnemonic": "引物酶，DNA模板做RNA", "useImg": false}]}, {"i": 9, "sec": "3.7 DNA Topoisomerase", "title": "DNA拓扑异构酶 (p31)", "notes": "DNA拓扑异构酶在复制过程中调节DNA的拓扑状态，使双螺旋保持松弛，避免解旋时产生过度超螺旋张力而阻碍复制叉前进。I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶。拓扑异构酶保证复制、转录等过程正常进行，是维持基因组稳定性的关键酶类。", "page": 31, "level": "掌握", "img": "assets/img/ch03/p031.jpg", "anim": null, "fig": null, "points": ["DNA拓扑异构酶调节DNA的拓扑状态，使双螺旋保持松弛", "避免解旋时产生过度超螺旋张力而阻碍复制叉前进", "I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶", "拓扑异构酶保证复制、转录等过程正常进行，是维持基因组稳定性的关键酶类"], "check": null, "cards": [{"front": "为什么DNA聚合酶需要引物？引物最终如何处理？", "back": "DNA聚合酶不能从头起始合成，必须依赖引物提供游离3′-OH；引物通常为短RNA链，复制完成后被切除并由DNA填补，最后由连接酶连接成完整DNA链。", "mnemonic": "聚合酶不能从头起，引物提供3′-OH", "useImg": false}]}, {"i": 10, "sec": "DNA复制相关物质", "title": "拓扑异构酶作用示意图 (p32)", "notes": "本页为示意图，展示拓扑异构酶如何通过切断和重新连接DNA骨架来释放超螺旋张力。在复制叉前方，解旋酶解开双链会导致正超螺旋积累，拓扑异构酶通过瞬时切断单链或双链、旋转并重新连接，使DNA恢复松弛状态。该图说明拓扑异构酶是复制叉顺利推进的重要辅助因子。", "page": 32, "level": "理解", "img": "assets/img/ch03/p032.jpg", "anim": null, "fig": "看图中复制叉前方正超螺旋的积累，以及拓扑异构酶如何切断DNA骨架、旋转后重新连接，使DNA恢复松弛状态。", "points": ["拓扑异构酶通过切断和重新连接DNA骨架来释放超螺旋张力", "复制叉前方解旋酶解开双链会导致正超螺旋积累", "拓扑异构酶通过瞬时切断单链或双链、旋转并重新连接，使DNA恢复松弛状态", "拓扑异构酶是复制叉顺利推进的重要辅助因子"], "check": null, "cards": [{"front": "DNA拓扑异构酶在复制中的作用是什么？I型和II型有何区别？", "back": "调节DNA拓扑状态，使双螺旋保持松弛，避免解旋产生过度超螺旋张力阻碍复制叉前进；I型切开单链改变连接数，II型切开双链且需消耗能量（如细菌促旋酶）。", "mnemonic": "I型切单链，II型切双链耗能", "useImg": false}]}, {"i": 11, "sec": "3.8 DNA Polymerase", "title": "DNA聚合酶 DNA Polymerase (p33)", "notes": "DNA聚合酶以DNA为模板催化dNTP合成DNA，由Arthur Kornberg在大肠杆菌中发现，又称Kornberg酶。其反应需要四个条件：dNTPs、带游离3′-OH的模板-引物、DNA聚合酶本身以及Mg2+。Mg2+优化酶活性。该酶只能沿5′→3′方向延伸，并具有校对功能，是DNA复制最核心的酶。", "page": 33, "level": "掌握", "img": "assets/img/ch03/p033.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶以DNA为模板催化dNTP合成DNA，由Arthur Kornberg在大肠杆菌中发现，又称Kornberg酶", "反应需要四个条件：dNTPs、带游离3′-OH的模板-引物、DNA聚合酶本身以及Mg2+", "Mg2+优化酶活性", "该酶只能沿5′→3′方向延伸，并具有校对功能，是DNA复制最核心的酶"], "check": null, "cards": [{"front": "DNA聚合酶（Kornberg酶）催化反应需要哪四个条件？其延伸方向和校对功能如何？", "back": "需要dNTPs、带游离3′-OH的模板-引物、DNA聚合酶本身以及Mg2+；只能沿5′→3′方向延伸，并具有校对功能。", "mnemonic": "底物、引物、酶、镁；5′→3′延伸能校对", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_11", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "DNA复制中，直接作为底物被DNA聚合酶添加到新生链上的物质是：", "o": ["A. NTPs", "B. dNTPs", "C. dNDPs", "D. 单磷酸脱氧核苷"], "a": "B", "e": "DNA聚合酶以四种脱氧核苷三磷酸（dATP、dTTP、dCTP、dGTP）为底物，释放焦磷酸并提供延伸所需能量。", "kp": "ch03_s2_0"}, {"id": "ch03_mcq_12", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "关于单链结合蛋白（SSBP）的功能，下列哪项不正确？", "o": ["A. 防止单链退火形成双链", "B. 保护单链不被降解", "C. 具有序列专一性结合", "D. 可增强DNA聚合酶对单链DNA的亲和力"], "a": "C", "e": "SSBP与DNA结合时无序列专一性，可覆盖单链，防止退火和降解，并增强DNA聚合酶亲和力。", "kp": "ch03_s2_6"}, {"id": "ch03_mcq_13", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "引物酶（Primase）在DNA复制中的主要作用是：", "o": ["A. 以DNA为模板合成一段RNA引物", "B. 以RNA为模板合成DNA", "C. 切除RNA引物并填补DNA", "D. 解开DNA双螺旋"], "a": "A", "e": "引物酶本质是以DNA为模板的RNA聚合酶，合成短RNA引物，为DNA聚合酶提供3′-OH起点。", "kp": "ch03_s2_7"}, {"id": "ch03_mcq_14", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "DNA拓扑异构酶在复制过程中的主要功能是：", "o": ["A. 催化dNTP聚合", "B. 使DNA螺旋保持松弛，避免拓扑张力阻碍复制", "C. 合成RNA引物", "D. 结合单链DNA防止降解"], "a": "B", "e": "拓扑异构酶通过切断和重新连接DNA链，释放解旋产生的超螺旋张力，保证复制叉正常推进。", "kp": "ch03_s2_9"}, {"id": "ch03_mcq_15", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "Kornberg发现的DNA聚合酶催化DNA合成时，下列哪项不是必需条件？", "o": ["A. dNTPs", "B. 带游离3′-OH的模板-引物", "C. Mg2+", "D. 高能磷酸化合物如ATP"], "a": "D", "e": "DNA聚合酶反应需要dNTPs、模板-引物、DNA聚合酶和Mg2+；dNTP本身提供能量，不需额外ATP。", "kp": "ch03_s2_11"}], "judge": [{"id": "ch03_judge_5", "modI": 2, "q": "DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH。", "a": "对", "e": "DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH；引物通常是一段短RNA链，能与模板DNA的一条链互补配对，其3′-OH作为DNA聚合酶的起点。", "kp": "ch03_s2_8"}, {"id": "ch03_judge_6", "modI": 2, "q": "DNA拓扑异构酶I型切开双链且需消耗能量，II型酶切开单链并改变连接数。", "a": "错", "e": "I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶。", "kp": "ch03_s2_9"}], "fill": [{"id": "ch03_fill_6", "modI": 2, "q": "dNTPs即dATP、dTTP、dCTP、dGTP，是DNA合成的直接底物；复制时，DNA聚合酶催化dNTP的________磷酸与新生链3′-OH形成磷酸二酯键，同时释放________。", "a": "α,焦磷酸", "kp": "ch03_s2_2"}], "short": [{"id": "ch03_short_3", "modI": 2, "q": "简述DNA复制相关物质（复制机器）的主要组成及其功能。", "a": "复制机器包括：底物dNTPs，提供核苷酸单元和能量；模板DNA，亲代DNA两条链分别作为模板；解旋酶，利用ATP水解能量破坏氢键，解开双螺旋；单链结合蛋白，与暴露的单链结合，防止重新退火或形成二级结构，并保护单链；引物酶，以DNA为模板合成短RNA引物，提供3′-OH；引物，提供游离3′-OH作为DNA聚合酶起点；拓扑异构酶，调节DNA拓扑状态，释放超螺旋张力；DNA聚合酶，以DNA为模板催化dNTP合成DNA，并具有校对功能。各因子在时间和空间上精密配合，协同完成复制。", "kp": "ch03_s2_0"}], "calc": [], "term": [{"id": "ch03_term_7", "modI": 2, "term": "DNA helicase", "def": "DNA解旋酶/解链酶：促进DNA双链分开的酶；利用ATP水解提供的能量破坏碱基对间的氢键，使双螺旋在复制叉处解开；沿DNA链移动，不断暴露单链模板，为后续引物合成和DNA聚合酶延伸创造条件；没有解旋酶，复制叉无法推进，DNA复制不能启动和持续。", "kp": "ch03_s2_11"}, {"id": "ch03_term_8", "modI": 2, "term": "Single-strand binding protein (SSBP)", "def": "单链结合蛋白：在复制过程中与暴露的DNA单链结合；防止两条单链重新退火或形成链内二级结构；保护单链不被核酸酶降解；与DNA结合无序列专一性，可覆盖较长单链；增强DNA聚合酶对单链DNA的亲和力，并与其他复制蛋白如解旋酶协同作用，促进复制顺利进行。", "kp": "ch03_s2_6"}, {"id": "ch03_term_9", "modI": 2, "term": "Primase", "def": "引物酶：以DNA为模板合成一段短RNA，为DNA聚合酶提供起始所需的3′-OH末端；其本质是以DNA为模板的RNA聚合酶，不需要引物即可起始合成；由于细胞内RNA引物易被降解，通常难以观察到完整引物，但它在复制起始中不可或缺，尤其在滞后链上需反复合成多个引物。", "kp": "ch03_s2_7"}, {"id": "ch03_term_10", "modI": 2, "term": "DNA topoisomerase", "def": "DNA拓扑异构酶：在复制过程中调节DNA的拓扑状态，使双螺旋保持松弛，避免解旋时产生过度超螺旋张力而阻碍复制叉前进；I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶；保证复制、转录等过程正常进行，是维持基因组稳定性的关键酶类。", "kp": "ch03_s2_11"}]}, {"i": 3, "name": "模块四：DNA聚合酶与DNA连接酶", "slides": [{"i": 0, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶催化磷酸二酯键形成 (p34)", "notes": "DNA聚合酶催化脱氧核糖3'-OH与dNTP的5'-磷酸之间形成磷酸二酯键，反应能量来自dNTP释放两个磷酸。聚合酶在延伸过程中能“找到”正确的互补dNTP，合成方向为5'→3'，速率可达800 dNTPs/秒，错误率极低，错误核苷酸掺入速率比正确者慢约10,000倍。这三大特征保证了DNA复制的高效性与保真性。", "page": 34, "level": "掌握", "img": "assets/img/ch03/p034.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶催化脱氧核糖3'-OH与dNTP的5'-磷酸之间形成磷酸二酯键", "反应能量来自dNTP释放两个磷酸（焦磷酸）", "合成方向为5'→3'，速率可达800 dNTPs/秒", "错误核苷酸掺入速率比正确者慢约10,000倍，保证高保真性"], "check": null, "cards": [{"front": "DNA聚合酶催化形成什么化学键？能量来自哪里？", "back": "催化脱氧核糖3'-OH与dNTP的5'-磷酸之间形成磷酸二酯键；能量来自dNTP释放两个磷酸。", "mnemonic": "3'羟基攻5'磷酸，dNTP掉两磷酸供能", "useImg": false}, {"front": "DNA连接酶的作用是什么？不能做什么？", "back": "催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键，封闭切口；不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口。", "mnemonic": "连切口不连游离单链；3'OH+5'磷酸成键", "useImg": false}]}, {"i": 1, "sec": "DNA聚合酶与DNA连接酶", "title": "原核生物DNA聚合酶的性质比较 (p35)", "notes": "大肠杆菌主要有DNA聚合酶Ⅰ、Ⅱ、Ⅲ。Pol Ⅰ具中等5'→3'聚合活性、3'→5'外切活性和5'→3'外切活性，主要切除RNA引物并填补空隙、修复损伤；Pol Ⅱ聚合活性很低，主要参与修复；Pol Ⅲ聚合活性很高，是复制主要酶，具3'→5'外切校对功能，提高保真性。三者功能分工体现了复制与修复的协调。", "page": 35, "level": "掌握", "img": "assets/img/ch03/p035.jpg", "anim": null, "fig": null, "points": ["大肠杆菌主要有DNA聚合酶Ⅰ、Ⅱ、Ⅲ三种", "Pol Ⅰ具5'→3'聚合、3'→5'外切和5'→3'外切活性，主要切除RNA引物、填补空隙、修复损伤", "Pol Ⅱ聚合活性很低，主要参与修复", "Pol Ⅲ聚合活性很高，是复制主要酶，具3'→5'外切校对功能", "三者功能分工体现复制与修复的协调"], "check": null, "cards": [{"front": "DNA聚合酶的合成方向、速率和保真性如何？", "back": "合成方向5'→3'，速率可达800 dNTPs/秒；错误率极低，错误核苷酸掺入速率比正确者慢约10,000倍。", "mnemonic": "五到三，八百速，错配慢万倍", "useImg": false}]}, {"i": 2, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶的手形结构 (p36)", "notes": "DNA聚合酶形似握持引物-模板接头的“手”，分为手掌、手指和拇指结构域。手掌区含催化中心，手指区识别并固定正确的dNTP，拇指区维持引物-模板位置。该结构解释了酶如何实现高选择性和持续合成，是理解聚合酶催化机制与保真性的结构基础。", "page": 36, "level": "理解", "img": "assets/img/ch03/p036.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶形似握持引物-模板接头的“手”，分为手掌、手指和拇指结构域", "手掌区含催化中心", "手指区识别并固定正确的dNTP", "拇指区维持引物-模板位置", "该结构是理解聚合酶高选择性和持续合成机制的结构基础"], "check": null, "cards": [{"front": "大肠杆菌DNA聚合酶Ⅰ、Ⅱ、Ⅲ的主要功能分工是什么？", "back": "Pol Ⅰ：切除RNA引物、填补空隙、修复损伤；Pol Ⅱ：聚合活性很低，主要参与修复；Pol Ⅲ：复制主要酶，具3'→5'外切校对功能。", "mnemonic": "Ⅰ切补修，Ⅱ弱修，Ⅲ主复制带校对", "useImg": false}]}, {"i": 3, "sec": "DNA聚合酶与DNA连接酶", "title": "3'→5'外切活性与校对 (p37)", "notes": "3'→5'外切活性是DNA聚合酶的校对功能：当错误核苷酸掺入新生链后，聚合酶可沿3'→5'方向切除错配核苷酸，再重新掺入正确核苷酸。该活性显著降低突变率，保证复制保真性。原核Pol Ⅰ、Ⅱ、Ⅲ均具此活性，真核复制型聚合酶也多具校对功能。", "page": 37, "level": "掌握", "img": "assets/img/ch03/p037.jpg", "anim": null, "fig": null, "points": ["3'→5'外切活性是DNA聚合酶的校对功能", "错误核苷酸掺入后，聚合酶沿3'→5'方向切除错配核苷酸，再重新掺入正确核苷酸", "该活性显著降低突变率，保证复制保真性", "原核Pol Ⅰ、Ⅱ、Ⅲ均具此活性，真核复制型聚合酶也多具校对功能"], "check": null, "cards": [{"front": "DNA聚合酶Ⅰ具有哪三种酶活性？", "back": "5'→3'聚合活性、3'→5'外切活性、5'→3'外切活性。", "mnemonic": "一聚两切：5'→3'聚，3'→5'切，5'→3'切", "useImg": false}]}, {"i": 4, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶Ⅰ的5'→3'外切活性与切口平移 (p38)", "notes": "DNA聚合酶Ⅰ具有5'→3'外切活性，可从切口处切除前方核苷酸，同时沿5'→3'方向合成新链，使切口沿DNA移动，称为切口平移。该特性在体外可用于DNA分子上引入放射性标记核苷酸，是分子杂交探针标记的经典技术，也参与体内RNA引物切除与空隙填补。", "page": 38, "level": "掌握", "img": "assets/img/ch03/p038.jpg", "anim": null, "fig": null, "points": ["DNA聚合酶Ⅰ具有5'→3'外切活性，可从切口处切除前方核苷酸", "同时沿5'→3'方向合成新链，使切口沿DNA移动，称为切口平移", "体外可用于DNA分子上引入放射性标记核苷酸，是分子杂交探针标记的经典技术", "体内参与RNA引物切除与空隙填补"], "check": null, "cards": [{"front": "DNA聚合酶的“手形结构”由哪几个结构域组成？各有什么功能？", "back": "手掌区含催化中心；手指区识别并固定正确dNTP；拇指区维持引物-模板位置。", "mnemonic": "掌催化，指选料，拇指夹稳引物模板", "useImg": false}]}, {"i": 5, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶Ⅲ的亚基组成与滑动钳 (p39)", "notes": "DNA聚合酶Ⅲ由多个亚基组成：核心酶含α（5'→3'聚合）、ε（3'→5'外切校对）、θ（组装核心酶并促进ε活性）；τ亚基连接核心酶与滑动钳装载器；δ、δ'等组成滑动钳装载器；β亚基形成环状滑动钳，作为持续合成因子。滑动钳环状结构使聚合酶不易脱落，极大提高持续合成能力。", "page": 39, "level": "掌握", "img": "assets/img/ch03/p039.jpg", "anim": null, "fig": null, "points": ["核心酶含α（5'→3'聚合）、ε（3'→5'外切校对）、θ（组装核心酶并促进ε活性）", "τ亚基连接核心酶与滑动钳装载器", "δ、δ'等组成滑动钳装载器", "β亚基形成环状滑动钳，作为持续合成因子", "滑动钳环状结构使聚合酶不易脱落，极大提高持续合成能力"], "check": null, "cards": [{"front": "什么是DNA聚合酶的3'→5'外切活性？其意义是什么？", "back": "校对功能：切除新生链3'端错配核苷酸，再重新掺入正确核苷酸，显著降低突变率，保证复制保真性。", "mnemonic": "3'→5'外切=退回去改错", "useImg": false}]}, {"i": 6, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶Ⅲ全酶的组成 (p40)", "notes": "大肠杆菌DNA聚合酶Ⅲ全酶由核心酶、滑动钳装载器复合物和滑动钳组成。全酶包含多个亚基，其中核心酶负责催化，τ亚基连接核心酶与装载器，δ、δ'、γ等参与装载滑动钳，β二聚体形成滑动钳。全酶结构使复制叉上前导链和后随链可同时高效合成，是原核复制机器的重要形式。", "page": 40, "level": "理解", "img": "assets/img/ch03/p040.jpg", "anim": null, "fig": null, "points": ["大肠杆菌DNA聚合酶Ⅲ全酶由核心酶、滑动钳装载器复合物和滑动钳组成", "核心酶负责催化，τ亚基连接核心酶与装载器", "δ、δ'、γ等参与装载滑动钳，β二聚体形成滑动钳", "全酶结构使复制叉上前导链和后随链可同时高效合成", "是原核复制机器的重要形式"], "check": null, "cards": [{"front": "什么是DNA聚合酶Ⅰ的切口平移？有何应用？", "back": "Pol Ⅰ从切口处切除前方核苷酸，同时沿5'→3'合成新链，使切口沿DNA移动。可用于体外放射性标记DNA探针，也参与体内RNA引物切除与空隙填补。", "mnemonic": "边切边补，切口平移；探针标记经典法", "useImg": false}]}, {"i": 7, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶Ⅲ全酶与复制体组装示意 (p41)", "notes": "该示意图展示DNA聚合酶Ⅲ全酶在复制叉上的组装与工作模式：滑动钳装载器将β滑动钳打开并装载到DNA上，聚合酶核心酶结合滑动钳后获得高持续合成能力；两个核心酶分别负责前导链和后随链合成，并与解旋酶、引物酶等协同形成复制体。图示强调了蛋白质间相互作用对复制效率的保障。", "page": 41, "level": "理解", "img": "assets/img/ch03/p041.jpg", "anim": null, "fig": "看图中滑动钳装载器如何打开β滑动钳并套到DNA上，以及两个核心酶分别结合前导链和后随链模板；注意解旋酶、引物酶与聚合酶的相对位置，理解复制体各组分协同工作的模式。", "points": ["滑动钳装载器将β滑动钳打开并装载到DNA上", "聚合酶核心酶结合滑动钳后获得高持续合成能力", "两个核心酶分别负责前导链和后随链合成", "与解旋酶、引物酶等协同形成复制体", "图示强调蛋白质间相互作用对复制效率的保障"], "check": null, "cards": [{"front": "DNA聚合酶Ⅲ核心酶由哪些亚基组成？各有什么功能？", "back": "α：5'→3'聚合；ε：3'→5'外切校对；θ：组装核心酶并促进ε活性。", "mnemonic": "α聚合，ε校对，θ组装促ε", "useImg": false}]}, {"i": 8, "sec": "DNA聚合酶与DNA连接酶", "title": "滑动钳由装载器打开并装载到DNA上 (p42)", "notes": "滑动钳装载器利用ATP水解提供的能量，将环状滑动钳打开并套在DNA双链上，随后关闭形成环状结构。装载器本身不具聚合酶活性，但能确保滑动钳正确定位在引物-模板接头处。该过程是复制体组装的关键步骤，使DNA聚合酶获得持续合成能力。", "page": 42, "level": "理解", "img": "assets/img/ch03/p042.jpg", "anim": null, "fig": null, "points": ["滑动钳装载器利用ATP水解提供的能量，将环状滑动钳打开并套在DNA双链上", "随后关闭形成环状结构", "装载器本身不具聚合酶活性，但能确保滑动钳正确定位在引物-模板接头处", "该过程是复制体组装的关键步骤，使DNA聚合酶获得持续合成能力"], "check": null, "cards": [{"front": "DNA聚合酶Ⅲ中β亚基和τ亚基分别起什么作用？", "back": "β亚基形成环状滑动钳，作为持续合成因子；τ亚基连接核心酶与滑动钳装载器。", "mnemonic": "β成环当滑钳，τ连核心与装载器", "useImg": false}]}, {"i": 9, "sec": "DNA聚合酶与DNA连接酶", "title": "滑动钳显著提高DNA聚合酶持续合成能力 (p43)", "notes": "滑动钳是环状蛋白，可套在DNA上并沿双链滑动，将DNA聚合酶锚定在模板上，防止其因合成而脱落。与无滑动钳时相比，滑动钳可使聚合酶的持续合成能力提高数百至数千倍，从而能连续合成数千个核苷酸。该机制对复制叉高效延伸和基因组完整复制至关重要。", "page": 43, "level": "掌握", "img": "assets/img/ch03/p043.jpg", "anim": null, "fig": null, "points": ["滑动钳是环状蛋白，可套在DNA上并沿双链滑动", "将DNA聚合酶锚定在模板上，防止其因合成而脱落", "与无滑动钳时相比，可使聚合酶的持续合成能力提高数百至数千倍", "能连续合成数千个核苷酸", "对复制叉高效延伸和基因组完整复制至关重要"], "check": null, "cards": [{"front": "大肠杆菌DNA聚合酶Ⅲ全酶由哪几部分组成？", "back": "核心酶、滑动钳装载器复合物和滑动钳（β二聚体）组成。", "mnemonic": "全酶=核心+装载器+滑动钳", "useImg": false}]}, {"i": 10, "sec": "DNA聚合酶与DNA连接酶", "title": "复制体（replisome）的概念 (p44)", "notes": "复制体是复制叉上由多种蛋白质组成的复合机器，包括DNA聚合酶、解旋酶、引物酶、滑动钳、装载器及单链结合蛋白等。各组分协同工作，实现DNA双链解开、RNA引物合成、前导链和后随链同步延伸。复制体的组装与动态变化保证了复制快速、准确进行。", "page": 44, "level": "理解", "img": "assets/img/ch03/p044.jpg", "anim": null, "fig": null, "points": ["复制体是复制叉上由多种蛋白质组成的复合机器", "包括DNA聚合酶、解旋酶、引物酶、滑动钳、装载器及单链结合蛋白等", "各组分协同工作，实现DNA双链解开、RNA引物合成、前导链和后随链同步延伸", "复制体的组装与动态变化保证复制快速、准确进行"], "check": null, "cards": [{"front": "滑动钳装载器如何将滑动钳装载到DNA上？", "back": "利用ATP水解能量，将环状滑动钳打开并套在DNA双链上，随后关闭形成环状结构，定位在引物-模板接头处。", "mnemonic": "ATP开环，套上DNA，关环定位", "useImg": false}]}, {"i": 11, "sec": "DNA聚合酶与DNA连接酶", "title": "复制叉上酶协同工作的机制 (p45)", "notes": "在大肠杆菌中，Pol Ⅲ全酶的τ亚基可刺激解旋酶活性约10倍，解旋酶又刺激引物酶活性约1000倍，滑动钳则刺激Pol Ⅲ活性。这种相互激活形成正反馈，使复制叉上解旋、引物合成和DNA聚合紧密偶联，保证前导链与后随链协调合成。复制体各组分协同是高效复制的关键。", "page": 45, "level": "掌握", "img": "assets/img/ch03/p045.jpg", "anim": null, "fig": null, "points": ["大肠杆菌中Pol Ⅲ全酶的τ亚基可刺激解旋酶活性约10倍", "解旋酶又刺激引物酶活性约1000倍", "滑动钳刺激Pol Ⅲ活性", "这种相互激活形成正反馈，使解旋、引物合成和DNA聚合紧密偶联", "保证前导链与后随链协调合成，是高效复制的关键"], "check": null, "cards": [{"front": "滑动钳如何提高DNA聚合酶的持续合成能力？", "back": "环状蛋白套在DNA上并沿双链滑动，将聚合酶锚定在模板上，防止脱落，使持续合成能力提高数百至数千倍。", "mnemonic": "环套DNA，滑动不掉，持续合成千倍升", "useImg": false}]}, {"i": 12, "sec": "DNA聚合酶与DNA连接酶", "title": "真核生物DNA聚合酶的种类与功能 (p46)", "notes": "真核生物已发现15种以上DNA聚合酶，哺乳动物主要有5种。Pol α与引物酶共同启动复制，形成RNA-DNA引物；Pol β参与碱基切除修复；Pol γ负责线粒体DNA复制；Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成。各聚合酶分工协作，确保核DNA和线粒体DNA的准确复制与修复。", "page": 46, "level": "掌握", "img": "assets/img/ch03/p046.jpg", "anim": null, "fig": null, "points": ["真核生物已发现15种以上DNA聚合酶，哺乳动物主要有5种", "Pol α与引物酶共同启动复制，形成RNA-DNA引物", "Pol β参与碱基切除修复；Pol γ负责线粒体DNA复制", "Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成", "各聚合酶分工协作，确保核DNA和线粒体DNA的准确复制与修复"], "check": null, "cards": [{"front": "什么是复制体（replisome）？包括哪些主要组分？", "back": "复制叉上由多种蛋白质组成的复合机器，包括DNA聚合酶、解旋酶、引物酶、滑动钳、装载器及单链结合蛋白等。", "mnemonic": "复制体=聚合+解旋+引物+滑钳+装载+SSB", "useImg": false}]}, {"i": 13, "sec": "DNA聚合酶与DNA连接酶", "title": "真核复制中的DNA聚合酶转换 (p47)", "notes": "真核DNA复制起始时，Pol α合成RNA-DNA引物，随后在滑动钳装载器（RFC）和滑动钳（PCNA）帮助下，Pol δ或Pol ε替换Pol α，分别延伸后随链和前导链。这种聚合酶转换确保引物被延伸为完整DNA链，并赋予复制高持续性和校对能力。转换过程受多种蛋白精确调控。", "page": 47, "level": "理解", "img": "assets/img/ch03/p047.jpg", "anim": null, "fig": null, "points": ["真核DNA复制起始时，Pol α合成RNA-DNA引物", "在滑动钳装载器（RFC）和滑动钳（PCNA）帮助下，Pol δ或Pol ε替换Pol α", "Pol δ延伸后随链，Pol ε延伸前导链", "聚合酶转换确保引物被延伸为完整DNA链，并赋予复制高持续性和校对能力", "转换过程受多种蛋白精确调控"], "check": null, "cards": [{"front": "复制叉上酶如何协同工作（大肠杆菌）？", "back": "Pol Ⅲ全酶的τ亚基刺激解旋酶活性约10倍，解旋酶刺激引物酶活性约1000倍，滑动钳刺激Pol Ⅲ活性，形成正反馈，使解旋、引物合成和DNA聚合紧密偶联。", "mnemonic": "τ促解旋10倍，解旋促引物1000倍，滑钳促聚合", "useImg": false}]}, {"i": 14, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA聚合酶的共同特点 (p48)", "notes": "所有DNA聚合酶具有共同特征：以dNTP为底物；需要Mg2+激活；需要模板指导；需要3'-OH存在；新链合成方向为5'→3'。这些共性反映了DNA聚合酶催化机制的保守性，也决定了DNA复制的基本方向与化学本质。理解这些特点有助于掌握复制、修复和逆转录等过程的共性。", "page": 48, "level": "掌握", "img": "assets/img/ch03/p048.jpg", "anim": null, "fig": null, "points": ["以dNTP为底物", "需要Mg2+激活", "需要模板指导", "需要3'-OH存在", "新链合成方向为5'→3'"], "check": null, "cards": [{"front": "真核生物主要DNA聚合酶的种类与功能是什么？", "back": "Pol α：与引物酶共同启动复制，形成RNA-DNA引物；Pol β：碱基切除修复；Pol γ：线粒体DNA复制；Pol δ：后随链合成并参与修复；Pol ε：前导链合成。", "mnemonic": "α起始，β修复，γ线粒体，δ后随，ε前导", "useImg": false}]}, {"i": 15, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA连接酶的作用 (p49)", "notes": "DNA连接酶催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键，从而连接相邻核苷酸，封闭切口。它不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口。DNA连接酶在DNA复制、修复和重组中不可或缺，也是基因工程中构建重组DNA的关键工具。", "page": 49, "level": "掌握", "img": "assets/img/ch03/p049.jpg", "anim": null, "fig": null, "points": ["DNA连接酶催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键", "连接相邻核苷酸，封闭切口", "不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口", "在DNA复制、修复和重组中不可或缺", "是基因工程中构建重组DNA的关键工具"], "check": null, "cards": [{"front": "真核复制中DNA聚合酶如何转换？", "back": "Pol α先合成RNA-DNA引物，随后在RFC和PCNA帮助下，Pol δ或Pol ε替换Pol α，分别延伸后随链和前导链。", "mnemonic": "α做引物，RFC+PCNA帮忙，δ/ε接班延伸", "useImg": false}]}, {"i": 16, "sec": "DNA聚合酶与DNA连接酶", "title": "DNA连接酶封闭切口的示意图 (p50)", "notes": "该示意图展示DNA连接酶封闭双链DNA切口的过程：连接酶识别切口，将3'-OH和5'-磷酸基相邻定位，催化形成磷酸二酯键，恢复DNA链的连续性。该反应需ATP或NAD+提供能量。图示强调了连接酶只能作用于双链DNA上的切口，不能连接游离单链，是理解复制、修复和重组中连接步骤的基础。", "page": 50, "level": "理解", "img": "assets/img/ch03/p050.jpg", "anim": null, "fig": "看图中连接酶如何识别双链DNA上的切口，将相邻的3'-OH与5'-磷酸基定位并催化形成磷酸二酯键；注意切口位于双链上而非游离单链末端，理解连接酶作用的底物要求。", "points": ["连接酶识别切口，将3'-OH和5'-磷酸基相邻定位", "催化形成磷酸二酯键，恢复DNA链的连续性", "反应需ATP或NAD+提供能量", "连接酶只能作用于双链DNA上的切口，不能连接游离单链", "是理解复制、修复和重组中连接步骤的基础"], "check": null, "cards": [{"front": "所有DNA聚合酶的共同特点有哪些？", "back": "以dNTP为底物；需要Mg2+激活；需要模板指导；需要3'-OH存在；新链合成方向为5'→3'。", "mnemonic": "dNTP底物，Mg激活，模板指导，3'OH起，5'→3'合", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_16", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于DNA聚合酶催化合成反应的特点，下列哪项正确？", "o": ["A. 合成方向为3'→5'，能量来自dNTP释放两个磷酸", "B. 合成方向为5'→3'，能量来自dNTP释放两个磷酸", "C. 合成方向为5'→3'，能量来自ATP水解", "D. 合成方向为3'→5'，能量来自ATP水解"], "a": "B", "e": "DNA聚合酶催化3'-OH与dNTP的5'-磷酸形成磷酸二酯键，合成方向为5'→3'，能量来自dNTP释放两个磷酸。", "kp": "ch03_s3_0"}, {"id": "ch03_mcq_17", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "在大肠杆菌中，主要负责DNA复制并具有3'→5'外切校对功能的是：", "o": ["A. DNA聚合酶Ⅰ", "B. DNA聚合酶Ⅱ", "C. DNA聚合酶Ⅲ", "D. DNA连接酶"], "a": "C", "e": "DNA聚合酶Ⅲ是复制的主要酶，具3'→5'外切活性，可校对错误掺入的核苷酸，提高保真性。", "kp": "ch03_s3_1"}, {"id": "ch03_mcq_18", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于滑动钳（sliding clamp）的作用，正确的是：", "o": ["A. 催化磷酸二酯键形成", "B. 切除RNA引物", "C. 提高DNA聚合酶的持续合成能力", "D. 连接DNA切口"], "a": "C", "e": "滑动钳为环状蛋白，套在DNA上并锚定聚合酶，防止其脱落，显著提高持续合成能力。", "kp": "ch03_s3_8"}, {"id": "ch03_mcq_19", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "真核生物中，主要负责前导链合成的DNA聚合酶是：", "o": ["A. Pol α", "B. Pol β", "C. Pol δ", "D. Pol ε"], "a": "D", "e": "Pol ε主要负责前导链合成；Pol δ主要负责后随链合成；Pol α参与起始；Pol β参与修复。", "kp": "ch03_s3_12"}, {"id": "ch03_mcq_20", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于DNA连接酶，下列描述正确的是：", "o": ["A. 能连接两条游离的DNA单链", "B. 催化3'-OH与5'-磷酸基形成磷酸二酯键", "C. 合成方向为5'→3'", "D. 需要模板指导"], "a": "B", "e": "DNA连接酶催化双链DNA切口处3'-OH与5'-磷酸基形成磷酸二酯键，不能连接游离单链，也不需要模板。", "kp": "ch03_s3_15"}], "judge": [{"id": "ch03_judge_7", "modI": 3, "q": "DNA聚合酶Ⅲ的β亚基形成环状滑动钳，作为持续合成因子，使聚合酶不易脱落，极大提高持续合成能力。", "a": "对", "e": "DNA聚合酶Ⅲ由多个亚基组成，β亚基形成环状滑动钳，作为持续合成因子；滑动钳环状结构使聚合酶不易脱落，极大提高持续合成能力。", "kp": "ch03_s3_5"}, {"id": "ch03_judge_8", "modI": 3, "q": "DNA连接酶能将两条游离的DNA单链连接起来。", "a": "错", "e": "DNA连接酶不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口。", "kp": "ch03_s3_15"}], "fill": [{"id": "ch03_fill_7", "modI": 3, "q": "DNA聚合酶催化脱氧核糖3'-OH与dNTP的5'-磷酸之间形成磷酸二酯键，反应能量来自dNTP释放两个磷酸；合成方向为________，速率可达________ dNTPs/秒。", "a": "5'→3',800", "kp": "ch03_s3_0"}, {"id": "ch03_fill_8", "modI": 3, "q": "大肠杆菌主要有DNA聚合酶Ⅰ、Ⅱ、Ⅲ；Pol Ⅰ主要切除________并填补空隙、修复损伤；Pol Ⅲ是复制主要酶，具________外切校对功能，提高保真性。", "a": "RNA引物,3'→5'", "kp": "ch03_s3_1"}], "short": [{"id": "ch03_short_4", "modI": 3, "q": "简述大肠杆菌DNA聚合酶Ⅰ、Ⅱ、Ⅲ的主要性质与功能差异。", "a": "Pol Ⅰ：具中等5'→3'聚合活性、3'→5'外切活性和5'→3'外切活性；主要切除RNA引物并填补空隙、修复损伤；其5'→3'外切活性参与切口平移。Pol Ⅱ：聚合活性很低，主要参与修复。Pol Ⅲ：聚合活性很高，是复制主要酶，具3'→5'外切校对功能，提高保真性；由多个亚基组成，核心酶含α（5'→3'聚合）、ε（3'→5'外切校对）、θ（组装核心酶并促进ε活性）；τ亚基连接核心酶与滑动钳装载器；β亚基形成环状滑动钳，作为持续合成因子。三者功能分工体现了复制与修复的协调。", "kp": "ch03_s3_1"}], "calc": [], "term": [{"id": "ch03_term_11", "modI": 3, "term": "DNA polymerase", "def": "DNA聚合酶：以DNA为模板催化dNTP合成DNA；由Arthur Kornberg在大肠杆菌中发现，又称Kornberg酶；反应需要dNTPs、带游离3′-OH的模板-引物、DNA聚合酶本身以及Mg2+；只能沿5′→3′方向延伸，并具有校对功能；是DNA复制最核心的酶。", "kp": "ch03_s3_1"}, {"id": "ch03_term_12", "modI": 3, "term": "DNA ligase", "def": "DNA连接酶：催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键，从而连接相邻核苷酸，封闭切口；不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口；在DNA复制、修复和重组中不可或缺，也是基因工程中构建重组DNA的关键工具。", "kp": "ch03_s3_0"}]}, {"i": 4, "name": "模块五：DNA复制的主要方式", "slides": [{"i": 0, "sec": "DNA复制的主要方式", "title": "DNA复制的主要方式(p51)", "notes": "本节介绍DNA复制的主要方式，包括双链线性DNA的复制和双链环状DNA的复制。双链环状DNA复制又分为θ型、滚环型和D-环型三种。不同复制方式适应不同DNA分子结构，保证遗传信息准确传递。", "page": 51, "level": "掌握", "img": "assets/img/ch03/p051.jpg", "anim": null, "fig": null, "points": ["DNA复制的主要方式包括双链线性DNA复制和双链环状DNA复制。", "双链环状DNA复制分为θ型、滚环型和D-环型三种。", "不同复制方式适应不同DNA分子结构，保证遗传信息准确传递。"], "check": null, "cards": [{"front": "DNA复制的主要方式分为哪两大类？", "back": "双链线性DNA的复制和双链环状DNA的复制。", "mnemonic": "线状+环状，两大类", "useImg": false}]}, {"i": 1, "sec": "DNA复制的主要方式", "title": "双链环状DNA复制的类型(p52)", "notes": "双链环状DNA复制主要有三种类型：θ型复制、滚环型复制和D-环型复制。θ型复制中复制叉双向移动，中间体呈θ形；滚环型复制常见于噬菌体，一条链被切开后以滚环方式延伸；D-环型复制常见于线粒体，两条链复制起点不同且不同步。", "page": 52, "level": "掌握", "img": "assets/img/ch03/p052.jpg", "anim": null, "fig": null, "points": ["双链环状DNA复制主要有三种类型：θ型、滚环型和D-环型。", "θ型复制中复制叉双向移动，中间体呈θ形。", "滚环型复制常见于噬菌体，一条链被切开后以滚环方式延伸。", "D-环型复制常见于线粒体，两条链复制起点不同且不同步。"], "check": null, "cards": [{"front": "双链环状DNA复制有哪三种类型？", "back": "θ型复制、滚环型复制、D-环型复制。", "mnemonic": "θ滚D（西塔滚地）", "useImg": false}]}, {"i": 2, "sec": "DNA复制的主要方式", "title": "θ型复制(p53)", "notes": "θ型复制是双链环形DNA分子从复制起始点开始，两个复制叉以相反方向沿染色体移动，复制中间体形状类似希腊字母θ。该方式常见于细菌环状染色体和质粒，保证双向复制高效进行，是环状DNA复制的重要模式。", "page": 53, "level": "掌握", "img": "assets/img/ch03/p053.jpg", "anim": null, "fig": null, "points": ["θ型复制从复制起始点开始，两个复制叉以相反方向移动。", "复制中间体形状类似希腊字母θ。", "常见于细菌环状染色体和质粒，保证双向复制高效进行。", "是环状DNA复制的重要模式。"], "check": null, "cards": [{"front": "θ型复制的复制叉如何移动？中间体呈什么形状？", "back": "两个复制叉以相反方向双向移动，中间体呈希腊字母θ形。", "mnemonic": "双向叉，θ形泡", "useImg": false}]}, {"i": 3, "sec": "DNA复制的主要方式", "title": "θ型复制示意图(p54)", "notes": "该图展示θ型复制过程中复制叉双向移动形成θ形中间体。复制起始点打开后，两个复制叉分别向两侧推进，合成新链，最终形成两个环状DNA分子。该图帮助理解双向复制和复制泡结构。", "page": 54, "level": "理解", "img": "assets/img/ch03/p054.jpg", "anim": null, "fig": "图中展示环状DNA从复制起始点打开，两个复制叉向相反方向移动，形成θ形中间体，最终复制出两个环状DNA分子。注意复制叉的移动方向和复制泡的扩大。", "points": ["θ型复制过程中复制叉双向移动形成θ形中间体。", "复制起始点打开后，两个复制叉分别向两侧推进，合成新链。", "最终形成两个环状DNA分子。", "图示帮助理解双向复制和复制泡结构。"], "check": null, "cards": [{"front": "θ型复制常见于哪些DNA分子？", "back": "细菌环状染色体和质粒。", "mnemonic": "细菌质粒走θ路", "useImg": false}]}, {"i": 4, "sec": "DNA复制的主要方式", "title": "θ型复制中间体示意图(p55)", "notes": "该图进一步展示θ型复制中间体的结构，包括复制叉、复制泡和未复制区域。通过图示可直观看到复制叉的移动方向和DNA链的合成情况，加深对θ型复制机制的理解。", "page": 55, "level": "理解", "img": "assets/img/ch03/p055.jpg", "anim": null, "fig": "图中显示环状DNA复制中间体，可见复制叉、复制泡和未复制区域。观察复制叉的移动方向和复制泡的形态，理解双向复制过程。", "points": ["θ型复制中间体结构包括复制叉、复制泡和未复制区域。", "通过图示可直观看到复制叉的移动方向。", "图示展示DNA链的合成情况，加深对θ型复制机制的理解。"], "check": null, "cards": [{"front": "滚环型复制常见于什么生物？正链合成有何特点？", "back": "常见于ΦX174噬菌体；正链合成不需RNA引物，在正链3'-OH上延伸；负链为不连续复制。", "mnemonic": "噬菌滚环，正链免引物", "useImg": false}]}, {"i": 5, "sec": "DNA复制的主要方式", "title": "滚环型复制(p56)", "notes": "滚环型复制常见于ΦX174噬菌体双链环状DNA。正链合成不需RNA引物，在正链3'-OH上延伸；负链合成是不连续复制。该方式通过切开一条链，以另一条链为模板滚动合成，产生多拷贝单链DNA，高效扩增遗传物质。", "page": 56, "level": "掌握", "img": "assets/img/ch03/p056.jpg", "anim": null, "fig": null, "points": ["滚环型复制常见于ΦX174噬菌体双链环状DNA。", "正链合成不需RNA引物，在正链3'-OH上延伸。", "负链合成是不连续复制。", "通过切开一条链，以另一条链为模板滚动合成，产生多拷贝单链DNA。", "高效扩增遗传物质。"], "check": null, "cards": [{"front": "滚环型复制的基本分子机制是什么？", "back": "切开一条链产生3'-OH，以环状另一条链为模板不断延伸，置换出单链，负链随后合成形成双链。", "mnemonic": "切链露出OH，绕环滚出单链", "useImg": false}]}, {"i": 6, "sec": "DNA复制的主要方式", "title": "滚环型复制示意图(p57)", "notes": "该图展示滚环型复制过程：一条链被切开产生3'-OH，以环状另一条链为模板不断延伸，置换出单链。负链随后合成，形成双链。该图有助于理解滚环复制的分子机制和不对称性。", "page": 57, "level": "理解", "img": "assets/img/ch03/p057.jpg", "anim": null, "fig": "图中展示滚环型复制过程：一条链被切开产生3'-OH，以环状另一条链为模板不断延伸，置换出单链，随后合成负链形成双链。注意模板链和新生链的方向及不对称性。", "points": ["滚环型复制中一条链被切开产生3'-OH。", "以环状另一条链为模板不断延伸，置换出单链。", "负链随后合成，形成双链。", "图示有助于理解滚环复制的分子机制和不对称性。"], "check": null, "cards": [{"front": "D-环型复制常见于哪里？两条链的复制有何特点？", "back": "常见于动物线粒体；两条链复制起点不同且不同步，合成高度不对称。", "mnemonic": "线粒体D环，两链不同步", "useImg": false}]}, {"i": 7, "sec": "DNA复制的主要方式", "title": "D-环型复制(p58)", "notes": "D-环型复制中，一条短RNA与一条DNA互补，取代原互补链，使两条链合成高度不对称。一条链迅速合成互补链，另一条链为游离单环。两条链复制起点不同且不同步。该方式首先在动物线粒体中发现，适应线粒体DNA复制需求。", "page": 58, "level": "掌握", "img": "assets/img/ch03/p058.jpg", "anim": null, "fig": null, "points": ["D-环型复制中，一条短RNA与一条DNA互补，取代原互补链。", "两条链合成高度不对称：一条链迅速合成互补链，另一条链为游离单环。", "两条链复制起点不同且不同步。", "首先在动物线粒体中发现，适应线粒体DNA复制需求。"], "check": null, "cards": [{"front": "D-环型复制中，一条短RNA的作用是什么？", "back": "短RNA与一条DNA互补，取代原互补链，形成D-环结构，使一条链迅速合成互补链，另一条链为游离单环。", "mnemonic": "RNA占位成D环，一链快一链闲", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_21", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "双链环状DNA复制的主要方式不包括以下哪一项？", "o": ["A. θ型复制", "B. 滚环型复制", "C. D-环型复制", "D. 线性复制"], "a": "D", "e": "双链环状DNA复制主要有θ型、滚环型和D-环型三种，线性复制是双链线性DNA的复制方式。", "kp": "ch03_s4_0"}, {"id": "ch03_mcq_22", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "θ型复制中，复制叉的移动方向是？", "o": ["A. 单向移动", "B. 双向移动", "C. 随机移动", "D. 不移动"], "a": "B", "e": "θ型复制中两个复制叉从起点开始以相反方向沿染色体移动，形成θ形中间体。", "kp": "ch03_s4_4"}, {"id": "ch03_mcq_23", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "滚环型复制中，正链合成不需要下列哪种物质？", "o": ["A. DNA聚合酶", "B. RNA引物", "C. 模板链", "D. 3'-OH"], "a": "B", "e": "滚环型复制中正链合成不需RNA引物，直接在正链3'-OH上延伸。", "kp": "ch03_s4_5"}, {"id": "ch03_mcq_24", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "D-环型复制首先在哪种细胞器中被发现？", "o": ["A. 细胞核", "B. 线粒体", "C. 叶绿体", "D. 核糖体"], "a": "B", "e": "D-环型复制首先在动物线粒体中被发现，其两条链复制起点不同且不同步。", "kp": "ch03_s4_7"}, {"id": "ch03_mcq_25", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "关于D-环型复制，下列描述正确的是？", "o": ["A. 两条链同步复制", "B. 两条链复制起点相同", "C. 两条链合成高度不对称", "D. 不需要RNA参与"], "a": "C", "e": "D-环型复制中一条短RNA与一条DNA互补，取代原链，使两条链合成高度不对称，且复制起点不同、不同步。", "kp": "ch03_s4_7"}], "judge": [{"id": "ch03_judge_9", "modI": 4, "q": "θ型复制中复制叉双向移动，中间体呈θ形，常见于细菌环状染色体和质粒。", "a": "对", "e": "θ型复制是双链环形DNA分子从复制起始点开始，两个复制叉以相反方向沿染色体移动，复制中间体形状类似希腊字母θ；该方式常见于细菌环状染色体和质粒。", "kp": "ch03_s4_2"}], "fill": [{"id": "ch03_fill_10", "modI": 4, "q": "双链环状DNA复制主要有三种类型：________复制、________复制和________复制。", "a": "θ型,滚环型,D-环型", "kp": "ch03_s4_1"}], "short": [], "calc": [], "term": []}, {"i": 5, "name": "模块六：大肠杆菌DNA复制的过程", "slides": [{"i": 0, "sec": "大肠杆菌DNA复制的过程", "title": "大肠杆菌DNA的复制过程 (p59)", "notes": "本页是第三章“DNA的复制”中模块六的总起页，标题为“大肠杆菌DNA的复制过程”。大肠杆菌（E. coli）是研究DNA复制机制的经典模式生物，其环状染色体约4.6 Mb，复制采用θ复制方式，为双向复制。本节将依次介绍复制起点oriC、复制的起始、新链的延伸以及复制的终止，是理解原核生物复制机制的核心内容。", "page": 59, "level": "掌握", "img": "assets/img/ch03/p059.jpg", "anim": null, "fig": null, "points": ["大肠杆菌是研究DNA复制机制的经典模式生物", "大肠杆菌环状染色体约4.6 Mb，采用θ复制方式，为双向复制", "本节内容依次包括：复制起点oriC、复制的起始、新链的延伸、复制的终止", "是理解原核生物复制机制的核心内容"], "check": null, "cards": [{"front": "大肠杆菌DNA复制采用什么方式？其染色体有何特点？", "back": "θ复制方式，双向复制；环状染色体约4.6 Mb。", "mnemonic": "θ形双向，环状4.6M", "useImg": false}, {"front": "环状染色体复制完成后如何分离？", "back": "两个复制叉在终止区相遇后，子代DNA相互缠绕，需II型拓扑异构酶（如DNA旋转酶）切开并重新连接，使两个子代环状DNA分离。", "mnemonic": "拓扑酶切连，子代环分离", "useImg": false}]}, {"i": 1, "sec": "大肠杆菌DNA复制的过程", "title": "复制机器的惊人效率 (p60)", "notes": "本页用形象的比喻说明大肠杆菌复制机器（replisome）的高效与精确：若将一个DNA碱基放大到教科书大小，大肠杆菌基因组将长达约800 km，复制体则像一辆送货车以超过600 km/h的速度行驶。完成一次基因组复制约需40分钟、行程约400 km，而两台这样的“机器”平均仅产生一个错误。这体现了DNA复制兼具高速、高保真和高度协同的特点，是生命分子机器精妙性的典型例证。", "page": 60, "level": "理解", "img": "assets/img/ch03/p060.jpg", "anim": null, "fig": null, "points": ["大肠杆菌复制机器（replisome）具有高速、高保真和高度协同的特点", "完成一次基因组复制约需40分钟", "复制体移动速度极快，比喻为超过600 km/h的送货车", "两台复制机器平均仅产生一个错误，体现高保真性", "是生命分子机器精妙性的典型例证"], "check": null, "cards": [{"front": "大肠杆菌复制机器（replisome）体现了哪些特点？", "back": "高速、高保真、高度协同。完成一次复制约40分钟，平均仅一个错误。", "mnemonic": "快准稳", "useImg": false}]}, {"i": 2, "sec": "大肠杆菌DNA复制的过程", "title": "复制机器与北京七环的类比 (p61)", "notes": "本页为示意图页，以“北京七环约940 km”作类比，帮助理解大肠杆菌基因组复制过程的尺度与复制体移动距离。结合前页可知，该图意在直观展示：在微观分子尺度上，复制机器需沿环状DNA高速行进相当于数百公里的距离，从而凸显DNA复制过程的高效性和复制体（replisome）作为分子机器的惊人性能。", "page": 61, "level": "了解", "img": "assets/img/ch03/p061.jpg", "anim": null, "fig": "该图为示意图页，用北京七环的尺度类比大肠杆菌基因组复制过程。看图时可将环状DNA复制与七环的环形路线对应，理解复制体需沿环状DNA高速行进相当于数百公里的距离，从而直观感受复制机器的高效性。", "points": ["以北京七环约940 km作类比，帮助理解大肠杆菌基因组复制的尺度", "意在直观展示复制机器沿环状DNA高速行进相当于数百公里的距离", "凸显DNA复制过程的高效性和复制体作为分子机器的惊人性能"], "check": null, "cards": [{"front": "大肠杆菌DNA复制过程分为哪四个阶段？", "back": "I.复制起点；II.复制的起始；III.新链的延伸；IV.复制的终止。", "mnemonic": "起起延终", "useImg": false}]}, {"i": 3, "sec": "大肠杆菌DNA复制的过程", "title": "大肠杆菌DNA复制过程的四个阶段 (p62)", "notes": "本页给出大肠杆菌DNA复制过程的总体框架，包括四个阶段：I. 复制起点（origin）；II. 复制的起始（initiation）；III. 新链的延伸（elongation）；IV. 复制的终止（termination）。这一划分有助于系统理解复制从起点识别、起始解旋与引物合成，到前导链和后随链的协同延伸，再到复制叉相遇并终止的完整过程。", "page": 62, "level": "掌握", "img": "assets/img/ch03/p062.jpg", "anim": null, "fig": null, "points": ["大肠杆菌DNA复制过程分为四个阶段", "I. 复制起点（origin）", "II. 复制的起始（initiation）", "III. 新链的延伸（elongation）", "IV. 复制的终止（termination）"], "check": null, "cards": [{"front": "大肠杆菌复制起点oriC的长度和组成是什么？", "back": "约245 bp，由9 bp重复序列（4个）和13 bp重复序列（3个，富含AT）组成。", "mnemonic": "245，9四13三", "useImg": false}]}, {"i": 4, "sec": "大肠杆菌DNA复制起点和起始", "title": "大肠杆菌复制起点oriC的结构 (p63)", "notes": "大肠杆菌的复制起点oriC全长约245 bp，由9 bp重复序列和13 bp重复序列组成。9 bp重复序列（共4个）是起始蛋白DnaA的结合位点；13 bp重复序列（共3个，富含AT）是DNA解旋的起始区域。oriC是复制起始的核心元件，其结构决定了复制起始的精确性和单向/双向性，是理解复制起始机制的基础。", "page": 63, "level": "掌握", "img": "assets/img/ch03/p063.jpg", "anim": null, "fig": null, "points": ["大肠杆菌复制起点oriC全长约245 bp", "由9 bp重复序列和13 bp重复序列组成", "9 bp重复序列共4个，是起始蛋白DnaA的结合位点", "13 bp重复序列共3个，富含AT，是DNA解旋的起始区域", "oriC结构决定复制起始的精确性和双向性"], "check": null, "cards": [{"front": "oriC中9 bp重复序列和13 bp重复序列的功能分别是什么？", "back": "9 bp重复序列是DnaA蛋白结合位点；13 bp重复序列（富含AT）是DNA解旋起始区域。", "mnemonic": "9结13解", "useImg": false}]}, {"i": 5, "sec": "大肠杆菌DNA复制起点和起始", "title": "起始蛋白DnaA识别并激活oriC (p64)", "notes": "本页说明复制起点的选择与激活过程：起始蛋白DnaA识别并结合oriC中的DnaA结合位点（9 bp重复序列），多个DnaA蛋白协同结合后形成起始复合物，促使oriC中13 bp重复序列区域解链（unwinding）。随后解旋酶DnaB被加载到解开的单链区域，引发复制起始。该过程体现了起始蛋白对复制起点的识别与激活作用，是复制起始的关键步骤。", "page": 64, "level": "掌握", "img": "assets/img/ch03/p064.jpg", "anim": null, "fig": null, "points": ["起始蛋白DnaA识别并结合oriC中的9 bp重复序列（DnaA结合位点）", "多个DnaA蛋白协同结合后形成起始复合物", "促使oriC中13 bp重复序列区域解链（unwinding）", "解旋酶DnaB被加载到解开的单链区域，引发复制起始", "体现起始蛋白对复制起点的识别与激活作用"], "check": null, "cards": [{"front": "DnaA蛋白如何激活oriC引发复制起始？", "back": "DnaA识别并结合9 bp重复序列，多个DnaA协同形成起始复合物，促使13 bp区域解链，随后加载解旋酶DnaB。", "mnemonic": "DnaA结合→解链→载DnaB", "useImg": false}]}, {"i": 6, "sec": "大肠杆菌DNA复制的起始和延伸", "title": "大肠杆菌DNA复制的起始和延伸 (p65)", "notes": "本页承接起始与延伸内容，概括大肠杆菌复制从起始进入延伸的过程。起始阶段DnaA使oriC解链，DnaB解旋酶加载并沿DNA移动，引物酶合成RNA引物，DNA聚合酶III随后催化新链合成。延伸阶段前导链连续合成，后随链不连续合成，二者由同一复制体协同完成，形成复制叉的双向推进。", "page": 65, "level": "掌握", "img": "assets/img/ch03/p065.jpg", "anim": null, "fig": null, "points": ["起始阶段DnaA使oriC解链，DnaB解旋酶加载并沿DNA移动", "引物酶合成RNA引物，DNA聚合酶III催化新链合成", "延伸阶段前导链连续合成，后随链不连续合成", "前导链和后随链由同一复制体协同完成，形成复制叉的双向推进"], "check": null, "cards": [{"front": "大肠杆菌复制起始后，延伸阶段需要哪些关键酶和蛋白？", "back": "DnaB解旋酶加载并沿DNA移动，引物酶合成RNA引物，DNA聚合酶III催化新链合成。", "mnemonic": "B解旋，引物酶引，Pol III延伸", "useImg": false}]}, {"i": 7, "sec": "大肠杆菌DNA复制的起始和延伸", "title": "复制体与长号模型（Trombone model） (p66)", "notes": "本页为示意图页，展示复制体（replisome）中前导链（leading strand）和后随链（lagging strand）的协同合成，即“长号模型”。后随链模板在复制体中形成环状结构，随合成不断伸缩，形似长号。该模型说明：尽管后随链是不连续合成（形成冈崎片段），但前导链和后随链由同一复制体同时、协同合成，体现了复制机器的高度组织性和高效性。", "page": 66, "level": "掌握", "img": "assets/img/ch03/p066.jpg", "anim": null, "fig": "该图为长号模型示意图，展示复制体中前导链和后随链的协同合成。看图时注意后随链模板形成的环状结构如何随合成不断伸缩，形似长号，从而理解后随链虽不连续合成，但与前导链由同一复制体同时协同完成。", "points": ["复制体中前导链和后随链协同合成，即“长号模型”", "后随链模板在复制体中形成环状结构，随合成不断伸缩，形似长号", "后随链为不连续合成，形成冈崎片段", "前导链和后随链由同一复制体同时、协同合成", "体现复制机器的高度组织性和高效性"], "check": null, "cards": [{"front": "前导链和后随链的合成方式有何不同？", "back": "前导链连续合成；后随链不连续合成（形成冈崎片段），二者由同一复制体协同完成。", "mnemonic": "前连后断，同体协同", "useImg": false}]}, {"i": 8, "sec": "大肠杆菌DNA复制的终止", "title": "大肠杆菌DNA复制的终止位点Ter (p67)", "notes": "大肠杆菌环状染色体的两个复制叉在终止区相遇。终止区含有多个拷贝的23 bp终止序列Ter，其序列为5’-AATTAGTATGTTGTAACTAAAGT-3’。Ter序列是复制终止的顺式作用元件，两个复制叉在此区域相遇并停止，确保复制在特定位置终止，避免复制叉过度推进。", "page": 67, "level": "掌握", "img": "assets/img/ch03/p067.jpg", "anim": null, "fig": null, "points": ["大肠杆菌环状染色体的两个复制叉在终止区相遇", "终止区含有多个拷贝的23 bp终止序列Ter", "Ter序列为5’-AATTAGTATGTTGTAACTAAAGT-3’", "Ter序列是复制终止的顺式作用元件", "确保复制在特定位置终止，避免复制叉过度推进"], "check": null, "cards": [{"front": "什么是长号模型（Trombone model）？", "back": "后随链模板在复制体中形成环状结构，随合成不断伸缩形似长号；说明前导链和后随链由同一复制体同时协同合成。", "mnemonic": "后随成环如长号，前后同体共合成", "useImg": false}]}, {"i": 9, "sec": "大肠杆菌DNA复制的终止", "title": "Tus蛋白与Ter-Tus复合物 (p68)", "notes": "链的终止需要Tus蛋白参与。Tus蛋白是一种反解旋酶（contrahelicase），可识别Ter序列并与之结合形成Ter-Tus复合物，抑制DnaB解旋酶的ATP依赖性解旋活性，阻止复制叉前移。Tus蛋白由tus基因编码，其反解旋酶活性是复制终止的关键，确保复制叉在终止区停止。", "page": 68, "level": "掌握", "img": "assets/img/ch03/p068.jpg", "anim": null, "fig": null, "points": ["复制终止需要Tus蛋白参与", "Tus蛋白是一种反解旋酶（contrahelicase）", "Tus蛋白识别Ter序列并与之结合形成Ter-Tus复合物", "Ter-Tus复合物抑制DnaB解旋酶的ATP依赖性解旋活性，阻止复制叉前移", "Tus蛋白由tus基因编码，其反解旋酶活性是复制终止的关键"], "check": null, "cards": [{"front": "大肠杆菌复制终止区Ter序列的特点是什么？", "back": "含多个拷贝的23 bp终止序列Ter，序列为5'-AATTAGTATGTTGTAACTAAAGT-3'，是复制终止的顺式作用元件。", "mnemonic": "23 bp Ter，多拷贝", "useImg": false}]}, {"i": 10, "sec": "大肠杆菌DNA复制的终止", "title": "Ter-Tus复合物的方向性 (p69)", "notes": "本页为示意图页，展示大肠杆菌DNA复制终止区的结构及Ter-Tus复合物的方向性。Ter-Tus复合物具有方向性：允许复制叉从一个方向通过，而阻止从相反方向到达的复制叉，从而将两个复制叉限制在终止区内相遇。这种方向性保证了复制终止的精确性，防止复制叉越过终止区继续前行，是复制终止调控的重要机制。", "page": 69, "level": "掌握", "img": "assets/img/ch03/p069.jpg", "anim": null, "fig": "该图为大肠杆菌DNA复制终止区结构及Ter-Tus复合物方向性示意图。看图时注意Ter-Tus复合物如何允许一个方向的复制叉通过、阻止相反方向的复制叉，从而将两个复制叉限制在终止区内相遇，理解复制终止的精确调控。", "points": ["Ter-Tus复合物具有方向性", "允许复制叉从一个方向通过，而阻止从相反方向到达的复制叉", "将两个复制叉限制在终止区内相遇", "保证复制终止的精确性，防止复制叉越过终止区继续前行", "是复制终止调控的重要机制"], "check": null, "cards": [{"front": "Tus蛋白如何参与复制终止？", "back": "Tus是反解旋酶，识别Ter并形成Ter-Tus复合物，抑制DnaB的ATP依赖性解旋活性，阻止复制叉前移。", "mnemonic": "Tus反解旋，Ter-Tus挡叉", "useImg": false}]}, {"i": 11, "sec": "大肠杆菌DNA复制的终止", "title": "复制完成与拓扑异构酶的作用 (p70)", "notes": "本页说明环状染色体复制完成后的分离过程。当两个复制叉在终止区相遇后，子代DNA分子相互缠绕，需要II型拓扑异构酶（如DNA旋转酶）切开并重新连接DNA链，使两个子代环状DNA分子彼此分离。这一步骤是复制完成的最后环节，确保遗传信息准确分配给子代细胞。", "page": 70, "level": "掌握", "img": "assets/img/ch03/p070.jpg", "anim": null, "fig": null, "points": ["两个复制叉在终止区相遇后，子代DNA分子相互缠绕", "需要II型拓扑异构酶（如DNA旋转酶）切开并重新连接DNA链", "使两个子代环状DNA分子彼此分离", "是复制完成的最后环节", "确保遗传信息准确分配给子代细胞"], "check": null, "cards": [{"front": "Ter-Tus复合物的方向性有何意义？", "back": "允许复制叉从一个方向通过，阻止从相反方向到达的复制叉，将两个复制叉限制在终止区内相遇，保证终止精确性。", "mnemonic": "单向放行，双向限遇", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_26", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌复制起点oriC中，9 bp重复序列的主要功能是：", "o": ["A. 作为DnaA蛋白的结合位点", "B. 作为DnaB解旋酶的加载位点", "C. 作为引物合成的起始位点", "D. 作为复制终止的识别序列"], "a": "A", "e": "oriC中的9 bp重复序列是起始蛋白DnaA的结合位点，DnaA结合后促使13 bp重复序列区域解链，从而启动复制。", "kp": "ch03_s5_4"}, {"id": "ch03_mcq_27", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "在大肠杆菌DNA复制终止过程中，Tus蛋白的作用是：", "o": ["A. 促进复制叉前移", "B. 作为反解旋酶阻止复制叉前移", "C. 合成RNA引物", "D. 切除冈崎片段"], "a": "B", "e": "Tus蛋白识别Ter序列并与之结合形成Ter-Tus复合物，具有反解旋酶活性，抑制DnaB解旋酶活性，阻止复制叉前移。", "kp": "ch03_s5_3"}, {"id": "ch03_mcq_28", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "关于大肠杆菌DNA复制中的“长号模型”，下列描述正确的是：", "o": ["A. 前导链不连续合成，后随链连续合成", "B. 前导链和后随链由不同复制体独立合成", "C. 后随链模板形成环状结构，前导链和后随链协同合成", "D. 后随链的合成不需要RNA引物"], "a": "C", "e": "长号模型描述后随链模板在复制体中形成环状结构，前导链连续合成、后随链不连续合成，二者由同一复制体协同完成。", "kp": "ch03_s5_3"}, {"id": "ch03_mcq_29", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌环状染色体复制完成后，子代DNA分子的分离需要：", "o": ["A. I型拓扑异构酶", "B. II型拓扑异构酶", "C. 解旋酶DnaB", "D. Tus蛋白"], "a": "B", "e": "环状染色体复制完成后，两个子代DNA分子相互缠绕，需要II型拓扑异构酶切开并重新连接DNA链，使子代分子分离。", "kp": "ch03_s5_0"}, {"id": "ch03_mcq_30", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌复制终止区Ter序列的特点是：", "o": ["A. 仅含一个拷贝的23 bp序列", "B. 含多个拷贝的23 bp序列", "C. 含多个拷贝的9 bp序列", "D. 含多个拷贝的13 bp序列"], "a": "B", "e": "大肠杆菌复制终止区含有多个拷贝的23 bp终止序列Ter，两个复制叉在此区域相遇并终止复制。", "kp": "ch03_s5_8"}], "judge": [], "fill": [], "short": [], "calc": [{"id": "ch03_calc_2", "modI": 5, "q": "论述大肠杆菌DNA复制的过程，包括起始、延伸和终止阶段，并说明复制体各组分如何协同工作。", "a": "起始阶段：复制起点oriC（245 bp，高度保守）被特异蛋白识别；解旋酶在复制叉前方解开双链，单链结合蛋白稳定暴露的单链；拓扑异构酶缓解超螺旋张力；引物酶合成RNA引物，提供3′-OH。延伸阶段：DNA聚合酶Ⅲ全酶在复制叉上组装；滑动钳装载器利用ATP水解能量将β滑动钳打开并装载到DNA上，聚合酶核心酶结合滑动钳后获得高持续合成能力；两个核心酶分别负责前导链和后随链合成；前导链连续合成，后随链不连续合成冈崎片段；Pol Ⅲ的τ亚基可刺激解旋酶活性约10倍，解旋酶又刺激引物酶活性约1000倍，滑动钳则刺激Pol Ⅲ活性，形成正反馈，使解旋、引物合成和DNA聚合紧密偶联。终止阶段：复制叉相遇，RNA引物被切除并由DNA填补，DNA连接酶封闭切口，形成完整DNA链。复制体各组分协同：复制体包括DNA聚合酶、解旋酶、引物酶、滑动钳、装载器及单链结合蛋白等；各组分协同工作，实现DNA双链解开、RNA引物合成、前导链和后随链同步延伸；复制体的组装与动态变化保证了复制快速、准确进行。", "steps": "起始：oriC识别、解旋、SSBP稳定、拓扑异构酶松弛、引物酶合成引物；延伸：Pol Ⅲ全酶组装、滑动钳装载、前导链连续/后随链不连续、τ-解旋酶-引物酶-滑动钳正反馈协同；终止：复制叉相遇、引物切除、填补、连接酶封闭；复制体协同：多组分复合机器，时空精密配合。", "kp": "ch03_s5_3"}], "term": []}, {"i": 6, "name": "模块七：真核生物DNA复制特点与端粒", "slides": [{"i": 0, "sec": "真核生物DNA复制特点与端粒", "title": "真核生物DNA复制特点概述 (p71)", "notes": "本页是模块七的总起页，引出真核生物DNA复制与端粒的核心问题。与细菌等原核生物相比，真核生物基因组更大、以多条线性染色体形式存在，复制不仅要保证基因组完整，还要保证每个细胞周期只复制一次，并解决线性DNA末端复制难题。后续将围绕复制起始调控、端粒与端粒酶、核小体遗传等展开。", "page": 71, "level": "掌握", "img": "assets/img/ch03/p071.jpg", "anim": null, "fig": null, "points": ["真核生物基因组更大，以多条线性染色体形式存在", "复制需保证基因组完整且每个细胞周期只复制一次", "需解决线性DNA末端复制难题", "引出复制起始调控、端粒与端粒酶、核小体遗传等核心问题"], "check": null, "cards": [{"front": "真核生物DNA复制与细菌相比有哪些核心特点？", "back": "基因组更大、多条线性染色体；需保证每周期只复制一次；需解决线性DNA末端复制难题。", "mnemonic": "大、线、一次、末端难", "useImg": false}, {"front": "目前较受支持的核小体分配模型是什么？", "back": "半保守模型，尤其H3-H4亲本四聚体保留性强，而H2A-H2B交换更动态。", "mnemonic": "H3-H4稳，H2A-H2B换", "useImg": false}]}, {"i": 1, "sec": "真核生物DNA复制特点与端粒", "title": "真核染色体每个细胞周期只复制一次 (p72)", "notes": "真核生物染色体在每个细胞周期中必须精确复制一次且仅一次。复制不足会导致染色体断裂，复制过度则造成基因扩增和基因组不稳定。细胞通过严格调控复制起始的“许可”过程来实现这一目标：M期后组装复制前复合体获得复制许可，S期起始后失去许可，从而防止同一复制起点在同一周期内再次启动。", "page": 72, "level": "掌握", "img": "assets/img/ch03/p072.jpg", "anim": null, "fig": null, "points": ["真核染色体每个细胞周期必须精确复制一次且仅一次", "复制不足导致染色体断裂，复制过度导致基因扩增和基因组不稳定", "通过复制起始的“许可”过程严格调控", "M期后组装复制前复合体获得许可，S期起始后失去许可", "防止同一复制起点在同一周期内再次启动"], "check": null, "cards": [{"front": "真核染色体为什么必须每个细胞周期只复制一次？", "back": "复制不足致染色体断裂；复制过度致基因扩增和基因组不稳定。", "mnemonic": "少断多增", "useImg": false}, {"front": "核小体遗传的生物学意义是什么？", "back": "亲代组蛋白携带修饰等表观遗传信息，通过分配传递给子代，维持基因表达状态和染色质状态。", "mnemonic": "组蛋白带记忆", "useImg": false}]}, {"i": 2, "sec": "真核生物DNA复制特点与端粒", "title": "复制起点可被被动复制 (p73)", "notes": "真核生物染色体有多个复制起点，起点激活具有时序性。若某个起点未被正常激活，而相邻起点继续双向复制，则该区域可被来自邻近起点的复制叉“被动”复制。这说明真核复制起点并非全部必须使用，但整体上仍需保证所有DNA在S期内完成复制，否则会造成复制压力、断裂和基因组不稳定。", "page": 73, "level": "理解", "img": "assets/img/ch03/p073.jpg", "anim": null, "fig": null, "points": ["真核染色体有多个复制起点，起点激活具有时序性", "某起点未激活时，相邻起点可双向复制使其被动复制", "真核复制起点并非全部必须使用", "整体仍需保证所有DNA在S期内完成复制", "否则造成复制压力、断裂和基因组不稳定"], "check": null, "cards": [{"front": "真核细胞如何保证每个复制起点每周期只起始一次？", "back": "通过“许可”调控：M期后组装pre-RC获得许可；S期起始后失去许可，高CDK抑制再许可。", "mnemonic": "先许可，后禁止", "useImg": false}]}, {"i": 3, "sec": "真核生物DNA复制特点与端粒", "title": "真核复制起始与起点许可示意图 (p74)", "notes": "本页为示意图，结合前后内容可知其展示真核DNA复制起始的“起点许可”过程：在M期后，Cdc6、Cdt1等许可因子协助MCM解旋酶装载到复制起点，形成复制前复合体（pre-RC）；进入S期后，CDK和DDK等激酶激活MCM，起始复制，同时抑制新的MCM装载，确保每个起点在一个细胞周期中只起始一次。", "page": 74, "level": "掌握", "img": "assets/img/ch03/p074.jpg", "anim": null, "fig": "该图展示真核DNA复制起始的“起点许可”过程。先看M期后许可因子如何协助MCM装载到起点形成pre-RC，再看S期CDK/DDK激活MCM起始复制并抑制重新装载。", "points": ["M期后Cdc6、Cdt1等许可因子协助MCM解旋酶装载到复制起点", "形成复制前复合体（pre-RC）", "进入S期后CDK和DDK等激酶激活MCM，起始复制", "同时抑制新的MCM装载", "确保每个起点在一个细胞周期中只起始一次"], "check": null, "cards": [{"front": "什么是复制起点的“被动复制”？", "back": "某起点未激活时，相邻起点双向复制叉可复制该区域。", "mnemonic": "邻居帮忙复制", "useImg": false}]}, {"i": 4, "sec": "真核生物DNA复制特点与端粒", "title": "解旋酶装载是复制起始第一步 (p75)", "notes": "真核DNA复制起始的第一步是解旋酶装载，即MCM2-7六聚体被装载到复制起点上，形成复制前复合体（pre-RC），这一过程称为起点许可。起点识别复合体ORC先结合起点，随后Cdc6和Cdt1协助MCM装载。只有完成许可的起点才能在S期被激活，从而保证复制起始的时空可控。", "page": 75, "level": "掌握", "img": "assets/img/ch03/p075.jpg", "anim": null, "fig": null, "points": ["真核DNA复制起始第一步是解旋酶装载", "MCM2-7六聚体装载到复制起点形成复制前复合体（pre-RC）", "该过程称为起点许可", "ORC先结合起点，Cdc6和Cdt1协助MCM装载", "只有完成许可的起点才能在S期被激活"], "check": null, "cards": [{"front": "真核复制起点是否全部必须使用？", "back": "不是，部分起点可未激活而被邻近起点被动复制，但整体仍需S期内完成全部DNA复制。", "mnemonic": "可偷懒，但必须干完", "useImg": false}]}, {"i": 5, "sec": "真核生物DNA复制特点与端粒", "title": "Pre-RC形成与激活的周期调控 (p76)", "notes": "Pre-RC的形成和激活受到细胞周期严格调控，使每个细胞周期只发生一轮复制。M期后CDK活性低，许可因子可组装pre-RC；进入S期后CDK和DDK激活MCM，启动复制，同时高CDK活性抑制新的pre-RC组装，防止再复制。G2和M期继续保持高CDK活性，直到下一周期才重新许可。", "page": 76, "level": "掌握", "img": "assets/img/ch03/p076.jpg", "anim": null, "fig": null, "points": ["Pre-RC形成和激活受细胞周期严格调控", "M期后CDK活性低，许可因子可组装pre-RC", "S期CDK和DDK激活MCM启动复制", "高CDK活性抑制新的pre-RC组装，防止再复制", "G2和M期保持高CDK活性，直到下一周期才重新许可"], "check": null, "cards": [{"front": "真核复制起始第一步是什么？", "back": "解旋酶装载：MCM2-7六聚体装载到起点，形成pre-RC，即起点许可。", "mnemonic": "先装MCM", "useImg": false}]}, {"i": 6, "sec": "真核生物DNA复制特点与端粒", "title": "端粒的结构与功能 (p77)", "notes": "端粒是真核生物线性染色体末端的特殊结构，由富含G的短串联重复序列和结合蛋白组成。其生物学功能是维持DNA复制的完整性、保护染色体末端不被识别为DNA损伤。不同生物端粒重复序列不同，如四膜虫(TTGGGG)n、人类(TTAGGG)n、酿酒酵母(TG1-3)n，果蝇则无简单重复。端粒酶可复制染色体末端。", "page": 77, "level": "掌握", "img": "assets/img/ch03/p077.jpg", "anim": null, "fig": null, "points": ["端粒是真核线性染色体末端的特殊结构", "由富含G的短串联重复序列和结合蛋白组成", "功能是维持DNA复制完整性、保护染色体末端不被识别为DNA损伤", "不同生物端粒重复序列不同：四膜虫(TTGGGG)n、人类(TTAGGG)n、酿酒酵母(TG1-3)n", "果蝇无简单重复；端粒酶可复制染色体末端"], "check": null, "cards": [{"front": "Pre-RC如何形成？", "back": "ORC结合起点，Cdc6和Cdt1协助MCM2-7装载，形成复制前复合体。", "mnemonic": "ORC-Cdc6-Cdt1-MCM", "useImg": false}]}, {"i": 7, "sec": "真核生物DNA复制特点与端粒", "title": "端粒酶延伸端粒示意图 (p78)", "notes": "本页为示意图，结合上下文可知其展示端粒酶复制端粒末端的过程。端粒酶是一种RNA-蛋白质复合物，其RNA含与端粒重复序列互补的模板，蛋白质亚基具有逆转录酶活性。端粒酶以自身RNA为模板，在染色体3’末端合成端粒重复序列，从而延伸3’端，为后续DNA复制提供空间，解决末端复制问题。", "page": 78, "level": "掌握", "img": "assets/img/ch03/p078.jpg", "anim": null, "fig": "该图展示端粒酶延伸端粒末端的过程。重点看端粒酶RNA模板如何与3’末端配对，以及逆转录合成端粒重复序列后3’端被延长的方向。", "points": ["端粒酶是RNA-蛋白质复合物", "其RNA含与端粒重复序列互补的模板", "蛋白质亚基具有逆转录酶活性", "以自身RNA为模板在染色体3’末端合成端粒重复序列", "延伸3’端为后续DNA复制提供空间，解决末端复制问题"], "check": null, "cards": [{"front": "Pre-RC形成与激活如何受细胞周期调控？", "back": "M期后低CDK允许组装pre-RC；S期CDK/DDK激活MCM并抑制新pre-RC；G2/M高CDK维持，直到下周期重新许可。", "mnemonic": "低CDK许可，高CDK禁止", "useImg": false}]}, {"i": 8, "sec": "真核生物DNA复制特点与端粒", "title": "末端复制问题 (p79)", "notes": "末端复制问题指线性DNA复制时，由于DNA聚合酶需要RNA引物且只能从5’到3’合成，去除末端RNA引物后，子链5’端无法被填补，导致每轮复制染色体末端缩短。若没有补偿机制，端粒会逐渐缩短，最终引发细胞衰老或基因组不稳定。端粒和端粒酶正是解决这一问题的关键机制。", "page": 79, "level": "掌握", "img": "assets/img/ch03/p079.jpg", "anim": null, "fig": null, "points": ["末端复制问题指线性DNA复制时末端缩短", "DNA聚合酶需要RNA引物且只能从5’到3’合成", "去除末端RNA引物后子链5’端无法被填补", "每轮复制染色体末端缩短", "端粒和端粒酶是解决该问题的关键机制"], "check": null, "cards": [{"front": "端粒的结构组成是什么？", "back": "富含G的短串联重复序列 + 端粒结合蛋白。", "mnemonic": "G重复加蛋白帽", "useImg": false}]}, {"i": 9, "sec": "真核生物DNA复制特点与端粒", "title": "端粒与端粒酶研究获2009年诺贝尔奖 (p80)", "notes": "2009年诺贝尔生理学或医学奖授予Elizabeth H. Blackburn、Carol W. Greider和Jack W. Szostak，表彰他们发现染色体如何被端粒保护以及端粒酶的机制。Blackburn和Greider发现端粒酶，Szostak证明端粒序列可保护线性DNA末端。这一发现揭示了染色体末端保护与细胞衰老、癌症等重要生命过程的关系。", "page": 80, "level": "了解", "img": "assets/img/ch03/p080.jpg", "anim": null, "fig": null, "points": ["2009年诺贝尔生理学或医学奖授予Blackburn、Greider和Szostak", "表彰发现染色体如何被端粒保护以及端粒酶机制", "Blackburn和Greider发现端粒酶", "Szostak证明端粒序列可保护线性DNA末端", "揭示染色体末端保护与细胞衰老、癌症等关系"], "check": null, "cards": [{"front": "端粒的两大核心功能是什么？", "back": "维持DNA复制完整性；保护染色体末端不被识别为DNA损伤。", "mnemonic": "保复制，护末端", "useImg": false}]}, {"i": 10, "sec": "真核生物DNA复制特点与端粒", "title": "端粒酶的结构与功能 (p81)", "notes": "端粒酶是一种RNA-蛋白质复合物。其RNA组分含有与端粒重复序列互补的模板序列，蛋白质组分具有逆转录酶活性，称为端粒酶逆转录酶（TERT）。端粒酶以自身携带的RNA为模板，逆转录合成端粒DNA重复序列，从而延伸染色体3’末端，补偿末端复制造成的缩短，维持端粒长度。", "page": 81, "level": "掌握", "img": "assets/img/ch03/p081.jpg", "anim": null, "fig": null, "points": ["端粒酶是RNA-蛋白质复合物", "RNA组分含与端粒重复序列互补的模板序列", "蛋白质组分具有逆转录酶活性，称为端粒酶逆转录酶（TERT）", "以自身RNA为模板逆转录合成端粒DNA重复序列", "延伸染色体3’末端，补偿末端复制造成的缩短，维持端粒长度"], "check": null, "cards": [{"front": "人类和四膜虫的端粒重复序列分别是什么？", "back": "人类：(TTAGGG)n；四膜虫：(TTGGGG)n。", "mnemonic": "人TTAGGG，四膜虫TTGGGG", "useImg": false}]}, {"i": 11, "sec": "真核生物DNA复制特点与端粒", "title": "端粒酶复制端粒的机制 (p82)", "notes": "端粒酶复制端粒时，其RNA模板与染色体3’末端端粒重复序列配对，以逆转录方式延伸3’末端，合成新的端粒重复。随后端粒酶移位，可进行多轮延伸。延伸后的3’末端可作为常规DNA聚合酶的引物，合成互补链，从而完成端粒区域的复制。该机制解决了线性染色体末端无法被常规复制机器完全复制的难题。", "page": 82, "level": "掌握", "img": "assets/img/ch03/p082.jpg", "anim": null, "fig": null, "points": ["端粒酶RNA模板与染色体3’末端端粒重复序列配对", "以逆转录方式延伸3’末端，合成新的端粒重复", "端粒酶移位后可进行多轮延伸", "延伸后的3’末端可作为常规DNA聚合酶的引物合成互补链", "完成端粒区域复制，解决线性染色体末端复制难题"], "check": null, "cards": [{"front": "什么是末端复制问题？", "back": "线性DNA复制去除末端RNA引物后，子链5’端无法填补，导致每轮复制染色体末端缩短。", "mnemonic": "末端引物去，5’端补不上", "useImg": false}]}, {"i": 12, "sec": "真核生物DNA复制特点与端粒", "title": "端粒酶通过延伸3’端解决末端问题 (p83)", "notes": "端粒酶通过延伸染色体3’末端来解决末端复制问题。它不依赖DNA模板，而是以自身RNA为模板合成端粒重复序列，使3’端延长。延长后的3’端为常规DNA复制提供了足够的模板，使去除末端RNA引物后仍能保留端粒序列。这样，端粒酶弥补了DNA聚合酶不能从头合成和末端引物去除造成的缺口。", "page": 83, "level": "掌握", "img": "assets/img/ch03/p083.jpg", "anim": null, "fig": null, "points": ["端粒酶通过延伸染色体3’末端解决末端复制问题", "不依赖DNA模板，以自身RNA为模板合成端粒重复序列", "使3’端延长，为常规DNA复制提供足够模板", "去除末端RNA引物后仍能保留端粒序列", "弥补DNA聚合酶不能从头合成和末端引物去除造成的缺口"], "check": null, "cards": [{"front": "端粒酶的基本组成和功能是什么？", "back": "RNA-蛋白质复合物；RNA含端粒重复互补模板，TERT具逆转录酶活性，延伸染色体3’末端。", "mnemonic": "RNA做模板，TERT逆转录", "useImg": false}]}, {"i": 13, "sec": "真核生物DNA复制特点与端粒", "title": "端粒T环结构示意图 (p84)", "notes": "本页为示意图，结合后页内容可知其展示端粒形成的T环（t-loop）结构。端粒3’端单链侵入端粒双链区，形成套索状T环，使染色体末端被“隐藏”起来，不被识别为DNA双链断裂。TRF2等端粒结合蛋白参与T环形成，T环还与端粒长度调控有关，是端粒保护功能的重要结构基础。", "page": 84, "level": "理解", "img": "assets/img/ch03/p084.jpg", "anim": null, "fig": "该图展示端粒形成的T环结构。重点看3’端单链如何侵入端粒双链区形成套索状结构，以及TRF2等蛋白如何参与维持该结构。", "points": ["端粒可形成T环（t-loop）结构", "端粒3’端单链侵入端粒双链区形成套索状T环", "使染色体末端被“隐藏”，不被识别为DNA双链断裂", "TRF2等端粒结合蛋白参与T环形成", "T环还与端粒长度调控有关，是端粒保护功能的重要结构基础"], "check": null, "cards": [{"front": "端粒酶复制端粒的机制是什么？", "back": "RNA模板与3’末端配对，逆转录延伸3’端；端粒酶移位多轮延伸；延长后的3’端供常规聚合酶合成互补链。", "mnemonic": "配对-延伸-移位-再延伸", "useImg": false}]}, {"i": 14, "sec": "真核生物DNA复制特点与端粒", "title": "端粒形成T环保护染色体末端 (p85)", "notes": "端粒在细胞中可形成环状结构（T环）。通过形成T环，端粒末端被遮蔽，不能被细胞识别为正常DNA末端或损伤。纯化的TRF2蛋白能引导T环形成，且T环可能与端粒长度控制有关。T环结构由端粒DNA和端粒结合蛋白共同维持，是端粒保护染色体末端、防止末端融合和降解的重要机制。", "page": 85, "level": "理解", "img": "assets/img/ch03/p085.jpg", "anim": null, "fig": null, "points": ["端粒在细胞中可形成环状结构（T环）", "通过T环端粒末端被遮蔽，不能被识别为正常DNA末端或损伤", "纯化的TRF2蛋白能引导T环形成", "T环可能与端粒长度控制有关", "T环由端粒DNA和端粒结合蛋白共同维持，防止末端融合和降解"], "check": null, "cards": [{"front": "端粒酶如何解决末端复制问题？", "back": "以自身RNA为模板延伸3’末端，为常规DNA复制提供足够模板，弥补引物去除造成的缺口。", "mnemonic": "延长3’端，补足模板", "useImg": false}]}, {"i": 15, "sec": "真核生物DNA复制特点与端粒", "title": "端粒的功能 (p86)", "notes": "端粒是染色体末端的保护帽，其重复序列配合端粒酶可解决线性染色体末端复制问题。端粒还参与染色体在细胞核中的空间组织，影响染色体末端核内定位。端粒长度与细胞增殖能力密切相关：端粒过短或失去保护会被识别为DNA损伤，激活DNA损伤反应，使细胞衰老或停止分裂；许多癌细胞重新激活端粒酶，维持端粒长度并获得无限增殖能力。", "page": 86, "level": "掌握", "img": "assets/img/ch03/p086.jpg", "anim": null, "fig": null, "points": ["端粒是染色体末端的保护帽", "重复序列配合端粒酶可解决线性染色体末端复制问题", "参与染色体在细胞核中的空间组织，影响末端核内定位", "端粒长度与细胞增殖能力密切相关", "端粒过短或失去保护被识别为DNA损伤，激活损伤反应使细胞衰老或停止分裂", "许多癌细胞重新激活端粒酶，维持端粒长度并获得无限增殖能力"], "check": null, "cards": [{"front": "什么是端粒T环？", "back": "端粒3’端单链侵入端粒双链区形成的套索状结构，使末端被隐藏，不被识别为DNA双链断裂。", "mnemonic": "末端藏进套索", "useImg": false}]}, {"i": 16, "sec": "真核生物DNA复制特点与端粒", "title": "端粒与衰老：小鼠实验 (p87)", "notes": "本页介绍通过调控端粒酶逆转小鼠衰老表型的研究。科学家通过抑制端粒酶相关基因使小鼠提前衰老，再重新激活该基因，部分逆转衰老效应。该研究说明端粒缩短与衰老相关，端粒酶激活可改善组织退化。但此类研究距离人类应用尚远，提示端粒与衰老、干细胞功能及癌症风险之间存在复杂关系。", "page": 87, "level": "了解", "img": "assets/img/ch03/p087.jpg", "anim": null, "fig": null, "points": ["通过调控端粒酶逆转小鼠衰老表型的研究", "抑制端粒酶相关基因使小鼠提前衰老", "重新激活该基因可部分逆转衰老效应", "说明端粒缩短与衰老相关，端粒酶激活可改善组织退化", "距离人类应用尚远，端粒与衰老、干细胞功能及癌症风险关系复杂"], "check": null, "cards": [{"front": "T环由什么维持？有何意义？", "back": "由端粒DNA和端粒结合蛋白（如TRF2）共同维持；保护末端、防止末端融合和降解，并参与端粒长度调控。", "mnemonic": "TRF2引导，保护末端", "useImg": false}]}, {"i": 17, "sec": "真核生物DNA复制特点与端粒", "title": "人端粒酶的表达与肿瘤 (p88)", "notes": "人端粒酶在胎儿发育期活跃，在多种增殖性细胞中保持活性，如干细胞、生殖细胞、毛囊细胞和活化淋巴细胞。许多成体细胞中端粒酶下调但仍可检测，如上皮细胞、成纤维细胞和内皮细胞。约90%的人类肿瘤中端粒酶高度活跃，从而维持端粒长度、获得无限增殖能力。因此端粒酶是癌症治疗的重要靶点。", "page": 88, "level": "掌握", "img": "assets/img/ch03/p088.jpg", "anim": null, "fig": null, "points": ["人端粒酶在胎儿发育期活跃", "在多种增殖性细胞中保持活性：干细胞、生殖细胞、毛囊细胞和活化淋巴细胞", "许多成体细胞中端粒酶下调但仍可检测：上皮细胞、成纤维细胞和内皮细胞", "约90%的人类肿瘤中端粒酶高度活跃，维持端粒长度、获得无限增殖能力", "端粒酶是癌症治疗的重要靶点"], "check": null, "cards": [{"front": "端粒长度与细胞增殖和衰老有何关系？", "back": "端粒过短或失去保护被识别为DNA损伤，激活损伤反应，使细胞衰老或停止分裂。", "mnemonic": "端粒短，细胞老", "useImg": false}]}, {"i": 18, "sec": "真核生物DNA复制特点与端粒", "title": "核小体的遗传 (p89)", "notes": "核小体遗传关注DNA复制后亲代组蛋白如何分配给子代DNA。组蛋白合成与DNA复制同步。主要模型包括：保守模型认为亲代(H3-H4)₂四聚体完整分配给一条子链；半保守模型认为亲代四聚体拆分为两个二聚体，分别进入两条子链，再与新合成二聚体配对；分散模型认为亲代四聚体随机分配，兼有拆分和完整分配。半保守模型获得较多支持，尤其H3-H4亲本四聚体保留性强，而H2A-H2B交换更动态。", "page": 89, "level": "掌握", "img": "assets/img/ch03/p089.jpg", "anim": null, "fig": null, "points": ["核小体遗传关注DNA复制后亲代组蛋白如何分配给子代DNA", "组蛋白合成与DNA复制同步", "保守模型：亲代(H3-H4)₂四聚体完整分配给一条子链", "半保守模型：亲代四聚体拆分为两个二聚体，分别进入两条子链，再与新合成二聚体配对", "分散模型：亲代四聚体随机分配，兼有拆分和完整分配", "半保守模型获得较多支持，H3-H4亲本四聚体保留性强，H2A-H2B交换更动态"], "check": null, "cards": [{"front": "端粒酶在正常人体细胞和肿瘤中的表达有何差异？", "back": "胎儿期活跃；干细胞、生殖细胞、毛囊细胞、活化淋巴细胞中有活性；约90%人类肿瘤中高度活跃。", "mnemonic": "正常少，肿瘤多", "useImg": false}]}, {"i": 19, "sec": "真核生物DNA复制特点与端粒", "title": "核小体分配与表观遗传示意图 (p90)", "notes": "本页为示意图，结合前页内容可知其展示DNA复制后核小体/组蛋白在子代DNA链上的分配方式。亲代组蛋白携带组蛋白修饰等表观遗传信息，通过半保守分配等方式传递给子代，使基因表达状态在细胞分裂后得以维持。该图有助于理解组蛋白修饰的遗传机制及染色质状态在复制后的重建。", "page": 90, "level": "理解", "img": "assets/img/ch03/p090.jpg", "anim": null, "fig": "该图展示DNA复制后核小体/组蛋白在子代DNA链上的分配方式。重点看亲代组蛋白如何通过半保守分配等方式进入子代DNA，并携带表观遗传信息传递。", "points": ["展示DNA复制后核小体/组蛋白在子代DNA链上的分配方式", "亲代组蛋白携带组蛋白修饰等表观遗传信息", "通过半保守分配等方式传递给子代", "使基因表达状态在细胞分裂后得以维持", "有助于理解组蛋白修饰的遗传机制及染色质状态在复制后的重建"], "check": null, "cards": [{"front": "核小体遗传的主要模型有哪些？", "back": "保守模型：亲代(H3-H4)₂完整分配；半保守模型：亲代四聚体拆分为二聚体分别进入子链；分散模型：随机分配。", "mnemonic": "保、半保、分散", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_31", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "真核生物保证每个细胞周期DNA只复制一次的关键调控环节是？", "o": ["A. 复制起点许可（pre-RC组装）与CDK活性的周期性变化", "B. DNA聚合酶合成速度的调节", "C. 核小体组装速度的调节", "D. 端粒酶活性的调节"], "a": "A", "e": "真核生物通过起点许可和CDK周期性调控，使pre-RC在低CDK时组装、高CDK时激活并抑制再组装，从而保证每个起点每周期只起始一次。", "kp": "ch03_s6_1"}, {"id": "ch03_mcq_32", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "端粒酶解决末端复制问题的主要机制是？", "o": ["A. 以DNA为模板合成端粒重复序列", "B. 以自身RNA为模板逆转录延伸染色体3’末端", "C. 直接填补去除RNA引物后的5’端缺口", "D. 切除染色体末端以维持长度"], "a": "B", "e": "端粒酶是RNA-蛋白质复合物，其RNA含互补模板，蛋白质具逆转录酶活性，可延伸染色体3’末端，为常规复制提供模板。", "kp": "ch03_s6_12"}, {"id": "ch03_mcq_33", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "关于端粒功能，下列哪项不正确？", "o": ["A. 保护染色体末端不被识别为DNA损伤", "B. 参与染色体在细胞核中的空间组织", "C. 端粒缩短可激活DNA损伤反应导致细胞衰老", "D. 端粒酶在所有正常成体细胞中均高度表达"], "a": "D", "e": "端粒酶在胎儿发育和干细胞、生殖细胞等增殖细胞中活跃，但在许多成体细胞中下调；约90%肿瘤中高度活跃。", "kp": "ch03_s6_6"}, {"id": "ch03_mcq_34", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "关于复制后核小体/组蛋白分配的半保守模型，正确的是？", "o": ["A. 亲代(H3-H4)₂四聚体完整分配给一条子链", "B. 亲代(H3-H4)₂四聚体拆分为两个H3-H4二聚体，分别进入两条子链", "C. 亲代组蛋白全部降解，子代全部使用新合成组蛋白", "D. 亲代组蛋白随机分配到子链或保持完整，无规律"], "a": "B", "e": "半保守模型认为亲代(H3-H4)₂四聚体在复制叉处拆分为两个二聚体，分别分配到两条子链，再与新合成二聚体配对，是解释组蛋白修饰遗传的重要机制。", "kp": "ch03_s6_19"}, {"id": "ch03_mcq_35", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "真核生物复制起点“可被被动复制”的含义是？", "o": ["A. 所有起点必须在同一时间激活", "B. 未激活的起点可由邻近复制叉复制", "C. 起点只能被端粒酶复制", "D. 起点复制不需要MCM解旋酶"], "a": "B", "e": "真核复制起点激活有时序性，若某起点未激活，相邻起点形成的复制叉可被动复制该区域，但整体仍需保证S期内完成复制。", "kp": "ch03_s6_2"}], "judge": [{"id": "ch03_judge_10", "modI": 6, "q": "真核生物DNA复制时，Pol ε主要负责后随链合成，Pol δ主要负责前导链合成。", "a": "错", "e": "真核生物DNA复制时，Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成。", "kp": "ch03_s6_0"}], "fill": [{"id": "ch03_fill_9", "modI": 6, "q": "真核生物DNA复制起始时，Pol α合成________引物，随后在滑动钳装载器（RFC）和滑动钳（PCNA）帮助下，Pol δ或Pol ε替换Pol α，分别延伸________链和________链。", "a": "RNA-DNA,后随,前导", "kp": "ch03_s6_0"}], "short": [{"id": "ch03_short_5", "modI": 6, "q": "简述真核生物DNA复制的主要特点，包括多起点复制、聚合酶分工和端粒问题。", "a": "多起点复制：真核生物每条染色体含多个复制子、多个复制起点，一个细胞周期中可激活约5万~10万个起点；复制时表现为多点起始、双向复制，相邻复制子的复制叉最终相遇并汇合，完成整条染色体的复制；每个复制子在一个细胞周期中只能复制一次。聚合酶分工：真核生物已发现15种以上DNA聚合酶，哺乳动物主要有5种；Pol α与引物酶共同启动复制，形成RNA-DNA引物；Pol β参与碱基切除修复；Pol γ负责线粒体DNA复制；Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成。端粒问题：真核线性染色体末端存在复制问题，端粒酶解决真核线性染色体末端复制问题。", "kp": "ch03_s6_0"}], "calc": [], "term": []}, {"i": 7, "name": "模块八：原核与真核复制比较及医学联系", "slides": [{"i": 0, "sec": "原核与真核复制比较及医学联系", "title": "原核、真核生物DNA复制的比较 (p91)", "notes": "本页作为模块八的开篇，提出将系统比较原核生物与真核生物DNA复制的异同。原核生物（如大肠杆菌）与真核生物在复制机制上既有高度保守的共性，也存在因基因组大小、结构及细胞周期差异而产生的显著不同。理解这些异同不仅有助于掌握复制的基本原理，也为理解抗癌、抗病毒药物的作用机制奠定基础。", "page": 91, "level": "掌握", "img": "assets/img/ch03/p091.jpg", "anim": null, "fig": null, "points": ["原核与真核DNA复制机制高度保守，但因基因组大小、结构及细胞周期差异而显著不同", "比较两者异同是掌握复制基本原理的核心，也是理解抗癌、抗病毒药物作用机制的基础", "原核代表：大肠杆菌；真核代表：人类等", "本页为模块八开篇，引出系统比较的必要性"], "check": null, "cards": [{"front": "原核与真核DNA复制的相同点有哪些？", "back": "均为半保留复制、半不连续复制；都需要解旋酶、单链结合蛋白、RNA引物及校对机制。", "mnemonic": "半半解单引校对——两半两需", "useImg": false}, {"front": "原核与真核复制叉关键蛋白的对应关系是什么？", "back": "DnaB→CMG；SSB→RPA；Pol III→Pol ε/Pol δ；β夹钳→PCNA；夹钳装载机→RFC；引物酶→Pol α–引物酶；Pol I→RNase H和FEN1；连接酶→DNA连接酶I。", "mnemonic": "DnaB-CMG，SSB-RPA，PolIII-εδ，β-PCNA，装载-RFC", "useImg": false}]}, {"i": 1, "sec": "原核与真核复制比较及医学联系", "title": "原核与真核DNA复制的异同 (p92)", "notes": "相同点：两者均为半保留复制、半不连续复制，都需要解旋酶、单链结合蛋白、RNA引物及校对机制。不同点：原核生物通常只有一个复制起点，复制子大且单一，复制周期与细胞周期不重叠，复制速度快，冈崎片段较长，无端粒和端粒酶，DNA聚合酶种类较少，且无核小体结构；真核生物有多个复制起点，复制子小且多，复制周期与细胞周期严格重叠，复制速度慢，冈崎片段较短，存在端粒和端粒酶，DNA聚合酶种类多，且DNA缠绕在核小体上。这些差异反映了真核生物基因组更大、更复杂，需要更精细的调控。", "page": 92, "level": "掌握", "img": "assets/img/ch03/p092.jpg", "anim": null, "fig": null, "points": ["相同点：半保留复制、半不连续复制、需解旋酶/单链结合蛋白/RNA引物/校对机制", "原核：单复制起点、复制子大且单一、复制与细胞周期不重叠、速度快、冈崎片段长、无端粒/端粒酶、DNA聚合酶种类少、无核小体", "真核：多复制起点、复制子小且多、复制与细胞周期严格重叠、速度慢、冈崎片段短、有端粒/端粒酶、DNA聚合酶种类多、DNA缠绕核小体", "此为高频考点，需准确区分原核与真核的对应差异"], "check": null, "cards": [{"front": "原核与真核DNA复制的主要不同点有哪些？", "back": "原核：单起点、复制子大、复制与细胞周期不重叠、速度快、冈崎片段长、无端粒酶、聚合酶少、无核小体；真核：多起点、复制子小、与细胞周期严格重叠、速度慢、冈崎片段短、有端粒酶、聚合酶多、有核小体。", "mnemonic": "原核一快大无少，真核多慢小有繁", "useImg": false}]}, {"i": 2, "sec": "原核与真核复制比较及医学联系", "title": "医学联系 (p93)", "notes": "本页为过渡页，引出DNA复制与医学的关联。许多抗癌和抗病毒药物以DNA复制为靶点，因为肿瘤细胞和病毒往往增殖迅速，对DNA复制抑制剂更为敏感。理解复制机制有助于开发选择性高、毒性低的药物。", "page": 93, "level": "了解", "img": "assets/img/ch03/p093.jpg", "anim": null, "fig": null, "points": ["许多抗癌和抗病毒药物以DNA复制为靶点", "肿瘤细胞和病毒增殖迅速，对DNA复制抑制剂更敏感", "理解复制机制有助于开发选择性高、毒性低的药物", "本页为过渡页，引出后续药物实例"], "check": null, "cards": [{"front": "为什么抗癌抗病毒药物常以DNA复制为靶点？", "back": "肿瘤细胞和病毒增殖迅速，对DNA复制抑制剂更敏感；理解复制机制有助于开发选择性高、毒性低的药物。", "mnemonic": "增殖快→更敏感→打复制", "useImg": false}]}, {"i": 3, "sec": "原核与真核复制比较及医学联系", "title": "靶向DNA复制的抗癌与抗病毒药物 (p94)", "notes": "本页概括了靶向DNA复制的药物策略：1）靶向核苷酸前体的生物合成，使DNA聚合酶缺乏底物，如5-FU、6-MP；2）更直接地靶向DNA合成，如AraC；3）损伤DNA以阻断复制，如顺铂。这些策略利用了癌细胞或病毒快速增殖的特点，但也会影响正常快速分裂的细胞，因此需注意副作用。", "page": 94, "level": "掌握", "img": "assets/img/ch03/p094.jpg", "anim": null, "fig": null, "points": ["策略一：靶向核苷酸前体生物合成，使DNA聚合酶缺乏底物，如5-FU、6-MP", "策略二：直接靶向DNA合成，如AraC", "策略三：损伤DNA以阻断复制，如顺铂", "利用癌细胞或病毒快速增殖特点，但也会影响正常快速分裂细胞，需注意副作用"], "check": null, "cards": [{"front": "靶向DNA复制的药物有哪三大策略？", "back": "1）靶向核苷酸前体合成（如5-FU、6-MP）；2）直接靶向DNA合成（如AraC）；3）损伤DNA阻断复制（如顺铂）。", "mnemonic": "断粮、堵路、炸桥", "useImg": false}]}, {"i": 4, "sec": "原核与真核复制比较及医学联系", "title": "核苷酸前体类似物：5-FU与6-MP (p95)", "notes": "5-氟尿嘧啶（5-FU）和6-巯嘌呤（6-MP）是核苷酸前体类似物，通过抑制嘧啶和嘌呤的合成，使DNA聚合酶缺乏构建DNA所需的核苷酸，从而抑制DNA复制。5-FU主要用于治疗消化道肿瘤等，6-MP用于白血病等。它们属于抗代谢类药物，通过“饥饿”策略抑制快速增殖的细胞。", "page": 95, "level": "掌握", "img": "assets/img/ch03/p095.jpg", "anim": null, "fig": null, "points": ["5-FU和6-MP是核苷酸前体类似物，属抗代谢类药物", "5-FU抑制嘧啶合成，6-MP抑制嘌呤合成，使DNA聚合酶缺乏核苷酸底物", "通过“饥饿”策略抑制快速增殖细胞", "5-FU主要用于消化道肿瘤等，6-MP用于白血病等"], "check": null, "cards": [{"front": "5-FU和6-MP的作用机制是什么？", "back": "核苷酸前体类似物，抑制嘧啶和嘌呤合成，使DNA聚合酶缺乏底物，从而抑制DNA复制。", "mnemonic": "饥饿疗法——不给原料", "useImg": false}]}, {"i": 5, "sec": "原核与真核复制比较及医学联系", "title": "直接靶向DNA合成：阿糖胞苷 (p96)", "notes": "胞嘧啶阿糖胞苷（AraC）是胞苷类似物，在体内转化为三磷酸形式，竞争性抑制DNA聚合酶，并可作为底物掺入DNA，导致链终止或复制错误。AraC主要用于治疗急性髓系白血病等。它直接干扰DNA合成，属于细胞周期特异性药物。", "page": 96, "level": "掌握", "img": "assets/img/ch03/p096.jpg", "anim": null, "fig": null, "points": ["AraC是胞苷类似物，体内转化为三磷酸形式", "竞争性抑制DNA聚合酶，并可掺入DNA导致链终止或复制错误", "主要用于治疗急性髓系白血病等", "直接干扰DNA合成，属细胞周期特异性药物"], "check": null, "cards": [{"front": "5-FU和6-MP分别主要用于治疗什么？", "back": "5-FU主要用于消化道肿瘤等；6-MP用于白血病等。", "mnemonic": "5-FU管消化，6-MP管白血", "useImg": false}]}, {"i": 6, "sec": "原核与真核复制比较及医学联系", "title": "损伤DNA阻断复制：顺铂 (p97)", "notes": "顺铂（Cisplatin）是一种铂类化合物，能与DNA鸟嘌呤N7位共价结合，形成链内或链间交联，导致DNA双链扭曲，阻断DNA复制和转录，最终诱导细胞凋亡。顺铂广泛用于睾丸癌、卵巢癌、肺癌等实体瘤的治疗。其作用不依赖于细胞周期，但副作用包括肾毒性和神经毒性。", "page": 97, "level": "掌握", "img": "assets/img/ch03/p097.jpg", "anim": null, "fig": null, "points": ["顺铂是铂类化合物，与DNA鸟嘌呤N7位共价结合", "形成链内或链间交联，导致DNA双链扭曲，阻断复制和转录", "最终诱导细胞凋亡，广泛用于睾丸癌、卵巢癌、肺癌等实体瘤", "作用不依赖细胞周期，副作用包括肾毒性和神经毒性"], "check": null, "cards": [{"front": "阿糖胞苷（AraC）的作用机制是什么？", "back": "胞苷类似物，转化为三磷酸形式后竞争性抑制DNA聚合酶，并可掺入DNA导致链终止或复制错误。", "mnemonic": "假胞苷→掺进去→链断", "useImg": false}]}, {"i": 7, "sec": "原核与真核复制比较及医学联系", "title": "致谢 (p98)", "notes": "本页为致谢页，表示课程内容结束。", "page": 98, "level": "了解", "img": "assets/img/ch03/p098.jpg", "anim": null, "fig": null, "points": ["本页为致谢页，表示课程内容结束", "无核心考点"], "check": null, "cards": [{"front": "阿糖胞苷（AraC）主要用于治疗什么？属于哪类药物？", "back": "主要用于急性髓系白血病；属于细胞周期特异性药物。", "mnemonic": "AraC治急髓，周期特异性", "useImg": false}]}, {"i": 8, "sec": "原核与真核复制比较及医学联系", "title": "DNA聚合酶III的分阶段组装 (p99)", "notes": "本页详细描述了大肠杆菌DNA聚合酶III全酶的分阶段组装过程：第一阶段，夹钳装载机水解ATP，将β夹钳装载到DNA上；第二阶段，核心酶结合到夹钳上，Tau蛋白连接另一个核心酶，形成对称的二聚体；第三阶段，前导链和后随链同时合成。这种结构使得DNA聚合酶III能够高效地同时合成两条链，体现了复制体的精密组织。", "page": 99, "level": "理解", "img": "assets/img/ch03/p099.jpg", "anim": null, "fig": null, "points": ["第一阶段：夹钳装载机水解ATP，将β夹钳装载到DNA上", "第二阶段：核心酶结合到夹钳上，Tau蛋白连接另一个核心酶，形成对称二聚体", "第三阶段：前导链和后随链同时合成", "该结构使DNA聚合酶III高效同时合成两条链，体现复制体精密组织"], "check": null, "cards": [{"front": "顺铂的作用机制是什么？", "back": "铂类化合物，与DNA鸟嘌呤N7位共价结合，形成链内/链间交联，使DNA双链扭曲，阻断复制和转录，诱导细胞凋亡。", "mnemonic": "铂连鸟嘌呤→DNA扭曲→凋亡", "useImg": false}]}, {"i": 9, "sec": "原核与真核复制比较及医学联系", "title": "复制体 (p100)", "notes": "本页为示意图，展示复制体（replisome）的整体结构。复制体是由多种蛋白质组成的复合体，包括解旋酶、引物酶、DNA聚合酶、单链结合蛋白、夹钳装载机等，它们协同工作，在复制叉上高效合成DNA。原核与真核的复制体组成有所不同，但基本功能相似。", "page": 100, "level": "理解", "img": "assets/img/ch03/p100.jpg", "anim": null, "fig": "观察复制体示意图时，注意识别复制叉上各蛋白质的位置和相互作用。重点看解旋酶如何解开双链，引物酶如何合成引物，DNA聚合酶如何延伸新链，以及单链结合蛋白和夹钳装载机等辅助蛋白的协同作用。", "points": ["复制体是由多种蛋白质组成的复合体，包括解旋酶、引物酶、DNA聚合酶、单链结合蛋白、夹钳装载机等", "各组分协同工作，在复制叉上高效合成DNA", "原核与真核复制体组成有所不同，但基本功能相似", "理解复制体整体结构有助于掌握复制机制"], "check": null, "cards": [{"front": "顺铂主要用于治疗哪些肿瘤？有什么主要副作用？", "back": "用于睾丸癌、卵巢癌、肺癌等实体瘤；副作用包括肾毒性和神经毒性。", "mnemonic": "顺铂治实体瘤，肾神要小心", "useImg": false}]}, {"i": 10, "sec": "原核与真核复制比较及医学联系", "title": "原核与真核复制叉蛋白比较 (p101)", "notes": "本页对比了原核生物（大肠杆菌）与真核生物在复制叉上关键蛋白的对应关系：解旋酶DnaB对应CMG；单链结合蛋白SSB对应RPA；DNA聚合酶III对应Pol ε/Pol δ；β夹钳对应PCNA；夹钳装载机对应RFC；引物酶对应Pol α–引物酶；去除引物的Pol I对应RNase H和FEN1等；连接酶对应DNA连接酶I。这些对应关系显示了复制机制在进化上的保守性，同时也体现了真核生物复制更加复杂和精细。", "page": 101, "level": "掌握", "img": "assets/img/ch03/p101.jpg", "anim": null, "fig": null, "points": ["解旋酶：原核DnaB对应真核CMG", "单链结合蛋白：原核SSB对应真核RPA", "DNA聚合酶：原核Pol III对应真核Pol ε/Pol δ", "夹钳与装载机：原核β夹钳/夹钳装载机对应真核PCNA/RFC", "引物酶：原核引物酶对应真核Pol α–引物酶；去除引物：原核Pol I对应真核RNase H和FEN1；连接酶：原核连接酶对应真核DNA连接酶I", "这些对应关系显示复制机制在进化上的保守性，真核复制更复杂"], "check": null, "cards": [{"front": "大肠杆菌DNA聚合酶III全酶分阶段组装的过程是怎样的？", "back": "第一阶段：夹钳装载机水解ATP，将β夹钳装载到DNA上；第二阶段：核心酶结合夹钳，Tau蛋白连接另一核心酶形成对称二聚体；第三阶段：前导链和后随链同时合成。", "mnemonic": "装夹→连核→双链同合", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_36", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "下列哪项不是原核生物与真核生物DNA复制的共同点？", "o": ["A. 半保留复制", "B. 半不连续复制", "C. 多复制起点", "D. RNA引物"], "a": "C", "e": "原核生物通常只有一个复制起点，而真核生物有多个复制起点，因此多复制起点不是共同点。", "kp": "ch03_s7_0"}, {"id": "ch03_mcq_37", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "5-氟尿嘧啶（5-FU）抗肿瘤的主要机制是？", "o": ["A. 直接损伤DNA", "B. 抑制核苷酸前体的合成", "C. 抑制DNA聚合酶活性", "D. 抑制解旋酶"], "a": "B", "e": "5-FU是核苷酸前体类似物，通过抑制嘧啶合成，使DNA聚合酶缺乏底物，从而抑制DNA复制。", "kp": "ch03_s7_4"}, {"id": "ch03_mcq_38", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "顺铂（Cisplatin）抗肿瘤的作用机制是？", "o": ["A. 嵌入DNA双螺旋", "B. 与DNA形成交联，阻断复制", "C. 抑制拓扑异构酶", "D. 抑制微管解聚"], "a": "B", "e": "顺铂与DNA鸟嘌呤N7位共价结合，形成链内或链间交联，导致DNA复制和转录受阻。", "kp": "ch03_s7_6"}, {"id": "ch03_mcq_39", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "真核生物复制叉上，负责去除RNA引物的主要酶是？", "o": ["A. Pol I", "B. RNase H和FEN1", "C. DNA连接酶I", "D. Pol α"], "a": "B", "e": "真核生物中，RNA引物由RNase H和FEN1等去除，而原核生物中由Pol I去除。", "kp": "ch03_s7_0"}, {"id": "ch03_mcq_40", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "关于原核与真核DNA复制的差异，下列哪项正确？", "o": ["A. 原核生物复制速度比真核生物慢", "B. 真核生物冈崎片段比原核生物长", "C. 真核生物有端粒和端粒酶", "D. 原核生物复制周期与细胞周期重叠"], "a": "C", "e": "真核生物线性染色体末端有端粒，需要端粒酶维持；原核生物环状DNA无端粒。原核复制速度快，冈崎片段长，复制周期与细胞周期不重叠。", "kp": "ch03_s7_1"}], "judge": [], "fill": [], "short": [], "calc": [{"id": "ch03_calc_1", "modI": 7, "q": "论述DNA复制过程中如何保证高保真性，并比较原核与真核生物在复制机制上的主要异同。", "a": "高保真性保证机制：1）碱基互补配对：G-C、A-T严格配对，一条链上的核苷酸排列决定另一条链的核苷酸排列；2）DNA聚合酶的校对功能：3'→5'外切活性可切除错配核苷酸，再重新掺入正确核苷酸；错误核苷酸掺入速率比正确者慢约10,000倍；3）错配修复系统：复制后修复进一步降低突变率；4）复制高度准确，合成过程中通常每10^10个碱基才出现一个错误。原核与真核复制机制主要异同：相同点：均为半保留复制；均从复制起点起始；均双向进行；均需要聚合酶、解旋酶、引发酶、拓扑异构酶等；前导链连续合成，后随链不连续合成；均需要RNA引物；均遵循5′→3′合成方向。不同点：原核生物通常只有一个复制起点，真核生物每条染色体含多个复制起点；原核生物复制速度约100-1000 bp/秒，真核生物约25-50 bp/秒；原核生物DNA聚合酶主要有Pol Ⅰ、Ⅱ、Ⅲ，真核生物有15种以上，哺乳动物主要有5种，分工更细；真核生物存在端粒和端粒酶解决线性染色体末端复制问题；真核生物复制受细胞周期检查点严格调控，每个复制子在一个细胞周期中只能复制一次。", "steps": "高保真性：碱基互补配对、聚合酶校对、错配修复、极低错误率；原核与真核相同点：半保留、起点起始、双向、酶类、半不连续、RNA引物、5′→3′；不同点：起点数量、复制速度、聚合酶种类与分工、端粒与端粒酶、细胞周期调控。", "kp": "ch03_s7_0"}], "term": []}], "mcq": [{"id": "ch03_mcq_1", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "DNA半保留复制是指子代DNA分子中：", "o": ["A. 两条链均来自亲代DNA", "B. 一条链来自亲代DNA，另一条链为新合成", "C. 两条链均为新合成", "D. 亲代链和新链随机分布"], "a": "B", "e": "半保留复制中，亲代双链解开，每条链作为模板合成新链，因此每个子代DNA由一条亲代链和一条新合成链组成。", "kp": "ch03_s0_7"}, {"id": "ch03_mcq_2", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "Meselson和Stahl证明DNA半保留复制所采用的关键技术是：", "o": ["A. X射线衍射", "B. 氯化铯密度梯度离心", "C. 琼脂糖凝胶电泳", "D. 电子显微镜观察"], "a": "B", "e": "他们用15N标记DNA，通过氯化铯密度梯度离心区分不同密度的DNA，从而证明复制为半保留方式。", "kp": "ch03_s0_5"}, {"id": "ch03_mcq_3", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "关于DNA复制的一般特征，下列哪项描述正确？", "o": ["A. 原核生物复制速度比真核生物慢", "B. 复制只发生在基因组的部分区域", "C. 复制具有高保真性，错误率极低", "D. 复制不需要引物"], "a": "C", "e": "DNA复制高度准确，通常每10^10个碱基才出现一个错误；原核复制速度约100-1000 bp/秒，真核约25-50 bp/秒，且复制几乎覆盖全基因组，并需要引物。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_4", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "下列哪种酶在DNA复制中负责解开双螺旋？", "o": ["A. DNA聚合酶", "B. 解旋酶", "C. 引发酶", "D. 端粒酶"], "a": "B", "e": "解旋酶负责解开DNA双螺旋，暴露单链模板；聚合酶合成DNA，引发酶合成引物，端粒酶延长真核染色体末端。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_5", "mod": "模块一：DNA复制概述与半保留复制", "modI": 0, "q": "DNA复制过程中，后随链的合成特点是：", "o": ["A. 连续合成", "B. 不连续合成，形成多个冈崎片段", "C. 不需要模板", "D. 从3'→5'方向合成"], "a": "B", "e": "后随链的合成方向与解旋方向相反，因此以不连续方式合成，形成多个冈崎片段，再连接成完整链。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_6", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "关于复制起点（origin，ori）的叙述，正确的是：", "o": ["A. 原核生物染色体通常有多个复制起点，真核生物只有一个", "B. 复制起点是约100~300 bp、可被特异蛋白识别并启动复制的DNA片段", "C. 复制起点就是复制子，一个复制子可含多个复制起点", "D. 真核生物复制起点在每个细胞周期中可被多次激活"], "a": "B", "e": "复制起点是约100~300 bp、具有专一序列并可被特异蛋白识别启动复制的片段。原核通常一个起点，真核有多个；一个复制子只含一个复制起点；真核每个复制子一个细胞周期只复制一次。", "kp": "ch03_s1_1"}, {"id": "ch03_mcq_7", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "真核生物线形染色体复制时，通常表现为：", "o": ["A. 单起点、单向复制", "B. 单起点、双向复制", "C. 多起点、双向复制，复制叉最终汇合", "D. 多起点、单向复制，复制叉不汇合"], "a": "C", "e": "真核染色体由多个复制子构成，每个复制子有自己的起点，表现为多点起始、双向复制，相邻复制叉最终汇合完成整条染色体复制。", "kp": "ch03_s1_3"}, {"id": "ch03_mcq_8", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "冈崎片段是指：", "o": ["A. 前导链上连续合成的DNA片段", "B. 后随链上不连续合成的5′→3′小片段", "C. 复制起点被识别后形成的RNA引物", "D. 复制叉解链后形成的Y形DNA结构"], "a": "B", "e": "冈崎片段是后随链断续合成产生的5′→3′不连续小片段，原核可达约2000 nt，真核约100~200 nt，随后被连接成完整链。", "kp": "ch03_s1_6"}, {"id": "ch03_mcq_9", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "DNA复制表现为半不连续复制，根本原因主要是：", "o": ["A. DNA双链反向平行，且DNA聚合酶只能沿5′→3′方向合成", "B. DNA聚合酶只能沿3′→5′方向合成", "C. 复制起点只能单向启动复制", "D. 真核生物染色体只有一个复制子"], "a": "A", "e": "DNA双链反向平行，而DNA聚合酶只能将核苷酸加到3′-OH端，即沿5′→3′延伸，因此一条链连续合成，另一条链必须分段合成。", "kp": "ch03_s1_0"}, {"id": "ch03_mcq_10", "mod": "模块二：复制的起点、方向与半不连续复制", "modI": 1, "q": "关于前导链和后随链，叙述正确的是：", "o": ["A. 前导链合成方向与复制叉移动方向相反，后随链相同", "B. 前导链连续合成，后随链不连续合成并形成冈崎片段", "C. 前导链和后随链都完全连续合成", "D. 后随链不需要引物即可起始合成"], "a": "B", "e": "前导链合成方向与复制叉移动方向一致，可连续合成；后随链方向相反，需不断起始并形成冈崎片段，再连接成完整链。", "kp": "ch03_s1_7"}, {"id": "ch03_mcq_11", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "DNA复制中，直接作为底物被DNA聚合酶添加到新生链上的物质是：", "o": ["A. NTPs", "B. dNTPs", "C. dNDPs", "D. 单磷酸脱氧核苷"], "a": "B", "e": "DNA聚合酶以四种脱氧核苷三磷酸（dATP、dTTP、dCTP、dGTP）为底物，释放焦磷酸并提供延伸所需能量。", "kp": "ch03_s2_0"}, {"id": "ch03_mcq_12", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "关于单链结合蛋白（SSBP）的功能，下列哪项不正确？", "o": ["A. 防止单链退火形成双链", "B. 保护单链不被降解", "C. 具有序列专一性结合", "D. 可增强DNA聚合酶对单链DNA的亲和力"], "a": "C", "e": "SSBP与DNA结合时无序列专一性，可覆盖单链，防止退火和降解，并增强DNA聚合酶亲和力。", "kp": "ch03_s2_6"}, {"id": "ch03_mcq_13", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "引物酶（Primase）在DNA复制中的主要作用是：", "o": ["A. 以DNA为模板合成一段RNA引物", "B. 以RNA为模板合成DNA", "C. 切除RNA引物并填补DNA", "D. 解开DNA双螺旋"], "a": "A", "e": "引物酶本质是以DNA为模板的RNA聚合酶，合成短RNA引物，为DNA聚合酶提供3′-OH起点。", "kp": "ch03_s2_7"}, {"id": "ch03_mcq_14", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "DNA拓扑异构酶在复制过程中的主要功能是：", "o": ["A. 催化dNTP聚合", "B. 使DNA螺旋保持松弛，避免拓扑张力阻碍复制", "C. 合成RNA引物", "D. 结合单链DNA防止降解"], "a": "B", "e": "拓扑异构酶通过切断和重新连接DNA链，释放解旋产生的超螺旋张力，保证复制叉正常推进。", "kp": "ch03_s2_9"}, {"id": "ch03_mcq_15", "mod": "模块三：DNA复制相关物质（起始与辅助蛋白）", "modI": 2, "q": "Kornberg发现的DNA聚合酶催化DNA合成时，下列哪项不是必需条件？", "o": ["A. dNTPs", "B. 带游离3′-OH的模板-引物", "C. Mg2+", "D. 高能磷酸化合物如ATP"], "a": "D", "e": "DNA聚合酶反应需要dNTPs、模板-引物、DNA聚合酶和Mg2+；dNTP本身提供能量，不需额外ATP。", "kp": "ch03_s2_11"}, {"id": "ch03_mcq_16", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于DNA聚合酶催化合成反应的特点，下列哪项正确？", "o": ["A. 合成方向为3'→5'，能量来自dNTP释放两个磷酸", "B. 合成方向为5'→3'，能量来自dNTP释放两个磷酸", "C. 合成方向为5'→3'，能量来自ATP水解", "D. 合成方向为3'→5'，能量来自ATP水解"], "a": "B", "e": "DNA聚合酶催化3'-OH与dNTP的5'-磷酸形成磷酸二酯键，合成方向为5'→3'，能量来自dNTP释放两个磷酸。", "kp": "ch03_s3_0"}, {"id": "ch03_mcq_17", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "在大肠杆菌中，主要负责DNA复制并具有3'→5'外切校对功能的是：", "o": ["A. DNA聚合酶Ⅰ", "B. DNA聚合酶Ⅱ", "C. DNA聚合酶Ⅲ", "D. DNA连接酶"], "a": "C", "e": "DNA聚合酶Ⅲ是复制的主要酶，具3'→5'外切活性，可校对错误掺入的核苷酸，提高保真性。", "kp": "ch03_s3_1"}, {"id": "ch03_mcq_18", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于滑动钳（sliding clamp）的作用，正确的是：", "o": ["A. 催化磷酸二酯键形成", "B. 切除RNA引物", "C. 提高DNA聚合酶的持续合成能力", "D. 连接DNA切口"], "a": "C", "e": "滑动钳为环状蛋白，套在DNA上并锚定聚合酶，防止其脱落，显著提高持续合成能力。", "kp": "ch03_s3_8"}, {"id": "ch03_mcq_19", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "真核生物中，主要负责前导链合成的DNA聚合酶是：", "o": ["A. Pol α", "B. Pol β", "C. Pol δ", "D. Pol ε"], "a": "D", "e": "Pol ε主要负责前导链合成；Pol δ主要负责后随链合成；Pol α参与起始；Pol β参与修复。", "kp": "ch03_s3_12"}, {"id": "ch03_mcq_20", "mod": "模块四：DNA聚合酶与DNA连接酶", "modI": 3, "q": "关于DNA连接酶，下列描述正确的是：", "o": ["A. 能连接两条游离的DNA单链", "B. 催化3'-OH与5'-磷酸基形成磷酸二酯键", "C. 合成方向为5'→3'", "D. 需要模板指导"], "a": "B", "e": "DNA连接酶催化双链DNA切口处3'-OH与5'-磷酸基形成磷酸二酯键，不能连接游离单链，也不需要模板。", "kp": "ch03_s3_15"}, {"id": "ch03_mcq_21", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "双链环状DNA复制的主要方式不包括以下哪一项？", "o": ["A. θ型复制", "B. 滚环型复制", "C. D-环型复制", "D. 线性复制"], "a": "D", "e": "双链环状DNA复制主要有θ型、滚环型和D-环型三种，线性复制是双链线性DNA的复制方式。", "kp": "ch03_s4_0"}, {"id": "ch03_mcq_22", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "θ型复制中，复制叉的移动方向是？", "o": ["A. 单向移动", "B. 双向移动", "C. 随机移动", "D. 不移动"], "a": "B", "e": "θ型复制中两个复制叉从起点开始以相反方向沿染色体移动，形成θ形中间体。", "kp": "ch03_s4_4"}, {"id": "ch03_mcq_23", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "滚环型复制中，正链合成不需要下列哪种物质？", "o": ["A. DNA聚合酶", "B. RNA引物", "C. 模板链", "D. 3'-OH"], "a": "B", "e": "滚环型复制中正链合成不需RNA引物，直接在正链3'-OH上延伸。", "kp": "ch03_s4_5"}, {"id": "ch03_mcq_24", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "D-环型复制首先在哪种细胞器中被发现？", "o": ["A. 细胞核", "B. 线粒体", "C. 叶绿体", "D. 核糖体"], "a": "B", "e": "D-环型复制首先在动物线粒体中被发现，其两条链复制起点不同且不同步。", "kp": "ch03_s4_7"}, {"id": "ch03_mcq_25", "mod": "模块五：DNA复制的主要方式", "modI": 4, "q": "关于D-环型复制，下列描述正确的是？", "o": ["A. 两条链同步复制", "B. 两条链复制起点相同", "C. 两条链合成高度不对称", "D. 不需要RNA参与"], "a": "C", "e": "D-环型复制中一条短RNA与一条DNA互补，取代原链，使两条链合成高度不对称，且复制起点不同、不同步。", "kp": "ch03_s4_7"}, {"id": "ch03_mcq_26", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌复制起点oriC中，9 bp重复序列的主要功能是：", "o": ["A. 作为DnaA蛋白的结合位点", "B. 作为DnaB解旋酶的加载位点", "C. 作为引物合成的起始位点", "D. 作为复制终止的识别序列"], "a": "A", "e": "oriC中的9 bp重复序列是起始蛋白DnaA的结合位点，DnaA结合后促使13 bp重复序列区域解链，从而启动复制。", "kp": "ch03_s5_4"}, {"id": "ch03_mcq_27", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "在大肠杆菌DNA复制终止过程中，Tus蛋白的作用是：", "o": ["A. 促进复制叉前移", "B. 作为反解旋酶阻止复制叉前移", "C. 合成RNA引物", "D. 切除冈崎片段"], "a": "B", "e": "Tus蛋白识别Ter序列并与之结合形成Ter-Tus复合物，具有反解旋酶活性，抑制DnaB解旋酶活性，阻止复制叉前移。", "kp": "ch03_s5_3"}, {"id": "ch03_mcq_28", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "关于大肠杆菌DNA复制中的“长号模型”，下列描述正确的是：", "o": ["A. 前导链不连续合成，后随链连续合成", "B. 前导链和后随链由不同复制体独立合成", "C. 后随链模板形成环状结构，前导链和后随链协同合成", "D. 后随链的合成不需要RNA引物"], "a": "C", "e": "长号模型描述后随链模板在复制体中形成环状结构，前导链连续合成、后随链不连续合成，二者由同一复制体协同完成。", "kp": "ch03_s5_3"}, {"id": "ch03_mcq_29", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌环状染色体复制完成后，子代DNA分子的分离需要：", "o": ["A. I型拓扑异构酶", "B. II型拓扑异构酶", "C. 解旋酶DnaB", "D. Tus蛋白"], "a": "B", "e": "环状染色体复制完成后，两个子代DNA分子相互缠绕，需要II型拓扑异构酶切开并重新连接DNA链，使子代分子分离。", "kp": "ch03_s5_0"}, {"id": "ch03_mcq_30", "mod": "模块六：大肠杆菌DNA复制的过程", "modI": 5, "q": "大肠杆菌复制终止区Ter序列的特点是：", "o": ["A. 仅含一个拷贝的23 bp序列", "B. 含多个拷贝的23 bp序列", "C. 含多个拷贝的9 bp序列", "D. 含多个拷贝的13 bp序列"], "a": "B", "e": "大肠杆菌复制终止区含有多个拷贝的23 bp终止序列Ter，两个复制叉在此区域相遇并终止复制。", "kp": "ch03_s5_8"}, {"id": "ch03_mcq_31", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "真核生物保证每个细胞周期DNA只复制一次的关键调控环节是？", "o": ["A. 复制起点许可（pre-RC组装）与CDK活性的周期性变化", "B. DNA聚合酶合成速度的调节", "C. 核小体组装速度的调节", "D. 端粒酶活性的调节"], "a": "A", "e": "真核生物通过起点许可和CDK周期性调控，使pre-RC在低CDK时组装、高CDK时激活并抑制再组装，从而保证每个起点每周期只起始一次。", "kp": "ch03_s6_1"}, {"id": "ch03_mcq_32", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "端粒酶解决末端复制问题的主要机制是？", "o": ["A. 以DNA为模板合成端粒重复序列", "B. 以自身RNA为模板逆转录延伸染色体3’末端", "C. 直接填补去除RNA引物后的5’端缺口", "D. 切除染色体末端以维持长度"], "a": "B", "e": "端粒酶是RNA-蛋白质复合物，其RNA含互补模板，蛋白质具逆转录酶活性，可延伸染色体3’末端，为常规复制提供模板。", "kp": "ch03_s6_12"}, {"id": "ch03_mcq_33", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "关于端粒功能，下列哪项不正确？", "o": ["A. 保护染色体末端不被识别为DNA损伤", "B. 参与染色体在细胞核中的空间组织", "C. 端粒缩短可激活DNA损伤反应导致细胞衰老", "D. 端粒酶在所有正常成体细胞中均高度表达"], "a": "D", "e": "端粒酶在胎儿发育和干细胞、生殖细胞等增殖细胞中活跃，但在许多成体细胞中下调；约90%肿瘤中高度活跃。", "kp": "ch03_s6_6"}, {"id": "ch03_mcq_34", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "关于复制后核小体/组蛋白分配的半保守模型，正确的是？", "o": ["A. 亲代(H3-H4)₂四聚体完整分配给一条子链", "B. 亲代(H3-H4)₂四聚体拆分为两个H3-H4二聚体，分别进入两条子链", "C. 亲代组蛋白全部降解，子代全部使用新合成组蛋白", "D. 亲代组蛋白随机分配到子链或保持完整，无规律"], "a": "B", "e": "半保守模型认为亲代(H3-H4)₂四聚体在复制叉处拆分为两个二聚体，分别分配到两条子链，再与新合成二聚体配对，是解释组蛋白修饰遗传的重要机制。", "kp": "ch03_s6_19"}, {"id": "ch03_mcq_35", "mod": "模块七：真核生物DNA复制特点与端粒", "modI": 6, "q": "真核生物复制起点“可被被动复制”的含义是？", "o": ["A. 所有起点必须在同一时间激活", "B. 未激活的起点可由邻近复制叉复制", "C. 起点只能被端粒酶复制", "D. 起点复制不需要MCM解旋酶"], "a": "B", "e": "真核复制起点激活有时序性，若某起点未激活，相邻起点形成的复制叉可被动复制该区域，但整体仍需保证S期内完成复制。", "kp": "ch03_s6_2"}, {"id": "ch03_mcq_36", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "下列哪项不是原核生物与真核生物DNA复制的共同点？", "o": ["A. 半保留复制", "B. 半不连续复制", "C. 多复制起点", "D. RNA引物"], "a": "C", "e": "原核生物通常只有一个复制起点，而真核生物有多个复制起点，因此多复制起点不是共同点。", "kp": "ch03_s7_0"}, {"id": "ch03_mcq_37", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "5-氟尿嘧啶（5-FU）抗肿瘤的主要机制是？", "o": ["A. 直接损伤DNA", "B. 抑制核苷酸前体的合成", "C. 抑制DNA聚合酶活性", "D. 抑制解旋酶"], "a": "B", "e": "5-FU是核苷酸前体类似物，通过抑制嘧啶合成，使DNA聚合酶缺乏底物，从而抑制DNA复制。", "kp": "ch03_s7_4"}, {"id": "ch03_mcq_38", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "顺铂（Cisplatin）抗肿瘤的作用机制是？", "o": ["A. 嵌入DNA双螺旋", "B. 与DNA形成交联，阻断复制", "C. 抑制拓扑异构酶", "D. 抑制微管解聚"], "a": "B", "e": "顺铂与DNA鸟嘌呤N7位共价结合，形成链内或链间交联，导致DNA复制和转录受阻。", "kp": "ch03_s7_6"}, {"id": "ch03_mcq_39", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "真核生物复制叉上，负责去除RNA引物的主要酶是？", "o": ["A. Pol I", "B. RNase H和FEN1", "C. DNA连接酶I", "D. Pol α"], "a": "B", "e": "真核生物中，RNA引物由RNase H和FEN1等去除，而原核生物中由Pol I去除。", "kp": "ch03_s7_0"}, {"id": "ch03_mcq_40", "mod": "模块八：原核与真核复制比较及医学联系", "modI": 7, "q": "关于原核与真核DNA复制的差异，下列哪项正确？", "o": ["A. 原核生物复制速度比真核生物慢", "B. 真核生物冈崎片段比原核生物长", "C. 真核生物有端粒和端粒酶", "D. 原核生物复制周期与细胞周期重叠"], "a": "C", "e": "真核生物线性染色体末端有端粒，需要端粒酶维持；原核生物环状DNA无端粒。原核复制速度快，冈崎片段长，复制周期与细胞周期不重叠。", "kp": "ch03_s7_1"}], "judge": [{"id": "ch03_judge_1", "modI": 0, "q": "DNA复制是中心法则中遗传信息流的第一环节，只有复制准确进行，转录和翻译才有可靠的模板。", "a": "对", "e": "中心法则描述遗传信息在生物大分子间传递的基本规律：DNA通过复制将遗传信息传给子代DNA，通过转录将信息传给RNA，再通过翻译合成蛋白质；DNA复制处于中心法则的起点。", "kp": "ch03_s0_2"}, {"id": "ch03_judge_2", "modI": 0, "q": "Meselson-Stahl实验第一代DNA全部为轻密度DNA，第二代出现杂合密度和轻密度DNA各半。", "a": "错", "e": "第一代全部为杂合密度DNA（一条重链一条轻链），第二代出现杂合密度和轻密度DNA各半。", "kp": "ch03_s0_5"}, {"id": "ch03_judge_3", "modI": 1, "q": "原核生物通常只有一个复制起始位点，而真核生物每条染色体含多个复制子、多个复制起点。", "a": "对", "e": "原核生物通常只有一个复制起始位点，如大肠杆菌oriC；真核生物每条染色体含多个复制子、多个复制起点，一个细胞周期中可激活约5万~10万个起点。", "kp": "ch03_s1_1"}, {"id": "ch03_judge_4", "modI": 1, "q": "冈崎片段是前导链上连续合成的小片段，原核生物可达约2000 nt，真核生物约100~200 nt。", "a": "错", "e": "冈崎片段是后随链上不连续合成的小片段，原核生物可达约2000 nt，真核生物约100~200 nt。", "kp": "ch03_s1_7"}, {"id": "ch03_judge_5", "modI": 2, "q": "DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH。", "a": "对", "e": "DNA聚合酶不能从头起始合成，必须依赖一段引物提供游离3′-OH；引物通常是一段短RNA链，能与模板DNA的一条链互补配对，其3′-OH作为DNA聚合酶的起点。", "kp": "ch03_s2_8"}, {"id": "ch03_judge_6", "modI": 2, "q": "DNA拓扑异构酶I型切开双链且需消耗能量，II型酶切开单链并改变连接数。", "a": "错", "e": "I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶。", "kp": "ch03_s2_9"}, {"id": "ch03_judge_7", "modI": 3, "q": "DNA聚合酶Ⅲ的β亚基形成环状滑动钳，作为持续合成因子，使聚合酶不易脱落，极大提高持续合成能力。", "a": "对", "e": "DNA聚合酶Ⅲ由多个亚基组成，β亚基形成环状滑动钳，作为持续合成因子；滑动钳环状结构使聚合酶不易脱落，极大提高持续合成能力。", "kp": "ch03_s3_5"}, {"id": "ch03_judge_8", "modI": 3, "q": "DNA连接酶能将两条游离的DNA单链连接起来。", "a": "错", "e": "DNA连接酶不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口。", "kp": "ch03_s3_15"}, {"id": "ch03_judge_9", "modI": 4, "q": "θ型复制中复制叉双向移动，中间体呈θ形，常见于细菌环状染色体和质粒。", "a": "对", "e": "θ型复制是双链环形DNA分子从复制起始点开始，两个复制叉以相反方向沿染色体移动，复制中间体形状类似希腊字母θ；该方式常见于细菌环状染色体和质粒。", "kp": "ch03_s4_2"}, {"id": "ch03_judge_10", "modI": 6, "q": "真核生物DNA复制时，Pol ε主要负责后随链合成，Pol δ主要负责前导链合成。", "a": "错", "e": "真核生物DNA复制时，Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成。", "kp": "ch03_s6_0"}], "fill": [{"id": "ch03_fill_1", "modI": 0, "q": "DNA复制是指以________为模板合成一个新的子代DNA分子的过程，复制发生在细胞分裂前的________期（真核）。", "a": "亲代DNA分子,S", "kp": "ch03_s0_3"}, {"id": "ch03_fill_2", "modI": 0, "q": "1958年Meselson和Stahl利用________技术，以大肠杆菌为材料，通过________标记亲代DNA，追踪复制后DNA在离心管中的密度位置，实验结果支持________复制。", "a": "氯化铯密度梯度离心,15N,半保留", "kp": "ch03_s0_5"}, {"id": "ch03_fill_3", "modI": 1, "q": "复制起点是DNA分子上约________ bp、具有专一核苷酸顺序的片段，可被特异蛋白识别并启动复制；大肠杆菌oriC全长________ bp，且在细菌中高度保守。", "a": "100~300,245", "kp": "ch03_s1_1"}, {"id": "ch03_fill_4", "modI": 1, "q": "复制子指从复制起点到复制终点所组成的一个独立复制单位，一个复制子只含________个复制起点；哺乳动物细胞约有________个复制子，每个复制子长约________ kb。", "a": "一,50000~100000,50~200", "kp": "ch03_s1_2"}, {"id": "ch03_fill_5", "modI": 1, "q": "由于DNA双链反向平行且DNA聚合酶只能沿________方向合成，复制叉两条模板链的合成方式不同，从而引出________链与________链、冈崎片段等概念。", "a": "5′→3′,前导,后随", "kp": "ch03_s1_0"}, {"id": "ch03_fill_6", "modI": 2, "q": "dNTPs即dATP、dTTP、dCTP、dGTP，是DNA合成的直接底物；复制时，DNA聚合酶催化dNTP的________磷酸与新生链3′-OH形成磷酸二酯键，同时释放________。", "a": "α,焦磷酸", "kp": "ch03_s2_2"}, {"id": "ch03_fill_7", "modI": 3, "q": "DNA聚合酶催化脱氧核糖3'-OH与dNTP的5'-磷酸之间形成磷酸二酯键，反应能量来自dNTP释放两个磷酸；合成方向为________，速率可达________ dNTPs/秒。", "a": "5'→3',800", "kp": "ch03_s3_0"}, {"id": "ch03_fill_8", "modI": 3, "q": "大肠杆菌主要有DNA聚合酶Ⅰ、Ⅱ、Ⅲ；Pol Ⅰ主要切除________并填补空隙、修复损伤；Pol Ⅲ是复制主要酶，具________外切校对功能，提高保真性。", "a": "RNA引物,3'→5'", "kp": "ch03_s3_1"}, {"id": "ch03_fill_9", "modI": 6, "q": "真核生物DNA复制起始时，Pol α合成________引物，随后在滑动钳装载器（RFC）和滑动钳（PCNA）帮助下，Pol δ或Pol ε替换Pol α，分别延伸________链和________链。", "a": "RNA-DNA,后随,前导", "kp": "ch03_s6_0"}, {"id": "ch03_fill_10", "modI": 4, "q": "双链环状DNA复制主要有三种类型：________复制、________复制和________复制。", "a": "θ型,滚环型,D-环型", "kp": "ch03_s4_1"}], "short": [{"id": "ch03_short_1", "modI": 0, "q": "简述DNA半保留复制的定义及其分子基础，并说明Meselson-Stahl实验如何证明半保留复制。", "a": "定义：以亲代DNA双链为模板，以碱基互补方式合成子代DNA，在新形成的子代DNA中，一条链来自亲代DNA，另一条链是新合成的。分子基础：G-C、A-T的严格配对，一条链上的核苷酸排列即可决定另一条链的核苷酸排列，从而保证遗传信息精确复制。Meselson-Stahl实验：1958年利用氯化铯密度梯度离心技术，以大肠杆菌为材料，通过15N标记亲代DNA，追踪复制后DNA在离心管中的密度位置；第一代全部为杂合密度DNA，第二代出现杂合密度和轻密度DNA各半，从而否定了全保留和弥散复制模型，支持半保留复制。", "kp": "ch03_s0_6"}, {"id": "ch03_short_2", "modI": 1, "q": "简述DNA复制中前导链和后随链的合成特点，并解释半不连续复制的原因。", "a": "前导链：合成方向与复制叉移动方向一致，可连续合成。后随链：合成方向与复制叉移动方向相反，随复制叉前进不断形成不连续片段（冈崎片段），再连接成完整DNA链。半不连续复制的原因：DNA双链反向平行，而DNA聚合酶只能将新核苷酸加到3′-OH末端，即只能沿5′→3′方向合成；因此复制叉处一条模板链可连续合成前导链，另一条模板链只能反向、分段合成后随链。该机制解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾。", "kp": "ch03_s1_0"}, {"id": "ch03_short_3", "modI": 2, "q": "简述DNA复制相关物质（复制机器）的主要组成及其功能。", "a": "复制机器包括：底物dNTPs，提供核苷酸单元和能量；模板DNA，亲代DNA两条链分别作为模板；解旋酶，利用ATP水解能量破坏氢键，解开双螺旋；单链结合蛋白，与暴露的单链结合，防止重新退火或形成二级结构，并保护单链；引物酶，以DNA为模板合成短RNA引物，提供3′-OH；引物，提供游离3′-OH作为DNA聚合酶起点；拓扑异构酶，调节DNA拓扑状态，释放超螺旋张力；DNA聚合酶，以DNA为模板催化dNTP合成DNA，并具有校对功能。各因子在时间和空间上精密配合，协同完成复制。", "kp": "ch03_s2_0"}, {"id": "ch03_short_4", "modI": 3, "q": "简述大肠杆菌DNA聚合酶Ⅰ、Ⅱ、Ⅲ的主要性质与功能差异。", "a": "Pol Ⅰ：具中等5'→3'聚合活性、3'→5'外切活性和5'→3'外切活性；主要切除RNA引物并填补空隙、修复损伤；其5'→3'外切活性参与切口平移。Pol Ⅱ：聚合活性很低，主要参与修复。Pol Ⅲ：聚合活性很高，是复制主要酶，具3'→5'外切校对功能，提高保真性；由多个亚基组成，核心酶含α（5'→3'聚合）、ε（3'→5'外切校对）、θ（组装核心酶并促进ε活性）；τ亚基连接核心酶与滑动钳装载器；β亚基形成环状滑动钳，作为持续合成因子。三者功能分工体现了复制与修复的协调。", "kp": "ch03_s3_1"}, {"id": "ch03_short_5", "modI": 6, "q": "简述真核生物DNA复制的主要特点，包括多起点复制、聚合酶分工和端粒问题。", "a": "多起点复制：真核生物每条染色体含多个复制子、多个复制起点，一个细胞周期中可激活约5万~10万个起点；复制时表现为多点起始、双向复制，相邻复制子的复制叉最终相遇并汇合，完成整条染色体的复制；每个复制子在一个细胞周期中只能复制一次。聚合酶分工：真核生物已发现15种以上DNA聚合酶，哺乳动物主要有5种；Pol α与引物酶共同启动复制，形成RNA-DNA引物；Pol β参与碱基切除修复；Pol γ负责线粒体DNA复制；Pol δ主要负责后随链合成并参与修复；Pol ε主要负责前导链合成。端粒问题：真核线性染色体末端存在复制问题，端粒酶解决真核线性染色体末端复制问题。", "kp": "ch03_s6_0"}], "calc": [{"id": "ch03_calc_1", "modI": 7, "q": "论述DNA复制过程中如何保证高保真性，并比较原核与真核生物在复制机制上的主要异同。", "a": "高保真性保证机制：1）碱基互补配对：G-C、A-T严格配对，一条链上的核苷酸排列决定另一条链的核苷酸排列；2）DNA聚合酶的校对功能：3'→5'外切活性可切除错配核苷酸，再重新掺入正确核苷酸；错误核苷酸掺入速率比正确者慢约10,000倍；3）错配修复系统：复制后修复进一步降低突变率；4）复制高度准确，合成过程中通常每10^10个碱基才出现一个错误。原核与真核复制机制主要异同：相同点：均为半保留复制；均从复制起点起始；均双向进行；均需要聚合酶、解旋酶、引发酶、拓扑异构酶等；前导链连续合成，后随链不连续合成；均需要RNA引物；均遵循5′→3′合成方向。不同点：原核生物通常只有一个复制起点，真核生物每条染色体含多个复制起点；原核生物复制速度约100-1000 bp/秒，真核生物约25-50 bp/秒；原核生物DNA聚合酶主要有Pol Ⅰ、Ⅱ、Ⅲ，真核生物有15种以上，哺乳动物主要有5种，分工更细；真核生物存在端粒和端粒酶解决线性染色体末端复制问题；真核生物复制受细胞周期检查点严格调控，每个复制子在一个细胞周期中只能复制一次。", "steps": "高保真性：碱基互补配对、聚合酶校对、错配修复、极低错误率；原核与真核相同点：半保留、起点起始、双向、酶类、半不连续、RNA引物、5′→3′；不同点：起点数量、复制速度、聚合酶种类与分工、端粒与端粒酶、细胞周期调控。", "kp": "ch03_s7_0"}, {"id": "ch03_calc_2", "modI": 5, "q": "论述大肠杆菌DNA复制的过程，包括起始、延伸和终止阶段，并说明复制体各组分如何协同工作。", "a": "起始阶段：复制起点oriC（245 bp，高度保守）被特异蛋白识别；解旋酶在复制叉前方解开双链，单链结合蛋白稳定暴露的单链；拓扑异构酶缓解超螺旋张力；引物酶合成RNA引物，提供3′-OH。延伸阶段：DNA聚合酶Ⅲ全酶在复制叉上组装；滑动钳装载器利用ATP水解能量将β滑动钳打开并装载到DNA上，聚合酶核心酶结合滑动钳后获得高持续合成能力；两个核心酶分别负责前导链和后随链合成；前导链连续合成，后随链不连续合成冈崎片段；Pol Ⅲ的τ亚基可刺激解旋酶活性约10倍，解旋酶又刺激引物酶活性约1000倍，滑动钳则刺激Pol Ⅲ活性，形成正反馈，使解旋、引物合成和DNA聚合紧密偶联。终止阶段：复制叉相遇，RNA引物被切除并由DNA填补，DNA连接酶封闭切口，形成完整DNA链。复制体各组分协同：复制体包括DNA聚合酶、解旋酶、引物酶、滑动钳、装载器及单链结合蛋白等；各组分协同工作，实现DNA双链解开、RNA引物合成、前导链和后随链同步延伸；复制体的组装与动态变化保证了复制快速、准确进行。", "steps": "起始：oriC识别、解旋、SSBP稳定、拓扑异构酶松弛、引物酶合成引物；延伸：Pol Ⅲ全酶组装、滑动钳装载、前导链连续/后随链不连续、τ-解旋酶-引物酶-滑动钳正反馈协同；终止：复制叉相遇、引物切除、填补、连接酶封闭；复制体协同：多组分复合机器，时空精密配合。", "kp": "ch03_s5_3"}], "term": [{"id": "ch03_term_1", "modI": 0, "term": "Semi-conservative replication", "def": "半保留复制：以亲代DNA双链为模板，按碱基互补配对合成子代DNA；每个子代DNA分子中一条链来自亲代，另一条链为新合成；由Meselson-Stahl实验证实；是DNA复制的基本规律。", "kp": "ch03_s0_5"}, {"id": "ch03_term_2", "modI": 1, "term": "Origin of replication (ori)", "def": "复制起点：DNA分子上约100~300 bp、具有专一核苷酸顺序的片段；可被特异蛋白识别并启动复制；原核生物通常只有一个，如大肠杆菌oriC全长245 bp且高度保守；真核生物每条染色体含多个复制起点。", "kp": "ch03_s1_4"}, {"id": "ch03_term_3", "modI": 1, "term": "Replicon", "def": "复制子：从复制起点到复制终点所组成的一个独立复制单位；一个复制子只含一个复制起点；原核生物染色体、噬菌体通常只有一个复制子；真核生物染色体由多个复制子组成，哺乳动物细胞约有50,000~100,000个复制子，每个长约50~200 kb；每个复制子在一个细胞周期中只能复制一次。", "kp": "ch03_s1_2"}, {"id": "ch03_term_4", "modI": 1, "term": "Replication fork", "def": "复制叉：DNA复制时解链酶等解开双链后形成的复制点；因形状呈叉状而得名，也称Y形DNA结构；复制叉处进行模板链解旋、引物合成、DNA聚合酶延伸及后随链加工等反应；可沿DNA向一个或两个方向移动；真核生物多复制子通常双向复制，形成两个移动方向相反的复制叉。", "kp": "ch03_s1_4"}, {"id": "ch03_term_5", "modI": 1, "term": "Semi-discontinuous replication", "def": "半不连续复制：DNA复制过程中一条链连续合成，另一条链不连续合成；前导链合成方向与复制叉移动方向一致，可连续合成；后随链合成方向与复制叉移动方向相反，随复制叉前进不断形成不连续片段，再连接成完整DNA链；由冈崎令治和冈崎恒子等提出并发现冈崎片段；解决了DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾。", "kp": "ch03_s1_4"}, {"id": "ch03_term_6", "modI": 1, "term": "Okazaki fragments", "def": "冈崎片段：后随链上不连续合成的小片段；原核生物可达约2000 nt，真核生物约100~200 nt；后随链先合成许多短片段，再由DNA连接酶等连接成完整链；在生物界具有普遍性，反映了DNA聚合酶只能5′→3′合成以及双链反向平行所决定的半不连续复制机制。", "kp": "ch03_s1_7"}, {"id": "ch03_term_7", "modI": 2, "term": "DNA helicase", "def": "DNA解旋酶/解链酶：促进DNA双链分开的酶；利用ATP水解提供的能量破坏碱基对间的氢键，使双螺旋在复制叉处解开；沿DNA链移动，不断暴露单链模板，为后续引物合成和DNA聚合酶延伸创造条件；没有解旋酶，复制叉无法推进，DNA复制不能启动和持续。", "kp": "ch03_s2_11"}, {"id": "ch03_term_8", "modI": 2, "term": "Single-strand binding protein (SSBP)", "def": "单链结合蛋白：在复制过程中与暴露的DNA单链结合；防止两条单链重新退火或形成链内二级结构；保护单链不被核酸酶降解；与DNA结合无序列专一性，可覆盖较长单链；增强DNA聚合酶对单链DNA的亲和力，并与其他复制蛋白如解旋酶协同作用，促进复制顺利进行。", "kp": "ch03_s2_6"}, {"id": "ch03_term_9", "modI": 2, "term": "Primase", "def": "引物酶：以DNA为模板合成一段短RNA，为DNA聚合酶提供起始所需的3′-OH末端；其本质是以DNA为模板的RNA聚合酶，不需要引物即可起始合成；由于细胞内RNA引物易被降解，通常难以观察到完整引物，但它在复制起始中不可或缺，尤其在滞后链上需反复合成多个引物。", "kp": "ch03_s2_7"}, {"id": "ch03_term_10", "modI": 2, "term": "DNA topoisomerase", "def": "DNA拓扑异构酶：在复制过程中调节DNA的拓扑状态，使双螺旋保持松弛，避免解旋时产生过度超螺旋张力而阻碍复制叉前进；I型酶切开单链并改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶；保证复制、转录等过程正常进行，是维持基因组稳定性的关键酶类。", "kp": "ch03_s2_11"}, {"id": "ch03_term_11", "modI": 3, "term": "DNA polymerase", "def": "DNA聚合酶：以DNA为模板催化dNTP合成DNA；由Arthur Kornberg在大肠杆菌中发现，又称Kornberg酶；反应需要dNTPs、带游离3′-OH的模板-引物、DNA聚合酶本身以及Mg2+；只能沿5′→3′方向延伸，并具有校对功能；是DNA复制最核心的酶。", "kp": "ch03_s3_1"}, {"id": "ch03_term_12", "modI": 3, "term": "DNA ligase", "def": "DNA连接酶：催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键，从而连接相邻核苷酸，封闭切口；不能将两条游离的DNA单链连接起来，只能作用于双链DNA上的切口或黏性末端退火后的缺口；在DNA复制、修复和重组中不可或缺，也是基因工程中构建重组DNA的关键工具。", "kp": "ch03_s3_0"}], "preview": {"main": "本章围绕DNA复制这一遗传信息传递的核心过程展开，从半保留复制的证明入手，系统介绍复制的起点、方向、半不连续机制、相关酶与蛋白因子，并以大肠杆菌为例解析原核复制过程，最后延伸至真核生物复制特点及原核与真核的比较。", "questions": ["为什么说DNA复制是中心法则的起点？它如何保证遗传信息传递的准确性？", "Meselson-Stahl实验如何区分三种复制模型？为什么它的结果支持半保留复制？", "DNA聚合酶只能沿5′→3′方向合成，如何解决双链反向平行带来的复制难题？", "复制叉上需要哪些主要酶和蛋白因子？它们各自发挥什么功能？", "原核生物与真核生物在复制起点、复制方式和复制酶系上有哪些主要差异？", "DNA聚合酶的校对功能和滑动钳分别如何提高复制的保真性与持续合成能力？", "双链环状DNA的θ型、滚环型和D-环型复制各有什么特点？"]}, "appcards": [{"front": "比较弥散复制、半保留复制和全保留复制三种模型的核心差异，并说明Meselson-Stahl实验如何区分这三种模型。", "back": "三种模型的核心差异在于复制后亲代链与子代链的分配方式：①半保留复制：每个子代DNA一条链来自亲代，一条链为新合成；②全保留复制：亲代双链完整保留，子代双链全部新合成；③弥散复制：新旧片段随机分布。Meselson-Stahl实验用15N标记亲代DNA，转入14N培养基后密度梯度离心：若为全保留，第一代应出现重密度和轻密度两条带；若为弥散，第一代应只有一条介于重轻之间的带且随代数增加逐渐变轻；若为半保留，第一代全部为杂合密度，第二代出现杂合密度和轻密度各半。实验结果为第一代全部杂合密度、第二代杂合与轻密度各半，支持半保留复制，否定全保留和弥散复制。", "points": "三种模型分配方式差异；15N标记与密度梯度离心；各模型预期结果；实验实际结果；结论支持半保留复制", "mod": 0, "modName": "模块一：DNA复制概述与半保留复制", "level": "掌握", "src": "生成"}, {"front": "从中心法则的角度说明DNA复制为什么必须高度准确，并分析其准确性依赖哪些机制。", "back": "中心法则中DNA复制处于遗传信息流的起点：DNA通过复制传给子代DNA，再经转录传给RNA、翻译合成蛋白质。只有复制准确，转录和翻译才有可靠模板，才能维持物种遗传稳定性。准确性依赖多重机制：①碱基互补配对（G-C、A-T严格配对）保证序列决定关系；②DNA聚合酶的校对功能，可切除错误掺入的核苷酸；③错配修复系统纠正复制后残留错误。因此复制通常每10^10个碱基才出现一个错误，对基因组稳定性至关重要。", "points": "复制是中心法则起点；准确复制保证转录翻译模板可靠；维持遗传稳定性；碱基互补配对；聚合酶校对；错配修复；错误率低", "mod": 0, "modName": "模块一：DNA复制概述与半保留复制", "level": "掌握", "src": "生成"}, {"front": "举例说明DNA复制的一般特征，并解释前导链和后随链合成方式不同的原因。", "back": "DNA复制的一般特征包括：半保留复制、从复制起点起始、双向进行、需要多种因子协同（聚合酶、解旋酶、引发酶、拓扑异构酶等）。以大肠杆菌为例，复制从oriC起始双向进行。前导链和后随链合成方式不同的原因在于DNA双链方向相反而聚合酶只能沿5'→3'方向合成：①前导链模板方向与复制叉前进方向一致，可连续合成；②后随链模板方向与复制叉前进方向相反，只能不连续合成，形成多个冈崎片段，再连接成完整链。因此表现为半不连续复制。", "points": "半保留、起点起始、双向复制；多种酶和因子参与；聚合酶只能5'→3'合成；前导链连续；后随链不连续形成冈崎片段；半不连续复制", "mod": 0, "modName": "模块一：DNA复制概述与半保留复制", "level": "掌握", "src": "生成"}, {"front": "Meselson-Stahl实验为什么能证明半保留复制？请从实验设计、预期结果和实际结果三方面说明其应用价值。", "back": "实验设计：用15N标记大肠杆菌亲代DNA使其为重密度，再转入14N培养基中复制，用氯化铯密度梯度离心追踪DNA密度位置。预期结果：若全保留，第一代应出现重密度和轻密度两条带；若弥散，第一代应只有一条中间密度带并随代数逐渐变轻；若半保留，第一代全部为杂合密度，第二代杂合密度和轻密度各半。实际结果：第一代全部杂合密度，第二代杂合与轻密度各半，符合半保留复制预期。应用价值：该实验首次用同位素标记和密度梯度离心直接区分三种复制模型，为半保留复制提供经典证据，也展示了同位素示踪与离心技术在分子生物学研究中的应用。", "points": "15N标记亲代DNA；转入14N复制；氯化铯密度梯度离心；三种模型预期结果；实际第一代杂合、第二代杂合与轻各半；证明半保留复制；同位素示踪应用", "mod": 0, "modName": "模块一：DNA复制概述与半保留复制", "level": "掌握", "src": "生成"}, {"front": "为什么DNA复制会出现“半不连续复制”现象？请从DNA结构特点和酶学特性两方面解释原因。", "back": "①DNA双链反向平行，复制叉处两条模板链方向相反；②DNA聚合酶只能沿5′→3′方向合成新链，即只能将核苷酸加到3′-OH末端；③因此以3′→5′模板链为模板时可连续合成前导链；④以5′→3′模板链为模板时，只能反向、分段合成后随链；⑤后随链形成冈崎片段，再由DNA连接酶连接，故表现为一条链连续、另一条链不连续的半不连续复制。", "points": "反向平行；DNA聚合酶只能5′→3′合成；前导链连续；后随链不连续；冈崎片段及连接", "mod": 1, "modName": "模块二：复制的起点、方向与半不连续复制", "level": "掌握", "src": "生成"}, {"front": "真核生物为什么采用“多起点双向复制”的策略？这种策略有什么生物学意义？", "back": "①真核基因组庞大，若只有一个起点，S期难以在有限时间内完成复制；②每条染色体含多个复制子，每个复制子有自身复制起点；③每个起点向两侧双向复制，形成两个相反方向移动的复制叉；④相邻复制子复制叉相遇汇合，完成整条染色体复制；⑤意义：提高复制效率，使巨大线形染色体能在S期内完成复制；⑥便于复制调控和检查点监控，并保证每个复制子在一个细胞周期中只复制一次，维持基因组稳定性。", "points": "基因组庞大；多复制子/多起点；双向复制；复制叉汇合；提高效率；每周期只复制一次；基因组稳定", "mod": 1, "modName": "模块二：复制的起点、方向与半不连续复制", "level": "掌握", "src": "生成"}, {"front": "复制子、复制起点和复制叉之间是什么关系？请以真核染色体为例说明。", "back": "①复制起点是DNA上可被特异蛋白识别并启动复制的专一序列；②复制子是从一个复制起点到复制终点所组成的独立复制单位，一个复制子只含一个复制起点；③复制叉是复制时双链解开形成的Y形结构，是实际进行DNA合成的部位；④真核染色体由多个复制子组成，每个复制子有自己的起点；⑤复制时每个起点双向启动，形成两个复制叉；⑥相邻复制子的复制叉最终相遇汇合，完成整条染色体复制；⑦每个复制子在一个细胞周期中只复制一次。", "points": "起点定义；复制子定义；一个复制子一个起点；复制叉为Y形合成部位；真核多复制子；双向复制叉；汇合；每周期一次", "mod": 1, "modName": "模块二：复制的起点、方向与半不连续复制", "level": "掌握", "src": "生成"}, {"front": "冈崎片段的发现如何解决DNA反向平行与DNA聚合酶5′→3′合成方向之间的矛盾？请举例说明前导链和后随链的差异。", "back": "①矛盾：DNA双链反向平行，而DNA聚合酶只能沿5′→3′方向合成，不能从3′→5′方向连续合成；②冈崎片段模型提出：后随链先合成许多短的不连续片段；③这些片段再由DNA连接酶等连接成完整链；④因此复制叉整体向前移动时，一条链可连续合成，另一条链分段合成；⑤举例：以复制叉移动方向为准，前导链合成方向与复制叉移动方向一致，可连续合成；后随链合成方向与复制叉移动方向相反，不断形成冈崎片段；⑥原核生物冈崎片段约2000 nt，真核生物约100~200 nt；⑦该机制在生物界具有普遍性。", "points": "反向平行与5′→3′矛盾；冈崎片段；后随链分段合成；连接酶连接；前导链连续且同向；后随链反向不连续；原核约2000 nt；真核约100~200 nt；普遍性", "mod": 1, "modName": "模块二：复制的起点、方向与半不连续复制", "level": "掌握", "src": "生成"}, {"front": "为什么说DNA复制不是单一酶能完成的过程？请以复制叉处的协同作用为例说明。", "back": "DNA复制由多种物质协同完成，称为复制机器。解旋酶利用ATP解开双链；SSBP稳定单链、防止退火和二级结构；拓扑异构酶缓解正超螺旋张力；引物酶合成RNA引物提供3′-OH；DNA聚合酶沿模板延伸新链；dNTPs作为底物和能量来源。各因子在时间和空间上精密配合，缺一不可。", "points": "复制机器多组分；解旋酶解链；SSBP稳定单链；拓扑异构酶缓解张力；引物酶提供3′-OH；DNA聚合酶延伸；dNTPs底物供能；协同配合", "mod": 2, "modName": "模块三：DNA复制相关物质（起始与辅助蛋白）", "level": "掌握", "src": "生成"}, {"front": "DNA聚合酶为什么不能从头起始DNA合成？引物机制如何解决这一问题，其意义是什么？", "back": "DNA聚合酶只能将dNTP的α-磷酸加到游离3′-OH上，不能从头起始。引物酶以DNA为模板合成短RNA引物，提供游离3′-OH。DNA聚合酶从引物3′-OH开始延伸。复制后RNA引物被切除、由DNA填补并由连接酶连接。意义：保证DNA合成高效、准确起始，尤其在滞后链上需反复合成多个引物。", "points": "DNA聚合酶需3′-OH；不能从头起始；引物酶合成RNA引物；提供3′-OH；聚合酶延伸；引物切除与填补；连接酶连接；滞后链多引物；保证准确起始", "mod": 2, "modName": "模块三：DNA复制相关物质（起始与辅助蛋白）", "level": "掌握", "src": "生成"}, {"front": "dNTPs在DNA复制中既是底物又提供能量，请结合其结构和聚合反应说明。", "back": "dNTPs包括dATP、dTTP、dCTP、dGTP，由脱氧核糖、碱基和三个磷酸基团组成。复制时DNA聚合酶催化dNTP的α-磷酸与新生链3′-OH形成磷酸二酯键，同时释放焦磷酸PPi。dNTP既提供核苷酸单元，又通过磷酸酐键提供能量。其种类和浓度影响复制速度与保真度，反应需Mg2+并遵循碱基互补配对。", "points": "dNTP四种；脱氧核糖+碱基+三磷酸；α-磷酸与3′-OH成键；释放PPi；提供核苷酸单元；提供能量；Mg2+参与；碱基互补配对；影响速度与保真度", "mod": 2, "modName": "模块三：DNA复制相关物质（起始与辅助蛋白）", "level": "掌握", "src": "生成"}, {"front": "DNA拓扑异构酶在复制中有什么作用？请比较I型和II型酶，并举例说明。", "back": "拓扑异构酶调节DNA拓扑状态，使双螺旋保持松弛，避免解旋时正超螺旋积累阻碍复制叉前进。I型酶切开单链、改变连接数；II型酶切开双链且需消耗能量，如细菌促旋酶。它们通过瞬时切断、旋转和重新连接DNA骨架释放超螺旋张力，保证复制、转录正常进行，是维持基因组稳定性的关键酶类。", "points": "调节拓扑状态；保持松弛；避免正超螺旋阻碍复制叉；I型切单链；II型切双链耗能；细菌促旋酶举例；瞬时切断-旋转-重连；保证复制转录；维持基因组稳定性", "mod": 2, "modName": "模块三：DNA复制相关物质（起始与辅助蛋白）", "level": "掌握", "src": "生成"}, {"front": "比较大肠杆菌DNA聚合酶Ⅰ、Ⅱ、Ⅲ在聚合活性、外切活性和主要功能上的差异，并说明这种分工的意义。", "back": "Pol Ⅰ：中等5'→3'聚合活性，具3'→5'外切和5'→3'外切活性，主要切除RNA引物、填补空隙、修复损伤。Pol Ⅱ：聚合活性很低，主要参与修复。Pol Ⅲ：聚合活性很高，是复制主要酶，具3'→5'外切校对功能。意义：三者功能分工体现了复制与修复的协调，既保证染色体高效复制，又维持基因组稳定性。", "points": "Pol Ⅰ中等聚合+两种外切+切除引物/修复；Pol Ⅱ低聚合+修复；Pol Ⅲ高聚合+复制主要酶+3'→5'校对；分工体现复制与修复协调", "mod": 3, "modName": "模块四：DNA聚合酶与DNA连接酶", "level": "掌握", "src": "生成"}, {"front": "为什么DNA聚合酶能高效且高保真地合成DNA？请从催化方向、dNTP选择和校对机制三方面说明。", "back": "①合成方向为5'→3'，反应能量来自dNTP释放两个磷酸，保证链延伸方向明确；②聚合酶能“找到”正确互补dNTP，错误核苷酸掺入速率比正确者慢约10,000倍，体现高选择性；③具3'→5'外切活性，可切除错配核苷酸再重新掺入正确核苷酸，显著降低突变率。三者共同保证复制高效性与保真性。", "points": "5'→3'合成方向；dNTP释放两个磷酸供能；正确dNTP选择/错误掺入慢约10,000倍；3'→5'外切校对；高效性与保真性", "mod": 3, "modName": "模块四：DNA聚合酶与DNA连接酶", "level": "掌握", "src": "生成"}, {"front": "滑动钳为什么能显著提高DNA聚合酶的持续合成能力？其装载过程需要什么条件？这一机制对基因组复制有何意义？", "back": "滑动钳是环状蛋白，可套在DNA上并沿双链滑动，将DNA聚合酶锚定在模板上，防止其因合成而脱落；与无滑动钳时相比，可使持续合成能力提高数百至数千倍。装载时，滑动钳装载器利用ATP水解提供的能量，将环状滑动钳打开并套在DNA双链上，随后关闭，并定位在引物-模板接头处。意义：使聚合酶能连续合成数千个核苷酸，对复制叉高效延伸和基因组完整复制至关重要。", "points": "环状蛋白套在DNA上滑动；锚定聚合酶防止脱落；持续合成能力提高数百至数千倍；装载器利用ATP水解打开并装载；定位在引物-模板接头；保证复制叉高效延伸和基因组完整复制", "mod": 3, "modName": "模块四：DNA聚合酶与DNA连接酶", "level": "掌握", "src": "生成"}, {"front": "举例说明DNA连接酶的作用特点，并解释为什么它不能连接两条游离的DNA单链。", "back": "DNA连接酶催化双链DNA切口处3'-OH与5'-磷酸基之间形成磷酸二酯键，从而连接相邻核苷酸，封闭切口；反应需ATP或NAD+提供能量。它只能作用于双链DNA上的切口或黏性末端退火后的缺口，不能将两条游离的DNA单链连接起来，因为连接酶需要将3'-OH和5'-磷酸基相邻定位，而游离单链缺乏双链结构提供的正确空间位置。应用：DNA复制、修复和重组中不可或缺，也是基因工程中构建重组DNA的关键工具。", "points": "催化双链DNA切口处3'-OH与5'-磷酸形成磷酸二酯键；需ATP或NAD+供能；只能作用于双链DNA切口或退火后缺口；不能连接游离单链；原因：需将3'-OH和5'-磷酸相邻定位；应用于复制、修复、重组和基因工程", "mod": 3, "modName": "模块四：DNA聚合酶与DNA连接酶", "level": "掌握", "src": "生成"}, {"front": "比较θ型复制、滚环型复制和D-环型复制的主要区别，并说明它们分别适用于哪些DNA分子。", "back": "θ型复制：复制叉双向移动，中间体呈θ形，常见于细菌环状染色体和质粒；滚环型复制：一条链被切开产生3'-OH，以另一条环状链为模板滚动延伸，置换出单链，常见于ΦX174噬菌体等；D-环型复制：两条链复制起点不同且不同步，一条链迅速合成互补链，另一条链为游离单环，常见于动物线粒体DNA。", "points": "①θ型：双向复制、θ形中间体、细菌染色体/质粒；②滚环型：切链产生3'-OH、滚动延伸、噬菌体；③D-环型：复制起点不同、不同步、线粒体；④三者均保证遗传信息准确传递。", "mod": 4, "modName": "模块五：DNA复制的主要方式", "level": "掌握", "src": "生成"}, {"front": "为什么滚环型复制中正链合成不需要RNA引物，而负链合成是不连续复制？这一机制有何意义？", "back": "滚环型复制中，正链被切开后产生3'-OH，可直接作为延伸起点，因此不需要RNA引物；负链合成则依赖不连续复制机制。其意义在于：以切开链的3'-OH为起点可高效滚动合成多拷贝单链DNA，适应噬菌体等快速扩增遗传物质的需要。", "points": "①正链切开产生3'-OH；②3'-OH直接延伸，无需RNA引物；③负链不连续复制；④意义：高效扩增、产生多拷贝单链DNA、适应噬菌体繁殖。", "mod": 4, "modName": "模块五：DNA复制的主要方式", "level": "掌握", "src": "生成"}, {"front": "D-环型复制的分子机制是什么？为什么说它适应线粒体DNA的复制需求？", "back": "D-环型复制中，一条短RNA与一条DNA互补，取代原互补链，形成D-环；两条链复制起点不同且不同步，一条链迅速合成互补链，另一条链为游离单环。该方式首先在动物线粒体中发现，适应线粒体DNA较小、结构特殊且需要不对称复制的需求。", "points": "①短RNA与DNA互补；②取代原互补链形成D-环；③两条链复制起点不同、不同步；④一条链迅速合成，另一条为游离单环；⑤适应线粒体DNA复制需求。", "mod": 4, "modName": "模块五：DNA复制的主要方式", "level": "掌握", "src": "生成"}, {"front": "θ型复制中两个复制叉为什么以相反方向移动？这种双向复制方式有什么应用意义？", "back": "θ型复制从复制起始点开始，两个复制叉以相反方向沿染色体移动，形成θ形中间体。双向复制可同时从两个方向推进复制，提高复制效率，保证细菌环状染色体和质粒快速、准确地完成复制。", "points": "①从复制起始点开始；②两个复制叉相反方向移动；③形成θ形中间体；④提高复制效率；⑤保证遗传信息准确传递；⑥常见于细菌环状染色体和质粒。", "mod": 4, "modName": "模块五：DNA复制的主要方式", "level": "掌握", "src": "生成"}, {"front": "大肠杆菌DNA复制采用θ复制方式，且为双向复制。请比较前导链与后随链在合成方式上的主要差异，并说明这种差异对复制体协同工作的意义。", "back": "前导链沿复制叉前进方向连续合成，只需一个引物；后随链与复制叉前进方向相反，需不连续合成，形成多个冈崎片段，每个片段需单独合成RNA引物。二者由同一复制体协同完成，后随链模板形成环状结构（长号模型），使两条链能够同时、协同合成，体现了复制机器的高度组织性和高效性。", "points": "前导链连续合成、一个引物；后随链不连续合成、多个冈崎片段、多个引物；同一复制体协同；长号模型/环状结构；高效性", "mod": 5, "modName": "模块六：大肠杆菌DNA复制的过程", "level": "掌握", "src": "生成"}, {"front": "大肠杆菌复制起点oriC中，9 bp重复序列和13 bp重复序列在复制起始中分别发挥什么作用？为什么说oriC的结构决定了复制起始的精确性？", "back": "9 bp重复序列（共4个）是起始蛋白DnaA的结合位点，DnaA识别并结合后形成起始复合物；13 bp重复序列（共3个，富含AT）是DNA解旋的起始区域，容易被解链。DnaA结合后促使13 bp区域解链，随后DnaB解旋酶被加载，引发复制起始。oriC中这两类重复序列的排列和数量使DnaA能够精确识别和激活起点，从而保证复制起始的精确性和双向性。", "points": "9 bp重复序列为DnaA结合位点；13 bp重复序列富含AT、为解旋起始区；DnaA结合后促使13 bp解链；DnaB加载；保证起始精确性和双向性", "mod": 5, "modName": "模块六：大肠杆菌DNA复制的过程", "level": "掌握", "src": "生成"}, {"front": "大肠杆菌复制终止区含有Ter序列，Tus蛋白与之结合形成Ter-Tus复合物。请说明Ter-Tus复合物为什么具有方向性，以及这种方向性对复制终止的意义。", "back": "Tus蛋白是一种反解旋酶，识别Ter序列并结合形成Ter-Tus复合物，抑制DnaB解旋酶的ATP依赖性解旋活性，阻止复制叉前移。Ter-Tus复合物具有方向性：允许复制叉从一个方向通过，而阻止从相反方向到达的复制叉。这种方向性将两个复制叉限制在终止区内相遇，保证复制终止的精确性，防止复制叉越过终止区继续前行。", "points": "Tus为反解旋酶；识别Ter并结合；抑制DnaB解旋活性；方向性：允许一个方向通过、阻止相反方向；将两个复制叉限制在终止区相遇；保证终止精确性", "mod": 5, "modName": "模块六：大肠杆菌DNA复制的过程", "level": "掌握", "src": "生成"}, {"front": "大肠杆菌环状染色体复制完成后，两个子代DNA分子相互缠绕，需要II型拓扑异构酶参与分离。请举例说明这一步骤的意义，并解释为什么它是复制完成的最后关键环节。", "back": "当两个复制叉在终止区相遇后，子代DNA分子相互缠绕，形成连锁环状DNA。II型拓扑异构酶（如DNA旋转酶）切开并重新连接DNA链，使两个子代环状DNA分子彼此分离。若没有这一步骤，子代DNA无法正常分离，遗传信息不能准确分配给子代细胞。因此该步骤是复制完成的最后关键环节，确保遗传信息准确传递。", "points": "复制叉在终止区相遇后子代DNA相互缠绕；II型拓扑异构酶/DNA旋转酶切开并重新连接；使两个子代环状DNA分离；保证遗传信息准确分配；复制完成的最后环节", "mod": 5, "modName": "模块六：大肠杆菌DNA复制的过程", "level": "掌握", "src": "生成"}, {"front": "比较原核生物与真核生物DNA复制的特点，并说明真核生物为何需要解决末端复制问题。", "back": "原核生物：基因组小、环状DNA、单复制起点、复制与细胞周期耦联较简单，无末端复制问题。真核生物：基因组大、多条线性染色体、多复制起点、起点激活有时序性、每个细胞周期只复制一次、需解决线性DNA末端复制难题。末端复制问题原因：DNA聚合酶需要RNA引物且只能5'→3'合成，去除末端RNA引物后子链5'端无法填补，导致每轮复制染色体末端缩短。", "points": "原核与真核对比（基因组大小/环状vs线性/单起点vs多起点）；真核每周期只复制一次；末端复制问题机制（RNA引物去除+5'端无法填补→末端缩短）", "mod": 6, "modName": "模块七：真核生物DNA复制特点与端粒", "level": "掌握", "src": "生成"}, {"front": "真核生物如何保证每个染色体在每个细胞周期中只复制一次？请从起点许可角度说明其机制及意义。", "back": "机制：M期后CDK活性低，ORC结合起点，Cdc6和Cdt1协助MCM2-7装载，形成pre-RC，获得复制许可；S期CDK和DDK激活MCM，起始复制，同时高CDK活性抑制新的pre-RC组装，使起点失去许可；G2/M期保持高CDK活性，直到下一周期重新许可。意义：防止同一周期内同一起点再次启动，避免复制过度导致基因扩增和基因组不稳定；同时保证复制不足时染色体断裂风险被控制。", "points": "M期后低CDK→pre-RC组装（ORC+Cdc6+Cdt1+MCM）；S期CDK/DDK激活MCM并抑制新pre-RC；每周期只许可一次；意义：防再复制/基因组稳定", "mod": 6, "modName": "模块七：真核生物DNA复制特点与端粒", "level": "掌握", "src": "生成"}, {"front": "端粒酶如何解决末端复制问题？请结合其结构和作用机制说明，并举例说明端粒酶活性与疾病或应用的关系。", "back": "结构：端粒酶是RNA-蛋白质复合物，RNA含与端粒重复互补的模板，TERT具逆转录酶活性。机制：端粒酶RNA模板与染色体3'端端粒重复配对，以逆转录方式延伸3'末端，合成新端粒重复；端粒酶移位可多轮延伸；延长后的3'端为常规DNA聚合酶提供模板，合成互补链，补偿末端引物去除造成的缩短。举例：约90%人类肿瘤端粒酶高度活跃，维持端粒获得无限增殖，是癌症治疗靶点；干细胞、生殖细胞等也有活性；端粒酶抑制或激活与衰老研究相关。", "points": "端粒酶结构（RNA模板+TERT逆转录酶）；延伸3'端机制；移位多轮延伸；为常规复制提供模板；举例：肿瘤90%高活性/治疗靶点/干细胞生殖细胞", "mod": 6, "modName": "模块七：真核生物DNA复制特点与端粒", "level": "掌握", "src": "生成"}, {"front": "端粒T环结构有什么功能？请说明其保护染色体末端的机制，并解释端粒长度与细胞衰老及癌症的关系。", "back": "T环功能：端粒3'端单链侵入端粒双链区形成套索状T环，使染色体末端被隐藏，不被识别为DNA双链断裂；TRF2等端粒结合蛋白参与形成和维持，防止末端融合和降解。端粒长度与衰老：端粒过短或失去保护会被识别为DNA损伤，激活DNA损伤反应，使细胞衰老或停止分裂；端粒酶可维持端粒长度。与癌症：许多癌细胞重新激活端粒酶，维持端粒长度并获得无限增殖能力。", "points": "T环形成（3'端侵入双链）；隐藏末端/防识别为DSB；TRF2参与；端粒过短→DNA损伤反应→衰老；癌细胞端粒酶激活→无限增殖", "mod": 6, "modName": "模块七：真核生物DNA复制特点与端粒", "level": "掌握", "src": "生成"}, {"front": "比较原核生物与真核生物DNA复制的主要异同，并说明理解这些差异对医学应用的意义。", "back": "相同点：均为半保留复制、半不连续复制；都需要解旋酶、单链结合蛋白、RNA引物及校对机制。不同点：原核通常只有一个复制起点，复制子大且单一，复制周期与细胞周期不重叠，速度快，冈崎片段较长，无端粒和端粒酶，DNA聚合酶种类少，无核小体；真核有多个复制起点，复制子小且多，复制周期与细胞周期严格重叠，速度慢，冈崎片段较短，有端粒和端粒酶，DNA聚合酶种类多，DNA缠绕在核小体上。意义：这些差异是开发选择性抗癌、抗病毒药物的重要基础，例如利用真核细胞周期特点设计细胞周期特异性药物。", "points": "相同点（半保留、半不连续、关键酶和蛋白）；不同点（起点数目、复制子、细胞周期关系、速度、冈崎片段长度、端粒/端粒酶、聚合酶种类、核小体）；医学意义（药物靶点选择性）", "mod": 7, "modName": "模块八：原核与真核复制比较及医学联系", "level": "掌握", "src": "生成"}, {"front": "为什么肿瘤细胞和病毒对DNA复制抑制剂更敏感？请结合复制机制和药物靶点举例说明。", "back": "肿瘤细胞和病毒往往增殖迅速，DNA复制频繁，因此对DNA复制抑制剂更敏感。药物策略包括：1）靶向核苷酸前体合成，使DNA聚合酶缺乏底物，如5-FU抑制嘧啶合成、6-MP抑制嘌呤合成；2）直接靶向DNA合成，如AraC转化为三磷酸形式竞争性抑制DNA聚合酶，并可掺入DNA导致链终止或复制错误；3）损伤DNA阻断复制，如顺铂与鸟嘌呤N7位共价结合形成交联，阻断复制和转录，诱导凋亡。但也会影响正常快速分裂细胞，需注意副作用。", "points": "肿瘤/病毒增殖快、复制频繁；三类策略（前体类似物、直接抑制聚合酶、损伤DNA）；具体药物（5-FU、6-MP、AraC、顺铂）；副作用原因（正常快速分裂细胞也受影响）", "mod": 7, "modName": "模块八：原核与真核复制比较及医学联系", "level": "掌握", "src": "生成"}, {"front": "以5-FU、AraC和顺铂为例，比较它们靶向DNA复制的方式及临床应用的差异。", "back": "5-FU是核苷酸前体类似物，通过抑制嘧啶合成使DNA聚合酶缺乏底物，属于抗代谢类，主要用于消化道肿瘤等。AraC是胞苷类似物，在体内转化为三磷酸形式，竞争性抑制DNA聚合酶并可作为底物掺入DNA，导致链终止或复制错误，主要用于急性髓系白血病，属于细胞周期特异性药物。顺铂是铂类化合物，与DNA鸟嘌呤N7位共价结合形成链内或链间交联，使DNA双链扭曲，阻断复制和转录，诱导凋亡，广泛用于睾丸癌、卵巢癌、肺癌等实体瘤，作用不依赖细胞周期，但有肾毒性和神经毒性。", "points": "5-FU：前体类似物、抑制嘧啶合成、消化道肿瘤；AraC：胞苷类似物、抑制聚合酶/掺入DNA、急性髓系白血病、细胞周期特异性；顺铂：铂类、DNA交联、阻断复制转录、实体瘤、不依赖细胞周期、肾毒性/神经毒性", "mod": 7, "modName": "模块八：原核与真核复制比较及医学联系", "level": "掌握", "src": "生成"}, {"front": "原核与真核复制叉关键蛋白的对应关系体现了什么进化特点？请举例说明并解释其意义。", "back": "原核与真核复制叉关键蛋白存在对应关系：解旋酶DnaB对应CMG；单链结合蛋白SSB对应RPA；DNA聚合酶III对应Pol ε/Pol δ；β夹钳对应PCNA；夹钳装载机对应RFC；引物酶对应Pol α–引物酶；去除引物的Pol I对应RNase H和FEN1等；连接酶对应DNA连接酶I。这体现了复制机制在进化上的高度保守性，同时真核生物复制更加复杂，涉及更多蛋白和调控因素。意义：保守性说明基本复制原理通用，复杂性解释真核复制调控更精细，也为以复制叉蛋白为靶点的药物设计提供依据。", "points": "对应关系举例（DnaB-CMG、SSB-RPA、Pol III-Pol ε/δ、β夹钳-PCNA、RFC、引物酶、Pol I-RNase H/FEN1、连接酶）；进化保守性；真核更复杂；意义（原理通用、调控精细、药物靶点）", "mod": 7, "modName": "模块八：原核与真核复制比较及医学联系", "level": "掌握", "src": "生成"}]};